import { Directive, ElementRef, HostListener, Input } from "@angular/core";
import { TooltipOptions } from "../models/tooltip.interface";
import { TooltipService } from "../services/tooltip.service";

/**
 * ### Basic
 * `<div epTooltip="Your tooltip text"></div>`
 * or
 * `<div [epTooltip]="tooltipTextProp"></div>`
 *
 *
 * ### Multi-line
 * `<div epTooltip="Line 1
 *                  Line 2
 *                      Line 3"></div>`
 *
 *
 * ### Advanced Options
 * `<div epTooltip="Text" [tooltipOptions]="{ delay: 500 }">...</div>`
 * or more
 * `<div
 *		epTooltip="Text"
 *		[tooltipOptions]="{ position: 'bottom', altPosition: 'left', align: 'center', delay: 500, width: 200, maxWidth: 400, offset: { top: 10, left: 10 } }"
 *	>...</div>`
 *
 * ### Using in .ts
 * Look at the `TooltipService` for programmatic usage.
 */
@Directive({
    selector: "[epTooltip]",
    standalone: true,
})
export class TooltipDirective {
    @Input("epTooltip") text = "";
    @Input() tooltipOptions: TooltipOptions = {};

    constructor(
        private el: ElementRef<HTMLElement>,
        private tooltipService: TooltipService
    ) {}

    @HostListener("mouseenter")
    onMouseEnter(): void {
        if (this.text) {
            this.tooltipService.show(this.el.nativeElement, this.text, this.tooltipOptions);
        }
    }

    @HostListener("mouseleave")
    onMouseLeave(): void {
        this.tooltipService.hide(this.el.nativeElement);
    }

    @HostListener("click")
    onClick(): void {
        this.tooltipService.hide(this.el.nativeElement, true);
    }
}
