import {
    AfterViewChecked,
    Directive,
    ElementRef,
    Input,
    NgZone,
    OnChanges,
    SimpleChanges,
} from "@angular/core";

@Directive({
    selector: "[epAutoScroll]",
})
export class AutoScrollDirective implements AfterViewChecked, OnChanges {
    @Input() epAutoScroll: boolean = true;
    @Input() scrollThreshold: number = 100;

    private shouldScroll: boolean = false;

    constructor(
        private elementRef: ElementRef<HTMLElement>,
        private ngZone: NgZone
    ) {}

    ngOnChanges(changes: SimpleChanges): void {
        if (changes["epAutoScroll"] && this.epAutoScroll) {
            this.markForScroll();
        }
    }

    ngAfterViewChecked(): void {
        if (this.shouldScroll && this.epAutoScroll) {
            this.scrollToBottom();
            this.shouldScroll = false;
        }
    }

    scrollToBottom(): void {
        this.ngZone.runOutsideAngular(() => {
            setTimeout(() => {
                const element = this.elementRef.nativeElement;
                if (!element) return;

                const isNearBottom =
                    element.scrollHeight - element.scrollTop - element.clientHeight <
                    this.scrollThreshold;

                if (isNearBottom || this.shouldScroll) {
                    element.scrollTop = element.scrollHeight;
                }
            }, 100);
        });
    }

    markForScroll(): void {
        this.shouldScroll = true;
    }
}
