import { MarkedRenderer } from "ngx-markdown";

const MAX_HIGHLIGHT_CODE_LENGTH = 12000;
const MAX_HIGHLIGHT_CODE_LINES = 400;

function escapeHtml(value: string): string {
    return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function normalizeLanguage(raw: string): string {
    return raw.trim().split(/\s+/)[0]?.toLowerCase() || "";
}

function sanitizeLanguage(value: string): string {
    if (!value) return "text";
    const safe = value.replace(/[^a-z0-9+-]/gi, "").toLowerCase();
    return safe || "text";
}

const HTML_TAG_RE = /<\/?[a-zA-Z][a-zA-Z0-9]*[\s>/]/;
const CSS_RULE_RE = /[a-zA-Z#.:*[\]]+\s*\{[\s\S]*?\}/;
const JSON_RE = /^\s*[{[]/;
const PYTHON_RE = /^(?:def |class |import |from \w+ import |elif |async def |@\w+\n)/m;

function autoDetectLanguage(code: string): string {
    if (HTML_TAG_RE.test(code)) return "html";
    if (JSON_RE.test(code)) {
        try {
            JSON.parse(code);
            return "json";
        } catch {
            /* not json */
        }
    }
    if (PYTHON_RE.test(code)) return "python";
    if (CSS_RULE_RE.test(code)) return "css";
    return "text";
}

function resolveLanguage(raw: string | undefined, code: string): string {
    const normalized = normalizeLanguage(raw ?? "");
    const resolved = normalized || autoDetectLanguage(code);
    return sanitizeLanguage(resolved);
}

function parseCodeRendererArgs(
    tokenOrCode: unknown,
    languageOrOptions?: unknown
): { code: string; language: string } {
    if (typeof tokenOrCode === "string") {
        const code = tokenOrCode;
        const rawLang = typeof languageOrOptions === "string" ? languageOrOptions : "";
        return { code, language: resolveLanguage(rawLang, code) };
    }

    if (tokenOrCode && typeof tokenOrCode === "object") {
        const token = tokenOrCode as { text?: string; raw?: string; lang?: string };
        const code = typeof token.text === "string" ? token.text : (token.raw ?? "");
        return { code, language: resolveLanguage(token.lang, code) };
    }

    return { code: "", language: "text" };
}

/**
 * Factory function to create marked options with custom link renderer
 * Configures markdown to open links in new tab with security attributes
 */
export function markedOptionsFactory() {
    const renderer = new MarkedRenderer();
    let codeBlockCounter = 0;

    renderer.link = ({ href, title, tokens }) => {
        if (!href) {
            return tokens ? tokens.map((t) => t.raw).join("") : "";
        }
        const titleAttr = title ? ` title="${title}"` : "";
        const text = tokens ? tokens.map((t) => t.raw).join("") : href;
        return `<a href="${href}"${titleAttr} target="_blank" rel="noopener noreferrer">${text}</a>`;
    };

    renderer.code = ((tokenOrCode: unknown, languageOrOptions?: unknown) => {
        const parsed = parseCodeRendererArgs(tokenOrCode, languageOrOptions);
        const trimmedCode = parsed.code.replace(/\n$/, "");
        const escapedCode = escapeHtml(trimmedCode);
        const lines = trimmedCode.split("\n").length;
        const isLargeCode =
            trimmedCode.length > MAX_HIGHLIGHT_CODE_LENGTH || lines > MAX_HIGHLIGHT_CODE_LINES;
        const language = isLargeCode ? "text" : sanitizeLanguage(parsed.language);
        const displayLanguage = escapeHtml(language.toUpperCase());
        const codeId = `ep-md-code-${codeBlockCounter++}`;
        const blockClasses = isLargeCode ? "ep-md-code ep-md-code--plain" : "ep-md-code";

        return `
                <div class="${blockClasses}">
                <div class="ep-md-code__header">
                    <span class="ep-md-code__lang">${displayLanguage}</span>
                    <span
                    class="ep-md-code__copy-icon"
                    data-copy-target="${codeId}"
                    role="button"
                    tabindex="0"
                    aria-label="Copy code"
                    title="Copy code"
                    ></span>
                </div>
                <pre><code id="${codeId}" class="language-${language}">${escapedCode}</code></pre>
                </div>
                `;
    }) as typeof renderer.code;

    return {
        renderer: renderer,
        gfm: true,
        breaks: true,
    };
}
