import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    Component,
    Input,
    OnChanges,
    OnDestroy,
    SimpleChanges,
} from "@angular/core";
import { IconComponent } from "../shared/icon/icon.component";

@Component({
    selector: "ep-thinking-expander",
    standalone: true,
    imports: [CommonModule, IconComponent],
    templateUrl: "./thinking-expander.component.html",
    styleUrls: ["./thinking-expander.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ThinkingExpanderComponent implements OnChanges, OnDestroy {
    @Input() entries: string[] = [];
    @Input() isActive = false;
    @Input() startedAtUnixSeconds?: number | null;
    @Input() endedAtUnixSeconds?: number | null;

    expanded = false;
    elapsedSeconds = 0;

    private startedAtMs: number | null = null;
    private tickTimerId: ReturnType<typeof setInterval> | null = null;
    private expandedIndex: number | null = null;

    get hasEntries(): boolean {
        return this.entries.length > 0;
    }

    get latestEntry(): string {
        if (!this.hasEntries) return "";
        return this.entries[this.entries.length - 1];
    }

    get latestSummary(): string {
        return this.getSummary(this.latestEntry);
    }

    get elapsedLabel(): string {
        return this.elapsedSeconds < 1 ? "<1s" : `${this.elapsedSeconds}s`;
    }

    toggleExpanded(): void {
        this.expanded = !this.expanded;
        if (!this.expanded) {
            this.expandedIndex = null;
        }
    }

    toggleItem(index: number): void {
        this.expandedIndex = this.expandedIndex === index ? null : index;
    }

    isItemExpanded(index: number): boolean {
        return this.expandedIndex === index;
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes["startedAtUnixSeconds"]) {
            this.startedAtMs =
                this.startedAtUnixSeconds != null ? this.startedAtUnixSeconds * 1000 : null;
        }

        if (changes["isActive"]) {
            if (this.isActive) {
                this.expanded = true;
                this.startTimer();
            } else {
                this.stopTimer();
                this.expanded = false;
                this.computeElapsedFromDates();
            }
        }

        // Handles initial render with isActive=false (page reload) — recompute when timestamps arrive
        if (!this.isActive && (changes["startedAtUnixSeconds"] || changes["endedAtUnixSeconds"])) {
            this.computeElapsedFromDates();
        }
    }

    ngOnDestroy(): void {
        this.stopTimer();
    }

    private startTimer(): void {
        this.stopTimer();
        this.updateElapsed();
        this.tickTimerId = setInterval(() => this.updateElapsed(), 1000);
    }

    private stopTimer(): void {
        if (this.tickTimerId) {
            clearInterval(this.tickTimerId);
            this.tickTimerId = null;
        }
    }

    private computeElapsedFromDates(): void {
        if (this.startedAtUnixSeconds != null && this.endedAtUnixSeconds != null) {
            this.elapsedSeconds = Math.max(0, this.endedAtUnixSeconds - this.startedAtUnixSeconds);
        }
    }

    private updateElapsed(): void {
        if (!this.isActive) return;
        if (this.startedAtMs == null) {
            this.elapsedSeconds += 1;
            return;
        }

        const delta = Math.floor((Date.now() - this.startedAtMs) / 1000);
        this.elapsedSeconds = Math.max(0, delta);
    }

    summary(entry: string): string {
        return this.getSummary(entry);
    }

    private getSummary(entry: string): string {
        const full = entry || "";
        const firstLine = full.split(/\r?\n/)[0] ?? "";
        const raw = firstLine.trim();
        const maxLength = 120;
        const hasMoreLines = full.includes("\n");

        if (!hasMoreLines && raw.length <= maxLength) {
            return raw;
        }

        const base = raw.length > maxLength ? raw.slice(0, maxLength - 1).trimEnd() : raw.trimEnd();
        return base ? `${base}…` : "";
    }
}
