import { HttpClient } from "@angular/common/http";
import { computed, Injectable, signal } from "@angular/core";
import { firstValueFrom } from "rxjs";
import { STORAGE_KEYS } from "../constants/storage.constants";
import { Agent, EpicstaffAgent } from "../models/epicstaff-agent.model";
import { generateAgentId } from "../utils/message.utils";
import { StorageService } from "./storage.service";

interface GraphLightResponse {
    results: Array<{
        id: number;
        name: string;
        description: string;
        tags: unknown[];
        epicchat_enabled: boolean;
    }>;
}

/**
 * Сервис для управления Epicstaff агентами
 * Отвечает за:
 * - CRUD операции с агентами (создание, обновление, удаление)
 * - Управление текущим выбранным агентом
 * - Сохранение/загрузку агентов из storage
 * - Инициализацию агентов при старте приложения
 *
 * НЕ отвечает за:
 * - HTTP запросы к API (см. ApiService)
 * - Отправку сообщений (см. ApiService.sendMessage)
 */
@Injectable({
    providedIn: "root",
})
export class EpicstaffAgentService {
    private agentsSignal = signal<Agent[]>([]);
    public readonly agents = this.agentsSignal.asReadonly();

    private currentAgentSignal = signal<Agent | null>(null);
    public readonly currentAgent = this.currentAgentSignal.asReadonly();

    /**
     * Agents visible in the UI.
     * When real (API-connected) agents exist, the default Virtual Assistant is hidden.
     */
    public readonly visibleAgents = computed(() => {
        const all = this.agentsSignal();
        const hasRealAgents = all.some(
            (a) => a.epicstaffFlowId !== null && a.epicstaffFlowId !== undefined
        );
        return hasRealAgents
            ? all.filter((a) => a.epicstaffFlowId !== null && a.epicstaffFlowId !== undefined)
            : all;
    });

    private defaultImagePath = "";

    constructor(
        private http: HttpClient,
        private storageService: StorageService
    ) {
        this.loadAgents();
    }

    loadAgents(): void {
        const storedAgents = this.loadAgentsFromStorage();

        if (storedAgents.length > 0) {
            this.agentsSignal.set(storedAgents);
        }
    }

    initializeCurrentAgent(): void {
        this.loadCurrentAgent();
    }

    // getAgents(): Observable<EpicstaffAgent[]> {
    //     // TODO: Заменить на реальный API endpoint если агенты хранятся на беке (как в  Эпике)
    //     // return this.http.get<EpicstaffAgent[]>('/api/epicstaff-agents');
    //     return of([]);
    // }

    createAgent(
        agent: EpicstaffAgent,
        options?: { selectAfterCreate?: boolean; source?: "sync" | "manual" }
    ): void {
        const agentId = agent.id ?? generateAgentId();
        const assistantMode: Agent = {
            mode: "epicstaff",
            name: agent.agent_name,
            description: agent.agent_description,
            imagePath: agent.imagePath || this.defaultImagePath,
            epicstaffAgentId: agentId,
            epicstaffFlowId: agent.flow_id,
            epicstaffFlowUrl: agent.url,
            source: options?.source ?? "manual",
        };

        this.agentsSignal.update((current) => [...current, assistantMode]);

        this.saveAgentsToStorage();

        if (options?.selectAfterCreate) {
            this.setCurrentAgent(assistantMode);
        }
    }

    updateAgent(agent: EpicstaffAgent): void {
        const existingAgent = this.agents().find((a) => a.epicstaffAgentId === agent.id);

        if (!existingAgent) {
            console.warn("Agent not found for update:", agent.id);
            return;
        }

        const updatedAgent: Agent = {
            ...existingAgent,
            name: agent.agent_name,
            description: agent.agent_description,
            epicstaffAgentId: agent.id ?? existingAgent.epicstaffAgentId,
            epicstaffFlowId: agent.flow_id,
            epicstaffFlowUrl: agent.url,
            imagePath: agent.imagePath || existingAgent.imagePath,
        };

        this.agentsSignal.update((current) => {
            const index = current.findIndex(
                (a) => a.epicstaffAgentId === existingAgent.epicstaffAgentId
            );
            if (index !== -1) {
                const updated = [...current];
                updated[index] = updatedAgent;
                return updated;
            }
            return current;
        });

        if (this.currentAgent()?.epicstaffAgentId === existingAgent.epicstaffAgentId) {
            this.setCurrentAgent(updatedAgent);
        }

        this.saveAgentsToStorage();
    }

    deleteAgent(agentId: number | string): void {
        const numericId = typeof agentId === "string" ? Number(agentId) : agentId;
        const agentToDelete = this.agents().find((a) => a.epicstaffAgentId === numericId);

        if (!agentToDelete) {
            console.warn("Agent not found for deletion:", agentId);
            return;
        }

        this.agentsSignal.update((current) =>
            current.filter((a) => a.epicstaffAgentId !== agentToDelete.epicstaffAgentId)
        );

        if (this.currentAgent()?.epicstaffAgentId === agentToDelete.epicstaffAgentId) {
            const remaining = this.agents();
            const nextAgent =
                remaining.find(
                    (a) => a.epicstaffFlowId !== null && a.epicstaffFlowId !== undefined
                ) ??
                remaining[0] ??
                null;
            this.setCurrentAgent(nextAgent);
        }

        this.saveAgentsToStorage();
    }

    setAgents(agents: Agent[]): void {
        this.agentsSignal.set(agents);
        this.saveAgentsToStorage();
    }

    setCurrentAgent(agent: Agent | null): void {
        this.currentAgentSignal.set(agent);
        if (agent) {
            this.storageService.setItem(
                STORAGE_KEYS.EPICSTAFF_AGENT_ID,
                String(agent.epicstaffAgentId)
            );
        } else {
            this.storageService.removeItem(STORAGE_KEYS.EPICSTAFF_AGENT_ID);
        }
    }

    switchAgentByFlow(flowId: number | string | null | undefined, flowUrl?: string): Agent | null {
        const normalizedFlowIdRaw =
            flowId === null || flowId === undefined || flowId === "" ? null : Number(flowId);
        const normalizedFlowId =
            normalizedFlowIdRaw !== null && Number.isFinite(normalizedFlowIdRaw)
                ? normalizedFlowIdRaw
                : null;
        const normalizedUrl = (flowUrl || "").trim();

        const targetAgent =
            this.agents().find((agent) => {
                const matchesFlowId =
                    normalizedFlowId === null || agent.epicstaffFlowId === normalizedFlowId;
                const matchesUrl = !normalizedUrl || agent.epicstaffFlowUrl === normalizedUrl;
                return matchesFlowId && matchesUrl;
            }) || null;

        if (targetAgent) {
            this.setCurrentAgent(targetAgent);
        }

        return targetAgent;
    }

    /**
     * Sync agents from backend API.
     * Fetches flows with epicchat_enabled=true and creates/updates/removes agents accordingly.
     * Agents with epicstaffFlowId === null are not managed by the API and are left untouched.
     */
    async syncAgentsFromApi(apiBaseUrl: string): Promise<void> {
        const url = apiBaseUrl.endsWith("/")
            ? `${apiBaseUrl}graph-light/?epicchat_enabled=true`
            : `${apiBaseUrl}/graph-light/?epicchat_enabled=true`;

        try {
            const response = await firstValueFrom(this.http.get<GraphLightResponse>(url));
            const flows = response?.results || [];
            const flowIds = new Set(flows.map((f) => f.id));
            const existingAgents = this.agents();

            // Create or update agents from API response
            for (const flow of flows) {
                const existing = existingAgents.find((a) => a.epicstaffFlowId === flow.id);

                if (!existing) {
                    // Create new agent
                    this.createAgent(
                        {
                            agent_name: flow.name,
                            agent_description: flow.description || "",
                            flow_id: flow.id,
                            url: apiBaseUrl,
                        },
                        { selectAfterCreate: false, source: "sync" }
                    );
                } else if (
                    existing.name !== flow.name ||
                    existing.description !== (flow.description || "")
                ) {
                    // Update name/description if changed
                    this.agentsSignal.update((current) =>
                        current.map((a) =>
                            a.epicstaffAgentId === existing.epicstaffAgentId
                                ? { ...a, name: flow.name, description: flow.description || "" }
                                : a
                        )
                    );
                    if (this.currentAgent()?.epicstaffAgentId === existing.epicstaffAgentId) {
                        this.currentAgentSignal.update((curr) =>
                            curr
                                ? {
                                      ...curr,
                                      name: flow.name,
                                      description: flow.description || "",
                                  }
                                : curr
                        );
                    }
                }
            }

            // Remove only sync agents whose flowId is no longer in the API response
            const agentsToRemove = this.agents().filter(
                (a) =>
                    a.source === "sync" &&
                    a.epicstaffFlowId !== null &&
                    a.epicstaffFlowId !== undefined &&
                    !flowIds.has(a.epicstaffFlowId)
            );
            for (const agent of agentsToRemove) {
                this.deleteAgent(agent.epicstaffAgentId);
            }

            this.saveAgentsToStorage();
        } catch (error) {
            console.error("Failed to sync agents from API:", error);
        }
    }

    private loadCurrentAgent(): void {
        const savedAgentId = this.storageService.getItem(STORAGE_KEYS.EPICSTAFF_AGENT_ID);
        if (savedAgentId) {
            const agentId = Number(savedAgentId);
            const agent = this.agents().find((a) => a.epicstaffAgentId === agentId);
            if (agent) {
                this.setCurrentAgent(agent);
            }
        }
    }

    private saveAgentsToStorage(): void {
        const agents = this.agents();
        try {
            this.storageService.setItemAsJSON(STORAGE_KEYS.EPICSTAFF_AGENTS, agents);
        } catch (error) {
            console.error("Failed to save agents to storage:", error);
        }
    }

    private loadAgentsFromStorage(): Agent[] {
        try {
            const stored = this.storageService.getItemAsJSON<Agent[]>(
                STORAGE_KEYS.EPICSTAFF_AGENTS
            );
            if (stored && Array.isArray(stored)) {
                return stored.map((agent) => {
                    if (!agent.epicstaffAgentId) {
                        agent.epicstaffAgentId = generateAgentId();
                    }
                    if (!agent.source) {
                        agent.source = "manual";
                    }
                    return agent;
                });
            }
            return [];
        } catch (error) {
            console.error("Failed to load agents from storage:", error);
            return [];
        }
    }
}
