/**
 * Utility functions for message operations
 */

/**
 * Generate a random string ID
 * Improved version with better uniqueness
 */
export function generateMessageId(): string {
    // Use timestamp + random for better uniqueness
    return `msg_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

/**
 * Convert Unix timestamp (seconds) to Date object
 */
export function timestampToDate(timestamp: number): Date {
    return new Date(timestamp * 1000);
}

/**
 * Get current Unix timestamp in seconds
 */
export function getCurrentTimestamp(): number {
    return Math.floor(Date.now() / 1000);
}

/**
 * Generate a unique numeric ID for an agent
 * Uses timestamp + random number to ensure uniqueness
 */
export function generateAgentId(): number {
    // Генерируем число на основе timestamp и случайного числа
    // Используем только положительные числа
    return Math.floor(Date.now() / 1000) * 1000 + Math.floor(Math.random() * 1000);
}
