import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    Component,
    computed,
    effect,
    HostListener,
    Injectable,
    OnDestroy,
    OnInit,
    input,
    output,
    signal,
} from "@angular/core";
import { MarkdownComponent } from "ngx-markdown";
import { UserActionType } from "../../models/action.enum";
import { Action, EpMessage } from "../../models/message.model";
import { EpTable } from "../../models/table.model";
import { ActionService } from "../../services/action.service";
import { getImagePath } from "../../utils/asset.utils";
import { DateUtils } from "../../utils/date.utils";
import { MessageTableComponent } from "../message-table/message-table.component";
import { ButtonComponent } from "../shared/button/button.component";
import { IconComponent } from "../shared/icon/icon.component";
import { ThinkingExpanderComponent } from "../thinking-expander/thinking-expander.component";

/**
 * Shared tick signal that increments every 60 seconds.
 * Used by all MessageItemComponent instances to trigger timestamp recalculation.
 */
@Injectable({ providedIn: "root" })
export class TimestampTickService {
    readonly tick = signal(0);
    private ticker: ReturnType<typeof setInterval> | null = null;
    private refCount = 0;

    register(): void {
        this.refCount++;
        if (!this.ticker) {
            this.ticker = setInterval(() => {
                this.tick.update((v) => v + 1);
            }, 60_000);
        }
    }

    unregister(): void {
        this.refCount--;
        if (this.refCount <= 0 && this.ticker) {
            clearInterval(this.ticker);
            this.ticker = null;
            this.refCount = 0;
        }
    }
}

@Component({
    selector: "ep-message-item",
    imports: [
        CommonModule,
        MarkdownComponent,
        MessageTableComponent,
        ButtonComponent,
        ThinkingExpanderComponent,
        IconComponent,
    ],
    templateUrl: "./message-item.component.html",
    styleUrls: ["./message-item.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MessageItemComponent implements OnInit, OnDestroy {
    readonly message = input.required<EpMessage>();
    readonly isLast = input(false);
    readonly actionClick = output<{ action: Action; message: EpMessage }>();
    public readonly getImagePath = getImagePath;
    public isSuggestionsVisible = true;

    constructor(
        private actionService: ActionService,
        private timestampTick: TimestampTickService
    ) {
        // Reset suggestions visibility when isLast becomes true
        effect(() => {
            if (this.isLast()) {
                this.isSuggestionsVisible = true;
            }
        });
    }

    ngOnInit(): void {
        this.timestampTick.register();
    }

    ngOnDestroy(): void {
        this.timestampTick.unregister();
    }

    readonly displayTimestamp = computed(() => {
        this.timestampTick.tick(); // dependency: re-evaluate every 60s
        return this.computeTimestamp();
    });

    readonly promptActions = computed(() => {
        const actions = this.message()?.response?.action_message || [];
        return actions.filter((a) => a.type === UserActionType.Prompt);
    });

    readonly isUserMessage = computed(() => {
        return !!this.message().request;
    });

    readonly hasError = computed(() => {
        return !!this.message()._epicaError;
    });

    readonly thinkingEntries = computed(() => {
        const msg = this.message();
        if (Array.isArray(msg._epicaThinkingTrail) && msg._epicaThinkingTrail.length) {
            return msg._epicaThinkingTrail;
        }
        const current = (msg._epicaIsThinkingAbout || "").trim();
        return current ? [current] : [];
    });

    readonly hasThinkingEntries = computed(() => {
        return this.thinkingEntries().length > 0;
    });

    readonly isThinkingActive = computed(() => {
        const msg = this.message();
        if (typeof msg._epicaThinkingActive === "boolean") {
            return msg._epicaThinkingActive;
        }
        return !msg.response?.message && this.hasThinkingEntries();
    });

    private readonly messageDate = computed(() => {
        const msg = this.message();
        return msg.time ? new Date(msg.time * 1000) : new Date();
    });

    readonly displayDate = computed(() => {
        return DateUtils.formatDate(this.messageDate());
    });

    readonly messageMarkdown = computed(() => {
        return this.normalizeInlineFencedCode(this.message()?.response?.message);
    });

    readonly secondMessageMarkdown = computed(() => {
        return this.normalizeInlineFencedCode(this.message()?.response?.second_message);
    });

    readonly linkActions = computed(() => {
        const actions = this.message()?.response?.action_message || [];
        return actions.filter((action) => this.isRenderableAction(action, UserActionType.Link));
    });

    readonly buttonActions = computed(() => {
        const actions = this.message()?.response?.action_message || [];
        return actions.filter((action) => this.isRenderableAction(action, UserActionType.Button));
    });

    readonly groupedButtonActionRows = computed(() => {
        const buttonActions = this.buttonActions();
        const grouped: Record<string, Action[]> = {};

        for (const action of buttonActions) {
            const raw =
                action.sequence !== undefined && action.sequence !== null ? action.sequence : 1;
            const key = String(raw);

            if (!grouped[key]) {
                grouped[key] = [];
            }
            grouped[key].push(action);
        }

        const keys = Object.keys(grouped);
        keys.sort((a, b) => {
            const na = Number(a);
            const nb = Number(b);
            if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
            return a.localeCompare(b);
        });
        return keys.map((k) => grouped[k]);
    });

    readonly tables = computed((): EpTable[] => {
        const response = this.message()?.response;
        if (!response) return [];
        return (response._tables || []) as EpTable[];
    });

    hideSuggestions(): void {
        this.isSuggestionsVisible = false;
    }

    onSuggestionClick(action: Action): void {
        this.isSuggestionsVisible = false;
        this.onActionClick(action);
    }

    @HostListener("click", ["$event"])
    onHostClick(event: MouseEvent): void {
        const rawTarget = event.target;
        const targetElement =
            rawTarget instanceof Element
                ? rawTarget
                : rawTarget instanceof Node
                  ? rawTarget.parentElement
                  : null;
        if (!targetElement) {
            return;
        }

        const copyTrigger = targetElement.closest(".ep-md-code__copy-icon") as HTMLElement | null;
        if (!copyTrigger) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();

        const blockElement = copyTrigger.closest(".ep-md-code") as HTMLElement | null;
        const blockText = blockElement?.querySelector("pre")?.textContent ?? "";
        const fallbackCodeText = blockElement?.querySelector("code")?.textContent ?? "";
        const textToCopy = blockText || fallbackCodeText;
        if (!textToCopy) {
            return;
        }

        void this.copyCodeToClipboard(textToCopy, copyTrigger);
    }

    @HostListener("keydown", ["$event"])
    onHostKeydown(event: KeyboardEvent): void {
        const targetElement = event.target instanceof Element ? event.target : null;
        if (!targetElement) {
            return;
        }
        if (event.key !== "Enter" && event.key !== " ") {
            return;
        }
        const copyTrigger = targetElement.closest(".ep-md-code__copy-icon");
        if (!copyTrigger) {
            return;
        }
        event.preventDefault();
        (copyTrigger as HTMLElement).click();
    }

    onActionClick(action: Action): void {
        if (!action.disabled) {
            this.actionClick.emit({ action, message: this.message() });
        }
    }

    trackTableById(index: number, table: EpTable): string {
        return table.id || index.toString();
    }

    trackActionById(index: number, action: Action): string {
        return action.id || `${action.action || "action"}_${index}`;
    }

    private isRenderableAction(action: Action, expectedType: UserActionType): boolean {
        if (!action || action.type !== expectedType) {
            return false;
        }
        return this.actionService.isActionHandled(action);
    }

    private computeTimestamp(): string {
        const date = this.messageDate();
        const now = new Date();
        const diffMs = now.getTime() - date.getTime();
        const diffMin = Math.floor(diffMs / 60000);

        let timeStr: string;
        if (diffMin < 1) {
            timeStr = "just now";
        } else if (diffMin < 60) {
            timeStr = `${diffMin} min ago`;
        } else if (DateUtils.isToday(date)) {
            timeStr = DateUtils.formatTime(date);
        } else if (DateUtils.isYesterday(date)) {
            timeStr = "Yesterday";
        } else {
            timeStr = date.toLocaleDateString("en-GB", {
                day: "2-digit",
                month: "2-digit",
                year: "numeric",
            });
        }

        if (!this.isUserMessage()) {
            return `EpicChat · ${timeStr}`;
        }
        return timeStr;
    }

    private normalizeInlineFencedCode(value: string | undefined): string {
        if (!value) {
            return "";
        }

        return value.replace(/```([^`\n]+)```/g, (_full, code: string) => {
            const normalizedCode = code.trim();
            if (!normalizedCode) {
                return _full;
            }
            return `\n\n\`\`\`\n${normalizedCode}\n\`\`\`\n\n`;
        });
    }

    private async copyCodeToClipboard(text: string, copyTrigger: HTMLElement): Promise<void> {
        let copied = false;
        try {
            if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(text);
                copied = true;
            }
        } catch {
            copied = false;
        }

        if (!copied) {
            copied = this.copyWithTextareaFallback(text);
        }

        if (!copied) {
            return;
        }

        const previousLabel = copyTrigger.getAttribute("aria-label") || "Copy code";
        const previousTitle = copyTrigger.getAttribute("title") || "Copy code";
        copyTrigger.setAttribute("aria-label", "Code copied");
        copyTrigger.setAttribute("title", "Code copied");
        setTimeout(() => {
            copyTrigger.setAttribute("aria-label", previousLabel);
            copyTrigger.setAttribute("title", previousTitle);
        }, 1200);
    }

    private copyWithTextareaFallback(text: string): boolean {
        try {
            const textarea = document.createElement("textarea");
            textarea.value = text;
            textarea.style.position = "fixed";
            textarea.style.opacity = "0";
            textarea.style.pointerEvents = "none";
            document.body.appendChild(textarea);
            textarea.select();
            textarea.setSelectionRange(0, text.length);
            const success = document.execCommand("copy");
            document.body.removeChild(textarea);
            return success;
        } catch {
            return false;
        }
    }
}
