import { ChangeDetectionStrategy, Component, computed, input, output } from "@angular/core";
import { TooltipDirective } from "src/app/directives/tooltip.directive";
import { Agent } from "../../models/epicstaff-agent.model";
import { getImagePath } from "../../utils/asset.utils";
import { IconComponent } from "../shared/icon/icon.component";
import { MenuItemComponent } from "../shared/menu/menu-item.component";
import { MenuComponent } from "../shared/menu/menu.component";

@Component({
    selector: "ep-chat-header",
    templateUrl: "./chat-header.component.html",
    styleUrls: ["./chat-header.component.scss"],
    imports: [TooltipDirective, MenuComponent, MenuItemComponent, IconComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChatHeaderComponent {
    readonly currentAgent = input<Agent | null>(null);
    readonly agents = input<Agent[]>([]);
    readonly isMonoAgent = input(false);
    readonly dockEnabled = input(false);
    readonly isDockMode = input(false);

    readonly closed = output<void>();
    readonly infoClicked = output<void>();
    readonly dragClicked = output<void>();
    readonly collapseClicked = output<void>();
    readonly toggleFullHeightClicked = output<void>();
    readonly agentSelected = output<Agent>();
    readonly clearChatHistory = output<void>();
    readonly createAgent = output<void>();
    readonly editAgent = output<void>();
    readonly removeAgent = output<void>();
    readonly setDefaultPosition = output<void>();
    readonly dockClicked = output<void>();

    isAgentMenuShown = false;
    isActionsMenuShown = false;
    public readonly getImagePath = getImagePath;

    readonly title = computed(() => {
        return this.currentAgent()?.name || "Virtual Assistant";
    });

    readonly iconPath = computed(() => {
        return this.currentAgent()?.imagePath || getImagePath("epicstaff-logo.svg");
    });

    readonly hasMultipleAgents = computed(() => {
        return this.agents().length > 1;
    });

    getAgentIconPath(agent: Agent): string {
        return agent.imagePath || getImagePath("epicstaff-logo.svg");
    }

    toggleAgentMenu(): void {
        if (this.hasMultipleAgents()) {
            this.closeActionsMenu();
            this.isAgentMenuShown = !this.isAgentMenuShown;
        }
    }

    closeAgentMenu(): void {
        this.isAgentMenuShown = false;
    }

    toggleActionsMenu(): void {
        this.closeAgentMenu();
        this.isActionsMenuShown = !this.isActionsMenuShown;
    }

    closeActionsMenu(): void {
        this.isActionsMenuShown = false;
    }

    onAgentSelect(agent: Agent): void {
        this.closeAgentMenu();
        this.agentSelected.emit(agent);
    }

    onClearChatHistory(): void {
        this.closeActionsMenu();
        this.clearChatHistory.emit();
    }

    onCreateAgent(): void {
        this.closeActionsMenu();
        this.createAgent.emit();
    }

    onEditAgent(): void {
        this.closeActionsMenu();
        this.editAgent.emit();
    }

    onRemoveAgent(): void {
        this.closeActionsMenu();
        this.removeAgent.emit();
    }

    onSetDefaultPosition(): void {
        this.closeActionsMenu();
        if (this.isDockMode()) {
            this.dockClicked.emit();
        }
        this.setDefaultPosition.emit();
    }

    isCurrentAgent(agent: Agent): boolean {
        const current = this.currentAgent();
        if (!current || !agent.epicstaffAgentId) return false;
        return current.epicstaffAgentId === agent.epicstaffAgentId;
    }

    onInfoClick(): void {
        this.infoClicked.emit();
    }

    onDragClick(): void {
        this.dragClicked.emit();
    }

    onCollapseClick(): void {
        this.collapseClicked.emit();
    }

    onToggleFullHeightClick(): void {
        this.toggleFullHeightClicked.emit();
    }

    onDockClick(): void {
        this.dockClicked.emit();
    }
}
