import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    ChangeDetectorRef,
    Component,
    ElementRef,
    HostBinding,
    Renderer2,
    ViewChild,
} from "@angular/core";
import {
    TooltipOptions,
    TooltipPosition,
    TooltipState,
    TooltipTextAlign,
} from "../../../models/tooltip.interface";

interface TooltipStyles {
    tooltipTopOffset: number;
    tooltipLeftOffset: number;
    leftMarginForArrow: number;
    topMarginForArrow: number;
    arrowClass: string;
}

@Component({
    selector: "ep-tooltip",
    templateUrl: "./tooltip.component.html",
    styleUrls: ["./tooltip.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
    imports: [CommonModule],
})
export class TooltipComponent {
    @ViewChild("tooltipContainer", { static: true }) tooltipContainer!: ElementRef<HTMLDivElement>;
    @ViewChild("tooltipArrow", { static: true }) tooltipArrow!: ElementRef<HTMLDivElement>;
    @ViewChild("tooltipText", { static: true }) tooltipText!: ElementRef<HTMLDivElement>;

    @HostBinding("style.maxWidth.px")
    public maxWidth: number | null = 300;

    public state: TooltipState;
    public tooltipStyles: { [key: string]: string } = { display: "none" };
    public arrowStyles: { [key: string]: string | null } = {};
    public arrowClass = "ep-tooltip-arrow";
    public textAlign: TooltipTextAlign = "center";

    private readonly criticalDistanceToScreenBorders = 3;
    private readonly arrowHeightWithPosition = 5;

    constructor(
        private renderer: Renderer2,
        private cdr: ChangeDetectorRef
    ) {
        this.state = { show: false };
    }

    public updateAndShow(): void {
        const { element, text, options = {} } = this.state;
        if (!element || !text) return;

        this.maxWidth = options.maxWidth ?? 300;
        this.setText(text);
        this.textAlign = options.align || "center";

        const primaryPosition = options.position || "top";
        let fallbackPosition = options.altPosition;

        if (!fallbackPosition) {
            switch (primaryPosition) {
                case "top":
                    fallbackPosition = "right";
                    break;
                case "right":
                    fallbackPosition = "bottom";
                    break;
                case "bottom":
                    fallbackPosition = "left";
                    break;
                case "left":
                    fallbackPosition = "top";
                    break;
            }
        }

        this.renderer.setStyle(this.tooltipContainer.nativeElement, "visibility", "hidden");
        this.renderer.setStyle(this.tooltipContainer.nativeElement, "display", "block");

        const tooltipWidth = this.tooltipContainer.nativeElement.offsetWidth;
        const tooltipHeight = this.tooltipContainer.nativeElement.offsetHeight;

        let rawStyles = this.getRawStylesForPosition(
            element,
            options,
            primaryPosition,
            tooltipWidth,
            tooltipHeight
        );

        if (!this.checkIfTooltipFitsScreen(rawStyles, tooltipWidth, tooltipHeight)) {
            rawStyles = this.getRawStylesForPosition(
                element,
                options,
                fallbackPosition!,
                tooltipWidth,
                tooltipHeight
            );
        }

        const finalStyles = this.adjustPositionIfDoesNotFit(rawStyles, tooltipWidth);

        this.tooltipStyles = {
            display: "block",
            visibility: "visible",
            "z-index": "13000",
            top: `${finalStyles.tooltipTopOffset}px`,
            left: `${Math.round(finalStyles.tooltipLeftOffset)}px`,
        };
        this.arrowClass = `ep-tooltip-arrow ${finalStyles.arrowClass}`;
        this.arrowStyles = {
            "margin-left": finalStyles.leftMarginForArrow
                ? `${Math.floor(finalStyles.leftMarginForArrow)}px`
                : null,
            "margin-top": finalStyles.topMarginForArrow
                ? `${Math.floor(finalStyles.topMarginForArrow)}px`
                : null,
        };

        this.cdr.detectChanges();
    }

    private setText(text: string): void {
        this.tooltipText.nativeElement.innerHTML = text.replace(/\n/g, "<br />");
    }

    private getRawStylesForPosition(
        element: HTMLElement,
        options: TooltipOptions,
        position: TooltipPosition,
        tooltipWidth: number,
        tooltipHeight: number
    ) {
        const elemRect = element.getBoundingClientRect();
        const elemWidth = options.width ?? elemRect.width;
        const elemHeight = elemRect.height;
        const elemLeft = elemRect.left + window.scrollX + (options.offset?.left ?? 0);
        const elemTop = elemRect.top + window.scrollY + (options.offset?.top ?? 0);

        const baseStyles = { leftMarginForArrow: 0, topMarginForArrow: 0 };

        switch (position) {
            case "bottom":
                return {
                    ...baseStyles,
                    tooltipTopOffset: elemTop + elemHeight + this.arrowHeightWithPosition,
                    tooltipLeftOffset: elemLeft + elemWidth / 2 - tooltipWidth / 2,
                    arrowClass: "upArrow",
                };
            case "left":
                return {
                    ...baseStyles,
                    tooltipTopOffset: elemTop + elemHeight / 2 - tooltipHeight / 2,
                    tooltipLeftOffset: elemLeft - tooltipWidth - this.arrowHeightWithPosition,
                    arrowClass: "rightArrow",
                };
            case "right":
                return {
                    ...baseStyles,
                    tooltipTopOffset: elemTop + elemHeight / 2 - tooltipHeight / 2,
                    tooltipLeftOffset: elemLeft + elemWidth + this.arrowHeightWithPosition,
                    arrowClass: "leftArrow",
                };
            case "top":
            default:
                return {
                    ...baseStyles,
                    tooltipTopOffset: elemTop - (tooltipHeight + this.arrowHeightWithPosition),
                    tooltipLeftOffset: elemLeft + elemWidth / 2 - tooltipWidth / 2,
                    arrowClass: "downArrow",
                };
        }
    }

    private checkIfTooltipFitsScreen(
        styles: TooltipStyles,
        tooltipWidth: number,
        tooltipHeight: number
    ): boolean {
        return !(
            styles.tooltipTopOffset - this.criticalDistanceToScreenBorders < window.scrollY ||
            styles.tooltipTopOffset + tooltipHeight + this.criticalDistanceToScreenBorders >
                window.scrollY + window.innerHeight ||
            styles.tooltipLeftOffset - this.criticalDistanceToScreenBorders < window.scrollX ||
            styles.tooltipLeftOffset + tooltipWidth + this.criticalDistanceToScreenBorders >
                window.scrollX + window.innerWidth
        );
    }

    private adjustPositionIfDoesNotFit(styles: TooltipStyles, tooltipWidth: number): TooltipStyles {
        const maxLeftOffset =
            window.innerWidth - tooltipWidth - this.criticalDistanceToScreenBorders;
        if (styles.tooltipLeftOffset > maxLeftOffset) {
            const shiftAmount = styles.tooltipLeftOffset - maxLeftOffset;
            styles.leftMarginForArrow = shiftAmount;
            styles.tooltipLeftOffset = maxLeftOffset;
        }

        const minLeftOffset = this.criticalDistanceToScreenBorders;
        if (styles.tooltipLeftOffset < minLeftOffset) {
            const shiftAmount = minLeftOffset - styles.tooltipLeftOffset;
            styles.leftMarginForArrow = -shiftAmount;
            styles.tooltipLeftOffset = minLeftOffset;
        }

        if (styles.arrowClass === "leftArrow" || styles.arrowClass === "rightArrow") {
            const minTopOffset = this.criticalDistanceToScreenBorders;
            if (styles.tooltipTopOffset < minTopOffset) {
                const shiftAmount = minTopOffset - styles.tooltipTopOffset;
                styles.topMarginForArrow = -shiftAmount;
                styles.tooltipTopOffset = minTopOffset;
            }
        }
        return styles;
    }
}
