import { Injectable } from "@angular/core";
import { CHAT_CONSTANTS } from "../constants/chat.constants";
import { STORAGE_KEYS } from "../constants/storage.constants";
import { Agent } from "../models/epicstaff-agent.model";
import { EpMessage } from "../models/message.model";
import { generateMessageId, getCurrentTimestamp } from "../utils/message.utils";
import { StorageService } from "./storage.service";

@Injectable({ providedIn: "root" })
export class MessageService {
    constructor(private storageService: StorageService) {}

    createMessage(text: string): EpMessage {
        return {
            id: generateMessageId(),
            request: text.trim(),
            time: getCurrentTimestamp(),
        };
    }

    /**
     * Get chat ID based on agent and userId
     * Always includes userId to ensure messages are separated by user
     * Uses "session" as userId when userId is not set (for anonymous users)
     * For mono agents: epicstaff_monoAgent_${userId}
     * For Epicstaff agents: epicstaff_${epicstaffAgentId}_${userId}
     * For other agents: ${mode or name}_${userId}
     */
    getChatId(agent: Agent | null, isMonoAgent: boolean = false): string {
        const userId = this.storageService.getUserId() || "session";

        if (!agent) {
            return `default_${userId}`;
        }

        // For mono agents, use userId-based chatId to ensure persistence
        if (isMonoAgent) {
            return `epicstaff_monoAgent_${userId}`;
        }

        // Используем epicstaffAgentId для Epicstaff агентов с userId в конце
        if (agent.epicstaffAgentId !== undefined) {
            return `epicstaff_${agent.epicstaffAgentId}_${userId}`;
        }

        // For other agents, use mode if available, otherwise use name, with userId suffix
        const agentIdentifier = agent.mode || agent.name?.toLowerCase() || "default";
        return `${agentIdentifier}_${userId}`;
    }

    /**
     * Save messages to storage (localStorage if userId is set, sessionStorage otherwise)
     */
    saveMessages(chatId: string, messages: EpMessage[]): void {
        // Limit messages to MAX_MESSAGES
        const limitedMessages = messages.slice(-CHAT_CONSTANTS.MAX_MESSAGES);

        // Get all messages from storage
        const allMessages = this.getAllMessagesFromStorage();

        // Update messages for this chat
        allMessages[chatId] = limitedMessages;

        // Save back to storage (uses sessionStorage if userId is not set)
        this.storageService.setItemAsJSON(STORAGE_KEYS.CHAT_MESSAGES, allMessages);
    }

    /**
     * Load messages from storage (localStorage if userId is set, sessionStorage otherwise)
     */
    loadMessages(chatId: string): EpMessage[] {
        const allMessages = this.getAllMessagesFromStorage();
        return allMessages[chatId] || [];
    }

    /**
     * Get all messages from storage (organized by chatId)
     */
    private getAllMessagesFromStorage(): { [chatId: string]: EpMessage[] } {
        const stored = this.storageService.getItemAsJSON<{ [chatId: string]: EpMessage[] }>(
            STORAGE_KEYS.CHAT_MESSAGES
        );
        return stored || {};
    }

    /**
     * Add a message and save to storage
     */
    addMessage(chatId: string, message: EpMessage): void {
        const messages = this.loadMessages(chatId);
        messages.push(message);
        this.saveMessages(chatId, messages);
    }

    /**
     * Update a message in storage
     */
    updateMessage(chatId: string, messageId: string, updates: Partial<EpMessage>): void {
        const messages = this.loadMessages(chatId);
        const index = messages.findIndex(
            (msg) => msg.id === messageId || msg.time === updates.time
        );
        if (index !== -1) {
            messages[index] = { ...messages[index], ...updates };
            this.saveMessages(chatId, messages);
        }
    }

    /**
     * Clear messages for a specific chat
     */
    clearMessages(chatId: string): void {
        const allMessages = this.getAllMessagesFromStorage();
        delete allMessages[chatId];
        this.storageService.setItemAsJSON(STORAGE_KEYS.CHAT_MESSAGES, allMessages);
    }
}
