import {
    CdkDrag,
    CdkDragDrop,
    CdkDragHandle,
    CdkDropList,
    moveItemInArray,
} from "@angular/cdk/drag-drop";
import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    Component,
    ElementRef,
    EventEmitter,
    HostListener,
    Input,
    OnChanges,
    OnDestroy,
    OnInit,
    Output,
    SimpleChanges,
} from "@angular/core";
import { TooltipDirective } from "../../directives/tooltip.directive";
import { ColumnGroup, DynamicColumn } from "./message-table-columns-configuration.model";

@Component({
    selector: "ep-message-table-columns-configuration",
    standalone: true,
    imports: [CommonModule, CdkDropList, CdkDrag, CdkDragHandle, TooltipDirective],
    templateUrl: "./message-table-columns-configuration.component.html",
    styleUrls: ["./message-table-columns-configuration.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MessageTableColumnsConfigurationComponent implements OnInit, OnChanges, OnDestroy {
    @Input() columns: DynamicColumn[] = [];
    @Input() maxHeight = 400;
    @Input() tooltipText = "Reorder columns and groups, show/hide columns";
    @Input() isEmbedded = false;

    @Output() updateShownColumns = new EventEmitter<DynamicColumn[]>();

    isDropdownOpen = false;
    columnGroups: ColumnGroup[] = [];
    private originalColumns: DynamicColumn[] = [];

    constructor(private eRef: ElementRef) {}

    ngOnInit(): void {
        this.updateOriginalColumns();
        this.groupColumns();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes["columns"] && !changes["columns"].firstChange) {
            this.updateOriginalColumns();
            this.groupColumns();
        }
    }

    ngOnDestroy(): void {
        this.closeDropdown();
    }

    toggleDropdown(): void {
        this.isDropdownOpen = !this.isDropdownOpen;
    }

    closeDropdown(): void {
        this.isDropdownOpen = false;
    }

    toggleColumnShowing(column: DynamicColumn): void {
        if (!column.isHidable) return;
        const updated = { ...column, visible: !column.visible };
        this.updateColumnInGroups(updated);
        this.updateShownColumns.emit(this.getAllColumns());
    }

    toggleGroupVisibility(group: ColumnGroup): void {
        const next = !group.isVisible;
        group.isVisible = next;
        group.columns.forEach((column) => {
            if (column.isHidable) {
                column.visible = next;
            }
        });
        this.updateShownColumns.emit(this.getAllColumns());
    }

    toggleGroupCollapse(group: ColumnGroup): void {
        group.isCollapsed = !group.isCollapsed;
    }

    onGroupDrop(event: CdkDragDrop<ColumnGroup[]>): void {
        moveItemInArray(this.columnGroups, event.previousIndex, event.currentIndex);
        this.updateGroupOrders();
        this.syncColumnsFromGroups();
        this.updateShownColumns.emit(this.getAllColumns());
    }

    onColumnDrop(event: CdkDragDrop<DynamicColumn[]>, groupId: string): void {
        const group = this.columnGroups.find((g) => g.id === groupId);
        if (!group) return;
        if (event.previousContainer === event.container) {
            moveItemInArray(group.columns, event.previousIndex, event.currentIndex);
            this.updateColumnOrders();
            this.syncColumnsFromGroups();
            this.updateShownColumns.emit(this.getAllColumns());
        }
    }

    restoreDefaultConfiguration(): void {
        this.columns = JSON.parse(JSON.stringify(this.originalColumns));
        this.groupColumns();
        this.updateColumnOrders();
        this.updateShownColumns.emit(this.getAllColumns());
    }

    toggleSelectAll(): void {
        const allSelected = this.columns.every((column) => column.visible);
        this.columns.forEach((column) => {
            if (column.isHidable) {
                column.visible = !allSelected;
            }
        });
        this.groupColumns();
        this.updateShownColumns.emit(this.getAllColumns());
    }

    get selectAllText(): string {
        return this.columns.every((column) => column.visible) ? "Deselect all" : "Select all";
    }

    trackByHandler(option: DynamicColumn): string {
        return option.key;
    }

    trackByGroup(_index: number, group: ColumnGroup): string {
        return group.id;
    }

    private groupColumns(): void {
        const groupsMap = new Map<string, DynamicColumn[]>();
        this.columns.forEach((column) => {
            const groupId = column.group || "default";
            if (!groupsMap.has(groupId)) {
                groupsMap.set(groupId, []);
            }
            groupsMap.get(groupId)?.push({
                ...column,
                visible: column.visible !== undefined ? column.visible : true,
            });
        });

        this.columnGroups = Array.from(groupsMap.entries()).map(([groupId, columns], index) => ({
            id: groupId,
            title: this.getGroupTitle(groupId),
            columns: columns.sort((a, b) => a.order - b.order),
            isVisible: columns.some((col) => col.visible),
            isCollapsed: false,
            order: index,
        }));
    }

    private getGroupTitle(groupId: string): string {
        const groupTitles: Record<string, string> = {
            default: "Columns",
            taskColumns: "Task Columns",
            generated: "Generated Columns",
        };
        return groupTitles[groupId] || groupId;
    }

    private updateColumnInGroups(updatedColumn: DynamicColumn): void {
        this.columnGroups.forEach((group) => {
            const index = group.columns.findIndex((col) => col.key === updatedColumn.key);
            if (index !== -1) {
                group.columns[index] = updatedColumn;
                group.isVisible = group.columns.some((col) => col.visible);
            }
        });
    }

    private getAllColumns(): DynamicColumn[] {
        return this.columnGroups.flatMap((group) => group.columns);
    }

    private updateColumnOrders(): void {
        let globalOrder = 0;
        this.columnGroups.forEach((group) => {
            group.columns.forEach((column) => {
                column.order = globalOrder++;
            });
        });
    }

    private updateGroupOrders(): void {
        this.columnGroups.forEach((group, index) => {
            group.order = index;
        });
    }

    private syncColumnsFromGroups(): void {
        this.columns = this.getAllColumns();
    }

    private updateOriginalColumns(): void {
        if (this.originalColumns.length === 0) {
            this.originalColumns = JSON.parse(JSON.stringify(this.columns));
        }
    }

    @HostListener("document:click", ["$event"])
    onDocumentClick(event: MouseEvent): void {
        if (!this.isEmbedded && this.isDropdownOpen) {
            const path = event.composedPath?.() ?? [];
            const target = event.target as Node | null;
            const isInside =
                path.includes(this.eRef.nativeElement) ||
                (!!target && this.eRef.nativeElement.contains(target));
            if (!isInside) {
                this.closeDropdown();
            }
        }
    }
}
