import { Injectable, signal } from "@angular/core";
import { EpMessage } from "../models/message.model";

@Injectable({ providedIn: "root" })
export class ChatService {
    readonly messages = signal<EpMessage[]>([]);
    readonly isOpen = signal<boolean>(false);
    readonly unreadCount = signal<number>(0);
    readonly attachedFile = signal<File | null>(null);
    readonly attachedFiles = signal<File[]>([]);
    readonly isLastRequestUsedFile = signal<boolean>(false);
    readonly isRecentFilesMenuShown = signal<boolean>(false);

    getMessagesValue(): EpMessage[] {
        return this.messages();
    }

    addMessage(message: EpMessage): void {
        const currentMessages = this.messages();
        this.messages.set([...currentMessages, message]);
    }

    setMessages(messages: EpMessage[]): void {
        this.messages.set(messages);
    }

    clearMessages(): void {
        this.messages.set([]);
    }

    openChat(): void {
        this.isOpen.set(true);
        this.unreadCount.set(0);
    }

    closeChat(): void {
        this.isOpen.set(false);
    }

    toggleChat(): void {
        this.isOpen.update((v) => !v);
        if (this.isOpen()) {
            this.unreadCount.set(0);
        }
    }

    incrementUnreadCount(): void {
        if (!this.isOpen()) {
            this.unreadCount.update((v) => v + 1);
        }
    }

    setAttachedFile(file: File | null): void {
        this.attachedFile.set(file);
    }

    setAttachedFiles(files: File[]): void {
        this.attachedFiles.set(files);
    }

    setIsLastRequestUsedFile(flag: boolean): void {
        this.isLastRequestUsedFile.set(flag);
    }

    setIsRecentFilesMenuShown(flag: boolean): void {
        this.isRecentFilesMenuShown.set(flag);
    }

    toggleRecentFilesMenu(): void {
        this.isRecentFilesMenuShown.update((v) => !v);
    }

    /**
     * Update a specific message in the messages array
     */
    updateMessage(messageId: string, updater: (message: EpMessage) => EpMessage): void {
        const currentMessages = this.messages();
        const updatedMessages = currentMessages.map((msg) => {
            if (msg.id === messageId) {
                return updater({ ...msg });
            }
            return msg;
        });
        this.messages.set(updatedMessages);
    }

    /**
     * Remove all button actions from a specific message
     */
    removeButtonActionsFromMessage(messageId: string): void {
        this.updateMessage(messageId, (message) => {
            if (message.response?.action_message) {
                const filteredActions = message.response.action_message.filter(
                    (action) => action.type !== "button"
                );
                return {
                    ...message,
                    response: {
                        ...message.response,
                        action_message: filteredActions.length > 0 ? filteredActions : undefined,
                    },
                };
            }
            return message;
        });
    }
}
