    private getBasePath(): string {
        interface WindowWithEpicChat extends Window {
            __epicChatBasePath?: string;
        }
        const globalBase = (window as WindowWithEpicChat)?.__epicChatBasePath;
        return (this.basePath || globalBase || "").toString();
    }

    private setGlobalBasePath(): void {
        interface WindowWithEpicChat extends Window {
            __epicChatBasePath?: string;
        }
        if (this.basePath) {
            (window as WindowWithEpicChat).__epicChatBasePath = this.basePath;
        }
    }

    private getIconPath(): string {
        if (this.chatIconPath) {
            return getImagePath(this.chatIconPath);
        }
        const base = this.getBasePath();
        const normalized = base ? (base.endsWith("/") ? base : base + "/") : "";
        return normalized + "assets/images/shared/epicstaff-chat-logo.svg";
    }

    private getChatStyle(position?: ChatPosition): Record<string, string> {
        const style: Record<string, string> = {
            width: this.chatWidth || CHAT_CONSTANTS.DEFAULT_WIDTH,
            height: this.chatHeight || CHAT_CONSTANTS.DEFAULT_HEIGHT,
            maxWidth: "90vw",
            maxHeight: "100vh",
        };

        const pos = position || this.chatPosition;

        if (pos && CHAT_CONSTANTS.PRESET_POSITIONS[pos]) {
            Object.assign(style, CHAT_CONSTANTS.PRESET_POSITIONS[pos]);
        } else if (this.chatTop || this.chatLeft || this.chatRight || this.chatBottom) {
            style["transform"] = "none";
            if (this.chatTop) style["top"] = this.chatTop;
            if (this.chatLeft) style["left"] = this.chatLeft;
            if (this.chatRight) style["right"] = this.chatRight;
            if (this.chatBottom) style["bottom"] = this.chatBottom;
        } else {
            Object.assign(style, CHAT_CONSTANTS.DEFAULT_POSITION);
        }

        return style;
    }

    getConfig(): ChatConfig {
        return {
            title: this.title,
            basePath: this.basePath,
            chatWidth: this.chatWidth,
            chatHeight: this.chatHeight,
            chatTop: this.chatTop,
            chatLeft: this.chatLeft,
            chatRight: this.chatRight,
            chatBottom: this.chatBottom,
            chatPosition: this.chatPosition || undefined,
            uniqueUserId: this.uniqueUserId,
        };
    }
