/**
 * Utility functions for asset paths
 */

/**
 * Get base path for assets from global window variable or provided basePath
 */
export function getBasePath(basePath?: string): string {
    interface WindowWithEpicChat extends Window {
        __epicChatBasePath?: string;
    }
    const globalBase = (window as WindowWithEpicChat)?.__epicChatBasePath;
    const base = basePath || globalBase || "";
    return base ? (base.endsWith("/") ? base : base + "/") : "";
}

/**
 * Get full path to an asset image
 * @param assetPath - Relative path to asset (e.g., "assets/images/shared/icon.svg")
 * @param basePath - Optional base path override
 * @returns Full path to asset
 */
export function getImagePath(path: string, basePath?: string): string {
    const base = getBasePath(basePath);
    if (!path) {
        return base;
    }
    if (path.includes("://") || path.startsWith("data:") || path.startsWith("/")) {
        return path;
    }
    const normalized = path.includes("/") ? path : `assets/images/shared/${path}`;
    return base + normalized;
}
