type TableRow = Record<string, unknown>;

@Component({
    selector: "ep-message-table",
    imports: [
        CommonModule,
        FormsModule,
        ButtonComponent,
        MessageTableCellComponent,
        MessageTableColumnsConfigurationComponent,
    ],
    templateUrl: "./message-table.component.html",
    styleUrls: ["./message-table.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MessageTableComponent implements OnInit, OnChanges {
    @Input() message!: EpMessage;
    @Input() columns: EpTableColumn[] = [];
    @Input() rows: TableRow[] = [];
    @Input() visibleRowsQuantity = 10;
    @Input() isEditable = true;
    @Input() isTitleEditable = true;
    @Input() isSortable = true;
    @Input() defaultSortField: string | null = null;
    @Input() tableActions: Action[] = [];
    @Input() id: string | null = null;
    @Input() rowsSelectionType?: "edit" | "select" | "multiSelect";
    @Input() preselectedRows?: string[];
    @Input() unions: EpTableUnion[] = [];

    readonly actionClick = output<{ action: Action; message: EpMessage }>();

    @ViewChild("tableContainer", { static: false }) tableContainer!: ElementRef;
    @ViewChild("columnsToggle", { static: false }) columnsToggle?: ElementRef<HTMLButtonElement>;
    @ViewChild("columnsDropdown", { static: false }) columnsDropdown?: ElementRef<HTMLDivElement>;

    public displayedRows: TableRow[] = [];
    public showAll = false;
    public currentSortField: string | null = null;
    public currentSortOrder: SortOrder = null;
    public hoveredColumn: string | null = null;
    public dynamicColumns: DynamicColumn[] = [];
    public visibleColumns: EpTableColumn[] = [];
    public showColumnsDropdown = false;
    public isColumnsDropdownPositioned = false;
    public columnsDropdownStyles: Record<string, string> = {};
    private columnAccessors: { [key: string]: (row: TableRow) => unknown } = {};

    public editingKey: string | null = null;
    public editingRow: TableRow | null = null;
    public editingValue: unknown = null;
    public editingDate: Date | null = null;
    private editingOriginalValue: unknown = null;
    public editingColumnKey: string | null = null;
    public editingColumnTitle: string | null = null;
    private originalRowSnapshots = new WeakMap<TableRow, TableRow>();
    private originalRows: TableRow[] = [];
    private originalColumnTitles: { [key: string]: string } = {};
    private initialTableSnapshotDone = false;
    private hasAnyChanges = false;

    public selectedRow: TableRow | null = null;
    public selectedRows = new Set<TableRow>();

    readonly UserAction = UserAction;
    public readonly getImagePath = getImagePath;

    private dropdownState = new WeakMap<TableRow, Map<string, DropdownCellState>>();
    private readonly dropdownSelectionPrefix = "__va_selected__";
    private dropdownStatesPrepared = false;

    private unionIndexByKey = new Map<string, number>();
    private unionsNormalized: {
        keys: string[];
        index: number;
        title: string;
        ruleName: UnionRuleName;
    }[] = [];
    private unionErrorKeysByRow = new WeakMap<TableRow, Map<number, Set<string>>>();
    public hasUnions = false;

    private readonly mathParser = new Parser();
    private readonly mathExpressionCache = new Map<string, ReturnType<Parser["parse"]>>();

    constructor(
        private tooltipService: TooltipService,
        private cdr: ChangeDetectorRef
    ) {}

    ngOnInit(): void {
        if (!this.rows || this.rows.length === 0) {
            console.warn("MessageTableComponent: No rows provided", {
                rows: this.rows,
                columns: this.columns,
            });
            return;
        }
        if (!this.columns || this.columns.length === 0) {
            console.warn("MessageTableComponent: No columns provided", {
                rows: this.rows,
                columns: this.columns,
            });
            return;
        }
        this.initializeTable();
        this.initializeColumns();
        this.ensureInitialSnapshots();
        this.initializeUnions();
        this.restoreSelectedRows();
        this.prepareAllDropdownStates();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (
            changes["rows"] ||
            changes["visibleRowsQuantity"] ||
            changes["defaultSortField"] ||
            changes["isSortable"]
        ) {
            this.initializeTable();
        }
        if (changes["columns"]) {
            this.initializeColumns();
        }
        if (changes["rows"] || changes["rowsSelectionType"] || changes["preselectedRows"]) {
            this.ensureInitialSnapshots();
            this.initializeUnions();
            this.restoreSelectedRows();
        }
        if (changes["rows"] || changes["columns"]) {
            this.dropdownState = new WeakMap<TableRow, Map<string, DropdownCellState>>();
            this.dropdownStatesPrepared = false;
            this.prepareAllDropdownStates();
        }
        if (changes["unions"]) {
            this.initializeUnions();
            this.initializeColumns();
        }
    }

    private initializeTable(): void {
        if (this.isSortable && this.defaultSortField) {
            this.currentSortField = this.defaultSortField;
            this.currentSortOrder = "asc";
        }

        this.recalculateMathForAllRows();
        this.updateDisplayedValues();
    }

    private updateDisplayedValues(): void {
        if (!Array.isArray(this.rows)) {
            console.error("MessageTableComponent: rows is not an array", this.rows);
            this.displayedRows = [];
            return;
        }
        const sortedRows = [...this.rows];

        if (this.isSortable && this.currentSortField && this.currentSortOrder) {
            sortedRows.sort((a, b) => {
                const aValue = this.getNestedValue(a, this.currentSortField!);
                const bValue = this.getNestedValue(b, this.currentSortField!);

                if (aValue === undefined || aValue === null) return 1;
                if (bValue === undefined || bValue === null) return -1;

                if (this.currentSortOrder === "asc") {
                    return aValue > bValue ? 1 : -1;
                } else {
                    return aValue < bValue ? 1 : -1;
                }
            });
        }

        if (this.showAll || sortedRows.length <= this.visibleRowsQuantity) {
            this.displayedRows = sortedRows;
        } else {
            this.displayedRows = sortedRows.slice(0, this.visibleRowsQuantity);
        }
    }

    private getNestedValue(obj: TableRow, path: string): unknown {
        if (!path || typeof path !== "string") {
            return undefined;
        }
        if (obj && typeof obj === "object" && path in obj) {
            return (obj as Record<string, unknown>)[path];
        }
        return path.split(".").reduce((current, key) => {
            if (current && typeof current === "object" && key in current) {
                return (current as Record<string, unknown>)[key];
            }
            return undefined;
        }, obj as unknown);
    }

    private compilePath(path: string): (obj: TableRow) => unknown {
        if (!path || typeof path !== "string") {
            return () => undefined;
        }
        if (path.indexOf(".") === -1) {
            return (obj: TableRow) => obj[path];
        }
        const parts = path.split(".");
        return (obj: TableRow) => {
            if (!obj || typeof obj !== "object") return undefined;
            if (path in obj) {
                return (obj as Record<string, unknown>)[path];
            }
            let current: unknown = obj;
            for (let i = 0; i < parts.length && current != null; i++) {
                if (typeof current === "object" && current !== null && parts[i] in current) {
                    current = (current as Record<string, unknown>)[parts[i]];
                } else {
                    return undefined;
                }
            }
            return current;
        };
    }

    private buildColumnAccessors(): void {
        this.columnAccessors = {};
        const source = this.columns || [];
        for (const col of source) {
            if (col && col.key) {
                this.columnAccessors[col.key] = this.compilePath(col.key);
            }
        }
    }

    private ensureInitialSnapshots(): void {
        if (this.initialTableSnapshotDone || !Array.isArray(this.rows)) return;

        this.originalRows = this.deepCloneArray(this.rows);

        for (const row of this.rows) {
            if (row && !this.originalRowSnapshots.has(row)) {
                this.originalRowSnapshots.set(row, this.deepCloneRow(row));
            }
        }
        if (Object.keys(this.originalColumnTitles).length === 0) {
            this.columns.forEach((col) => {
                if (col && col.key) {
                    this.originalColumnTitles[col.key] = col.title ?? col.key;
                }
            });
        }
        this.initialTableSnapshotDone = true;
    }

    private deepCloneArray(arr: TableRow[]): TableRow[] {
        return arr.map((row) => this.deepCloneRow(row));
    }

    private deepCloneRow(obj: TableRow): TableRow {
        const cloned: Record<string, unknown> = {};
        for (const key in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, key)) {
                const value = obj[key];
                if (value === null || typeof value !== "object") {
                    cloned[key] = value;
                } else if (value instanceof Date) {
                    cloned[key] = new Date(value.getTime());
                } else if (Array.isArray(value)) {
                    cloned[key] = value.map((item) =>
                        typeof item === "object" && item !== null
                            ? this.deepCloneRow(item as TableRow)
                            : item
                    );
                } else {
                    cloned[key] = this.deepCloneRow(value as TableRow);
                }
            }
        }
        return cloned as TableRow;
    }

    public isCellChanged(row: TableRow, column: EpTableColumn): boolean {
        const original = this.originalRowSnapshots.get(row);
        if (!original) return false;
        const currentVal = this.getNestedValue(row, column.key);
        const originalVal = this.getNestedValue(original, column.key);
        return !this.isEqualShallow(currentVal, originalVal);
    }

    private isEqualShallow(a: unknown, b: unknown): boolean {
        if (a === b) return true;
        if (typeof a !== typeof b) return false;
        try {
            return JSON.stringify(a) === JSON.stringify(b);
        } catch {
            return false;
        }
    }

    public onCellDblClick(row: TableRow, column: EpTableColumn): void {
        if (!this.isEditable || column.editable === false) return;
        if (
            column.type === "boolean" ||
            column.type === "select" ||
            column.type === "multiSelect"
        ) {
            return;
        }
        this.editingRow = row;
        this.editingKey = column.key;
        this.editingOriginalValue = this.getNestedValue(row, column.key);

        if (column.type === "date") {
            const rawValue = this.getNestedValue(row, column.key);
            this.editingDate = this.parseDateValue(rawValue);
            if (!this.editingDate) {
                this.editingDate = new Date();
            }
            this.editingValue = null;
        } else {
            this.editingValue = this.getCellValue(row, column);
            this.editingDate = null;
        }
    }

    public onEditKeydown(event: KeyboardEvent, row: TableRow, column: EpTableColumn): void {
        if (!this.isEditable || column.editable === false) return;
        if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            this.applyEdit(row, column);
        } else if (event.key === "Escape") {
            event.preventDefault();
            this.cancelEdit(true);
        }
    }

    public isColumnEditable(column: EpTableColumn): boolean {
        return !!this.isEditable && column.editable !== false;
    }

    public isEditingCell(row: TableRow, column: EpTableColumn): boolean {
        return (
            this.isColumnEditable(column) &&
            this.editingKey === column.key &&
            this.editingRow === row
        );
    }

    public isEditingColumnTitle(column: EpTableColumn): boolean {
        return this.isEditable && this.isTitleEditable && this.editingColumnKey === column.key;
    }

    public isColumnTitleChanged(column: EpTableColumn): boolean {
        const originalDisplayTitle = this.originalColumnTitles[column.key];
        if (originalDisplayTitle === undefined) {
            return false;
        }
        const currentDisplayTitle = column.title ?? column.key;
        return currentDisplayTitle !== originalDisplayTitle;
    }

    public getActionIcon(action: Action): string | null {
        if (
            action.action === UserAction.DownloadEpTableCsv ||
            action.action === UserAction.DownloadEpTableExcel
        ) {
            return getImagePath("assets/images/shared/download.svg");
        }
        if (action.action === UserAction.EpicstaffResetTable) {
            return getImagePath("assets/images/shared/undo.svg");
        }
        return null;
    }

    public get tableActionsToRender(): Action[] {
        const existing = Array.isArray(this.tableActions) ? [...this.tableActions] : [];
        const downloadActions = this.buildDownloadActions().filter(
            (action) => !existing.some((item) => item.action === action.action)
        );
        if (downloadActions.length === 0) {
            return existing;
        }
        const undoIndex = existing.findIndex(
            (action) => action.action === UserAction.EpicstaffResetTable
        );
        if (undoIndex === -1) {
            return [...downloadActions, ...existing];
        }
        return [...existing.slice(0, undoIndex), ...downloadActions, ...existing.slice(undoIndex)];
    }

    public shouldShowActionText(action: Action): boolean {
        return action.action !== UserAction.EpicstaffResetTable;
    }

    public get resetTableAction(): Action | null {
        return (
            this.tableActionsToRender.find((a) => a.action === UserAction.EpicstaffResetTable) ??
            null
        );
    }

    public get csvAction(): Action {
        return { action: UserAction.DownloadEpTableCsv, type: "button", text: "CSV" };
    }

    public get xlsxAction(): Action {
        return { action: UserAction.DownloadEpTableExcel, type: "button", text: "XLSX" };
    }

    public get customTableActionsToRender(): Action[] {
        return this.tableActionsToRender.filter(
            (a) =>
                a.action !== UserAction.EpicstaffResetTable &&
                a.action !== UserAction.DownloadEpTableCsv &&
                a.action !== UserAction.DownloadEpTableExcel
        );
    }

    public onDeleteRowClick(row: TableRow, event: Event): void {
        if (!this.isEditable || this.rowsSelectionType !== "edit") return;

        event.stopPropagation();
        const rowIndex = this.rows.findIndex((r) => r === row);
        if (rowIndex !== -1) {
            this.rows.splice(rowIndex, 1);
            this.updateDisplayedValues();

            if (!this.hasAnyChanges && Array.isArray(this.tableActions)) {
                const hasReset = this.tableActions.some(
                    (a) => a?.action === UserAction.EpicstaffResetTable
                );
                if (!hasReset) {
                    this.tableActions.push({
                        action: UserAction.EpicstaffResetTable,
                        type: "button",
                        text: "Undo changes",
                    });
                }
                this.hasAnyChanges = true;
            }
        }
    }

    public applyEdit(row: TableRow, column: EpTableColumn): void {
        if (this.editingKey !== column.key || this.editingRow !== row) {
            this.cancelEdit(true);
            return;
        }

        let newValue = this.editingValue;
        if (column.type === "date") {
            newValue = this.editingDate ? this.formatDateForBackend(this.editingDate) : null;
        } else if (column.type === "number") {
            const parsed = Number(newValue);
            newValue = isNaN(parsed) ? newValue : parsed;
        }

        this.setNestedValue(row, column.key, newValue);

        for (const u of this.unionsNormalized) {
            if (u.keys.includes(column.key)) {
                this.validateUnionRow(row, u);
            }
        }

        if (!this.hasAnyChanges && Array.isArray(this.tableActions)) {
            const hasReset = this.tableActions.some(
                (a) => a?.action === UserAction.EpicstaffResetTable
            );
            if (!hasReset) {
                this.tableActions.push({
                    action: UserAction.EpicstaffResetTable,
                    type: "button",
                    text: "Undo changes",
                });
            }
            this.hasAnyChanges = true;
        }

        this.cancelEdit(false);
    }

    public onTableActionClick(action: Action, _event: Event): void {
        if (action?.action === UserAction.EpicstaffResetTable) {
            this.revertToOriginal();
        } else {
            const actionWithTableId = {
                ...action,
                params: {
                    ...action.params,
                    tableId: this.id,
                    uniqueTableId: this.id,
                },
            };
            this.actionClick.emit({ action: actionWithTableId, message: this.message });
        }
    }

    private buildDownloadActions(): Action[] {
        return [
            {
                action: UserAction.DownloadEpTableCsv,
                type: "button",
                text: "Download csv",
            },
            {
                action: UserAction.DownloadEpTableExcel,
                type: "button",
                text: "Download xlsx",
            },
        ];
    }

    private revertToOriginal(): void {
        this.rows.splice(0, this.rows.length, ...this.deepCloneArray(this.originalRows));

        this.columns.forEach((col) => {
            if (col && col.key) {
                const originalTitle = this.originalColumnTitles[col.key];
                col.title = originalTitle !== undefined ? originalTitle : col.key;
            }
        });
        this.visibleColumns.forEach((col) => {
            if (col && col.key) {
                const originalTitle = this.originalColumnTitles[col.key];
                col.title = originalTitle !== undefined ? originalTitle : col.key;
            }
        });

        this.editingKey = null;
        this.editingRow = null;
        this.editingValue = null;
        this.editingDate = null;
        this.editingColumnKey = null;
        this.editingColumnTitle = null;
        this.initialTableSnapshotDone = false;
        this.originalRowSnapshots = new WeakMap<TableRow, TableRow>();
        this.ensureInitialSnapshots();

        if (Array.isArray(this.tableActions)) {
            this.tableActions = this.tableActions.filter(
                (a: Action) => a?.action !== UserAction.EpicstaffResetTable
            );
        }
        this.hasAnyChanges = false;

        this.updateDisplayedValues();
        this.dropdownState = new WeakMap<TableRow, Map<string, DropdownCellState>>();
        this.dropdownStatesPrepared = false;
        this.prepareAllDropdownStates();

        this.initializeUnions();
    }

    public cancelEdit(revertToOriginal: boolean = false): void {
        if (revertToOriginal && this.editingRow && this.editingKey) {
            this.setNestedValue(this.editingRow, this.editingKey, this.editingOriginalValue);
        }
        this.editingKey = null;
        this.editingRow = null;
        this.editingValue = null;
        this.editingDate = null;
        this.editingOriginalValue = null;
    }

    private setNestedValue(obj: TableRow, path: string, value: unknown): void {
        if (!obj || !path) return;
        if (path in obj) {
            (obj as Record<string, unknown>)[path] = value;
            return;
        }
        const parts = path.split(".");
        let current: Record<string, unknown> = obj;
        for (let i = 0; i < parts.length - 1; i++) {
            const key = parts[i];
            if (current[key] == null || typeof current[key] !== "object") {
                current[key] = {};
            }
            current = current[key] as Record<string, unknown>;
        }
        current[parts[parts.length - 1]] = value;
    }

    public onColumnHeaderClick(column: EpTableColumn): void {
        if (!this.isSortable) return;

        if (this.currentSortField === column.key) {
            if (this.currentSortOrder === "asc") {
                this.currentSortOrder = "desc";
            } else if (this.currentSortOrder === "desc") {
                this.currentSortField = null;
                this.currentSortOrder = null;
            }
        } else {
            this.currentSortField = column.key;
            this.currentSortOrder = "asc";
        }

        this.updateDisplayedValues();
    }

    public getSortIcon(column: EpTableColumn): string {
        if (!this.isSortable) return getImagePath("assets/images/shared/arrow-down-grey.svg");

        if (this.currentSortField === column.key) {
            return getImagePath("assets/images/shared/arrow-down-blue.svg");
        } else if (this.hoveredColumn === column.key) {
            return getImagePath("assets/images/shared/arrow-down-grey.svg");
        }

        return getImagePath("assets/images/shared/arrow-down-grey.svg");
    }

    public onColumnHeaderMouseEnter(column: EpTableColumn): void {
        if (this.isSortable) {
            this.hoveredColumn = column.key;
        }
    }

    public onColumnHeaderMouseLeave(): void {
        this.hoveredColumn = null;
    }

    public toggleShowAll(): void {
        this.showAll = !this.showAll;
        this.updateDisplayedValues();
    }

    public shouldShowToggleButton(): boolean {
        return this.rows.length > this.visibleRowsQuantity;
    }

    public getToggleButtonText(): string {
        return this.showAll ? "Show less" : "Show more";
    }

    public getCellValue(row: TableRow, column: EpTableColumn): unknown {
        if (!column || !column.key) {
            return "";
        }
        const accessor = this.columnAccessors[column.key];
        const value = accessor ? accessor(row) : this.getNestedValue(row, column.key);
        if (column.type === "date" && value) {
            return this.formatDateValue(value);
        }
        return value;
    }

    private initializeColumns(): void {
        if (!this.columns || this.columns.length === 0) {
            console.warn(
                "MessageTableComponent: Cannot initialize columns - columns array is empty"
            );
            this.visibleColumns = [];
            return;
        }
        this.columns = this.applyUnionColumnOrdering(
            this.orderColumnsByRowKeys(this.columns, this.rows)
        );
        this.dynamicColumns = this.columns
            .filter((column) => column && column.key)
            .map((column, index) => ({
                key: column.key,
                title: column.title || column.key,
                visible: column.visible !== undefined ? column.visible : true,
                type: column.type,
                group: column.group,
                order: index,
                isHidable: true,
                isReorderable: true,
                isSortable: this.isSortable,
            }));
        this.visibleColumns = this.columns.filter((col) => col && col.visible !== false);
        this.buildColumnAccessors();
    }

    private orderColumnsByRowKeys(columns: EpTableColumn[], rows: TableRow[]): EpTableColumn[] {
        const cols = Array.isArray(columns) ? columns.slice() : [];
        if (!Array.isArray(rows) || rows.length === 0) {
            return cols;
        }
        const firstRow = rows[0] as Record<string, unknown>;
        const keys = Object.keys(firstRow || {});
        if (keys.length === 0) {
            return cols;
        }
        const byKey = new Map<string, EpTableColumn>();
        cols.forEach((col) => {
            if (col?.key) byKey.set(col.key, col);
        });
        const ordered: EpTableColumn[] = [];
        keys.forEach((key) => {
            const col = byKey.get(key);
            if (col) {
                ordered.push(col);
                byKey.delete(key);
            }
        });
        cols.forEach((col) => {
            if (col?.key && byKey.has(col.key)) {
                ordered.push(col);
                byKey.delete(col.key);
            }
        });
        return ordered;
    }

    public trackByColumn(index: number, column: EpTableColumn): string {
        return column.key;
    }

    public trackByRow(index: number, row: TableRow): TableRow {
        return row;
    }

    @HostListener("document:click", ["$event"])
    onDocumentClick(event: MouseEvent): void {
        const target = event.target as Node;
        const path = event.composedPath?.() ?? [];
        const hasMatchInPath = (selector: string): boolean =>
            path.some(
                (node) =>
                    node instanceof Element &&
                    (node.matches(selector) || node.closest(selector) !== null)
            );

        if (this.editingKey && this.editingRow) {
            const active =
                hasMatchInPath(
                    ".ep-message-table__cell-editor, .ep-message-table__cell-editor-wrapper, .ep-message-table__date-input, .mat-datepicker-content, .mat-mdc-datepicker-content, .mat-calendar, .mat-mdc-calendar, .mat-calendar-body-cell, .mat-calendar-body-cell-content, .mat-mdc-calendar-body-cell, .mat-mdc-calendar-body-cell-content, .cdk-overlay-pane, .cdk-overlay-container"
                ) ||
                (target as HTMLElement).closest(
                    ".ep-message-table__cell-editor, .ep-message-table__cell-editor-wrapper, .ep-message-table__date-input, .mat-datepicker-content, .mat-mdc-datepicker-content, .mat-calendar, .mat-mdc-calendar, .mat-calendar-body-cell, .mat-calendar-body-cell-content, .mat-mdc-calendar-body-cell, .mat-mdc-calendar-body-cell-content, .cdk-overlay-pane, .cdk-overlay-container"
                );

            if (!active) {
                const column = this.visibleColumns.find((c) => c.key === this.editingKey);

                if (column) {
                    this.applyEdit(this.editingRow, column);
                } else {
                    this.cancelEdit();
                }
            }
        }

        if (this.editingColumnKey) {
            const activeTitleEditor =
                hasMatchInPath(".ep-message-table__title-editor") ||
                (target as HTMLElement).closest(".ep-message-table__title-editor");
            if (!activeTitleEditor) {
                const column = this.visibleColumns.find((c) => c.key === this.editingColumnKey);
                if (column) {
                    this.applyColumnTitleEdit(column);
                } else {
                    this.cancelColumnTitleEdit();
                }
            }
        }

        if (this.showColumnsDropdown) {
            const dropdown =
                hasMatchInPath(".ep-message-table__columns-dropdown") ||
                (target as HTMLElement).closest(".ep-message-table__columns-dropdown");
            const manageButton =
                hasMatchInPath(".ep-message-table__manage") ||
                (target as HTMLElement).closest(".ep-message-table__manage");
            if (!dropdown && !manageButton) {
                this.showColumnsDropdown = false;
            }
        }
    }

    public onCellEditorInput(event: Event, row: TableRow, column: EpTableColumn): void {
        if (!this.isEditable || column.editable === false) return;
        const editor = event.target as HTMLElement;
        const newValue = editor.textContent || editor.innerText || "";
        this.editingValue = newValue;

        let processedValue: unknown = newValue;
        if (column.type === "number") {
            const parsed = Number(newValue);
            processedValue = isNaN(parsed) ? newValue : parsed;
        }
        this.setNestedValue(row, column.key, processedValue);
        this.recalculateMathColumnsForRow(row);

        const union = column?.key ? this.getUnionByColumnKey(column.key) : null;
        if (union) {
            if (union.ruleName === "percentage") {
                const sumValue = 100;
                const n = this.parseUnionNumber(processedValue);
                if (n == null || n < 0 || n > sumValue) {
                    this.validateUnionRow(row, union);
                } else if (union.keys.length === 2) {
                    const otherKey = union.keys.find((k) => k !== column.key);
                    if (otherKey) {
                        const otherVal = sumValue - n;
                        this.setNestedValue(row, otherKey, otherVal);
                    }
                    this.validateUnionRow(row, union);
                } else {
                    this.validateUnionRow(row, union);
                }
            } else if (union.ruleName === "datesSequence") {
                this.validateUnionRow(row, union);
            }
        }
        this.markTableAsChanged();
    }

    public onColumnTitleDblClick(column: EpTableColumn, event: MouseEvent): void {
        if (!this.isEditable || !this.isTitleEditable) return;
        event.stopPropagation();
        this.editingColumnKey = column.key;
        this.editingColumnTitle = column.title ?? column.key;
    }

    public onColumnTitleEditKeydown(event: KeyboardEvent, column: EpTableColumn): void {
        if (!this.isEditable || !this.isTitleEditable) return;
        if (event.key === "Enter") {
            this.applyColumnTitleEdit(column);
        } else if (event.key === "Escape") {
            this.cancelColumnTitleEdit();
        }
    }

    public applyColumnTitleEdit(column: EpTableColumn): void {
        if (!this.isEditable || !this.isTitleEditable) {
            this.cancelColumnTitleEdit();
            return;
        }
        if (this.editingColumnKey !== column.key) {
            this.cancelColumnTitleEdit();
            return;
        }
        if (this.editingColumnTitle !== null && this.editingColumnTitle !== undefined) {
            column.title = this.editingColumnTitle;
            const visibleCol = this.visibleColumns.find((c) => c.key === column.key);
            if (visibleCol) {
                visibleCol.title = this.editingColumnTitle;
            }
            this.markTableAsChanged();
        }
        this.cancelColumnTitleEdit();
    }

    public cancelColumnTitleEdit(): void {
        this.editingColumnKey = null;
        this.editingColumnTitle = null;
    }

    public onBooleanToggle(checked: boolean, row: TableRow, column: EpTableColumn): void {
        if (!this.isEditable || column.editable === false) return;
        this.setNestedValue(row, column.key, checked);
        this.recalculateMathColumnsForRow(row);
        this.markTableAsChanged();
    }

    public onDateChanged(date: Date | null, row: TableRow, column: EpTableColumn): void {
        if (!this.isEditable || column.editable === false) return;
        this.editingDate = date;
        const dateString = date ? this.formatDateForBackend(date) : "";
        this.setNestedValue(row, column.key, dateString);
        this.recalculateMathColumnsForRow(row);
        this.markTableAsChanged();
        this.applyEdit(row, column);
    }

    public onCellMouseOver(event: Event, row: TableRow, column: EpTableColumn): void {
        const cellElement = (event.target as HTMLElement).closest(
            ".ep-message-table__cell"
        ) as HTMLElement;
        if (!cellElement) {
            return;
        }
        const cellValue = this.getCellValue(row, column);
        if (this.isTextOverflowing(cellElement) && cellValue) {
            this.tooltipService.show(cellElement, String(cellValue));
        }
    }

    public onCellMouseLeave(event: Event): void {
        const cellElement = (event.target as HTMLElement).closest(
            ".ep-message-table__cell"
        ) as HTMLElement;
        if (cellElement) {
            this.tooltipService.hide(cellElement);
        }
    }

    private isTextOverflowing(element: HTMLElement): boolean {
        return element.scrollWidth > element.clientWidth;
    }

    public getBooleanCellValue(row: TableRow, column: EpTableColumn): boolean {
        const value = this.getNestedValue(row, column.key);
        return !!value;
    }

    public onDropdownFocus(): void {
        return;
    }

    public getDropdownOptions(row: TableRow, column: EpTableColumn): DropdownOption[] {
        const state = this.getDropdownState(row, column);
        if (state) {
            return state.options;
        }
        const cellValue = this.getNestedValue(row, column.key);
        return this.normalizeDropdownOptions(cellValue);
    }

    public getDropdownSelection(
        row: TableRow,
        column: EpTableColumn
    ): DropdownOption[] | DropdownOption | null {
        const state = this.getDropdownState(row, column);
        if (!state) {
            const cellValue = this.getNestedValue(row, column.key);
            const options = this.normalizeDropdownOptions(cellValue);
            const selectionKey = this.getDropdownSelectionKey(column.key);
            const selectionValue = this.getNestedValue(row, selectionKey);
            if (selectionValue !== undefined) {
                return this.getSelectedFromValue(selectionValue, options, column);
            }
            const preselectedValue = this.extractPreselectedValues(cellValue, column);
            if (preselectedValue !== null && preselectedValue !== undefined) {
                return this.getSelectedFromValue(preselectedValue, options, column);
            }
            return column.type === "multiSelect" ? [] : null;
        }
        if (column.type === "multiSelect") {
            return (state.selected as DropdownOption[]) ?? [];
        }
        return (state.selected as DropdownOption) ?? null;
    }

    public onSelectDropdownChange(
        option: DropdownOption | null,
        row: TableRow,
        column: EpTableColumn
    ): void {
        let rowMap = this.dropdownState.get(row);
        if (!rowMap) {
            rowMap = new Map<string, DropdownCellState>();
            this.dropdownState.set(row, rowMap);
        }

        let state = rowMap.get(column.key);
        if (!state) {
            const cellValue = this.getNestedValue(row, column.key);
            const options = this.normalizeDropdownOptions(cellValue);
            state = { options, selected: null };
            rowMap.set(column.key, state);
        }

        const isCleared = option == null;
        state.selected = isCleared ? null : option;
        this.applyDropdownValueToRow(row, column, isCleared ? null : option);
        this.recalculateMathColumnsForRow(row);
        this.markTableAsChanged();
    }

    public onMultiSelectChange(
        selection: DropdownOption[],
        row: TableRow,
        column: EpTableColumn
    ): void {
        let rowMap = this.dropdownState.get(row);
        if (!rowMap) {
            rowMap = new Map<string, DropdownCellState>();
            this.dropdownState.set(row, rowMap);
        }

        let state = rowMap.get(column.key);
        if (!state) {
            const cellValue = this.getNestedValue(row, column.key);
            const options = this.normalizeDropdownOptions(cellValue);
            state = { options, selected: [] };
            rowMap.set(column.key, state);
        }

        state.selected = selection;
        this.applyDropdownValueToRow(row, column, state.selected);
        this.recalculateMathColumnsForRow(row);
        this.markTableAsChanged();
    }

    private applyDropdownValueToRow(
        row: TableRow,
        column: EpTableColumn,
        selected: DropdownOption[] | DropdownOption | null
    ): void {
        if (!this.isColumnEditable(column)) return;

        let value: unknown = null;
        if (column.type === "multiSelect") {
            value = Array.isArray(selected) ? selected.map((opt) => opt.Id ?? opt.Name) : [];
        } else if (selected) {
            const selectedOption = selected as DropdownOption;
            value = selectedOption?.Id ?? selectedOption?.Name ?? null;
        }
        this.setNestedValue(row, this.getDropdownSelectionKey(column.key), value);
    }

    private getDropdownSelectionKey(columnKey: string): string {
        return `${this.dropdownSelectionPrefix}${columnKey}`;
    }

    private getDropdownState(row: TableRow, column: EpTableColumn): DropdownCellState | null {
        const rowMap = this.dropdownState.get(row);
        if (!rowMap) {
            return null;
        }
        return rowMap.get(column.key) || null;
    }

    private normalizeDropdownOptions(value: unknown): DropdownOption[] {
        if (value == null) return [];
        const seen = new Set<string>();
        const options: DropdownOption[] = [];

        if (Array.isArray(value)) {
            value.forEach((v) => {
                if (v == null) return;
                let strVal: string;
                if (typeof v === "object" && "value" in (v as Record<string, unknown>)) {
                    const val = (v as { value?: unknown }).value;
                    if (val == null) return;
                    strVal = String(val).trim();
                } else {
                    strVal = String(v).trim();
                }
                if (strVal.length > 0 && !seen.has(strVal)) {
                    seen.add(strVal);
                    options.push({ Id: strVal, Name: strVal });
                }
            });
        } else if (typeof value === "string") {
            value
                .split(",")
                .map((v) => v.trim())
                .filter((v) => v.length > 0 && !seen.has(v))
                .forEach((v) => {
                    seen.add(v);
                    options.push({ Id: v, Name: v });
                });
        } else {
            const strVal = String(value).trim();
            if (strVal.length > 0) {
                options.push({ Id: strVal, Name: strVal });
            }
        }

        return options;
    }

    private getSelectedFromValue(
        value: unknown,
        options: DropdownOption[],
        column: EpTableColumn
    ): DropdownOption[] | DropdownOption | null {
        if (value == null) {
            return column.type === "multiSelect" ? [] : null;
        }
        if (column.type === "multiSelect") {
            const selected: DropdownOption[] = [];
            let valueArray: unknown[] = [];
            if (Array.isArray(value)) {
                valueArray = value;
            } else if (typeof value === "string") {
                valueArray = value
                    .split(",")
                    .map((v) => v.trim())
                    .filter((v) => v.length > 0);
            } else {
                valueArray = [value];
            }
            const optionsMap = new Map(options.map((opt) => [opt.Id, opt]));
            valueArray.forEach((val) => {
                const valStr = String(val);
                const option = optionsMap.get(valStr);
                selected.push(option || { Id: valStr, Name: valStr });
            });
            return selected;
        }
        const valStr = String(value);
        const option = options.find((opt) => opt.Id === valStr);
        if (option) return option;
        return valStr ? { Id: valStr, Name: valStr } : null;
    }

    private extractPreselectedValues(value: unknown, column: EpTableColumn): unknown {
        if (value == null || !Array.isArray(value)) {
            return column.type === "multiSelect" ? [] : null;
        }
        const preselected: unknown[] = [];
        value.forEach((v) => {
            if (v && typeof v === "object" && "value" in (v as Record<string, unknown>)) {
                const isChecked = (v as { isChecked?: unknown }).isChecked;
                if (isChecked === true || isChecked === "True" || isChecked === 1) {
                    preselected.push((v as { value?: unknown }).value);
                }
            }
        });
        if (preselected.length === 0) {
            return column.type === "multiSelect" ? [] : null;
        }
        if (column.type === "select") {
            return preselected[0];
        }
        return preselected;
    }

    private prepareAllDropdownStates(): void {
        if (
            this.dropdownStatesPrepared ||
            !Array.isArray(this.rows) ||
            !Array.isArray(this.columns)
        ) {
            return;
        }
        const selectColumns = this.columns.filter(
            (col) => col && (col.type === "select" || col.type === "multiSelect")
        );
        if (selectColumns.length === 0) {
            this.dropdownStatesPrepared = true;
            return;
        }
        for (const row of this.rows) {
            let rowMap = this.dropdownState.get(row);
            if (!rowMap) {
                rowMap = new Map<string, DropdownCellState>();
                this.dropdownState.set(row, rowMap);
            }
            for (const column of selectColumns) {
                if (rowMap.has(column.key)) continue;
                const cellValue = this.getNestedValue(row, column.key);
                const options = this.normalizeDropdownOptions(cellValue);
                const selectionKey = this.getDropdownSelectionKey(column.key);
                const selectionValue = this.getNestedValue(row, selectionKey);

                let selected: DropdownOption[] | DropdownOption | null;
                if (selectionValue !== undefined) {
                    selected = this.getSelectedFromValue(selectionValue, options, column);
                } else {
                    const preselectedValue = this.extractPreselectedValues(cellValue, column);
                    if (preselectedValue !== null && preselectedValue !== undefined) {
                        selected = this.getSelectedFromValue(preselectedValue, options, column);
                        this.setNestedValue(row, selectionKey, preselectedValue);
                    } else {
                        selected = column.type === "multiSelect" ? [] : null;
                    }
                }
                rowMap.set(column.key, { options, selected });
            }
        }
        this.dropdownStatesPrepared = true;
    }

    private markTableAsChanged(): void {
        if (!this.hasAnyChanges && Array.isArray(this.tableActions)) {
            const hasReset = this.tableActions.some(
                (a) => a?.action === UserAction.EpicstaffResetTable
            );
            if (!hasReset) {
                this.tableActions.push({
                    action: UserAction.EpicstaffResetTable,
                    type: "button",
                    text: "Undo changes",
                });
            }
        }
        this.hasAnyChanges = true;
    }

    private parseDateValue(value: unknown): Date | null {
        if (!value) return null;
        if (value instanceof Date) return value;
        if (typeof value === "string") {
            const trimmed = value.trim();
            if (!trimmed) return null;

            const timestampMatch = trimmed.match(/^\d{10,13}$/);
            if (timestampMatch) {
                let timestamp = parseInt(trimmed, 10);
                if (trimmed.length === 10) {
                    timestamp = timestamp * 1000;
                }
                const date = new Date(timestamp);
                if (!isNaN(date.getTime())) {
                    return date;
                }
            }

            const isoMatch = trimmed.match(/^\d{4}-\d{2}-\d{2}/);
            if (isoMatch) {
                const date = new Date(trimmed);
                if (!isNaN(date.getTime())) {
                    return date;
                }
            }

            const ddmmyyMatch = trimmed.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})$/);
            if (ddmmyyMatch) {
                const part1 = parseInt(ddmmyyMatch[1], 10);
                const part2 = parseInt(ddmmyyMatch[2], 10);
                let year = parseInt(ddmmyyMatch[3], 10);
                if (year < 100) {
                    year += year < 50 ? 2000 : 1900;
                }

                let day: number, month: number;
                if (part1 > 12) {
                    day = part1;
                    month = part2 - 1;
                } else if (part2 > 12) {
                    month = part1 - 1;
                    day = part2;
                } else {
                    day = part1;
                    month = part2 - 1;
                }

                const date = new Date(year, month, day);
                if (!isNaN(date.getTime())) {
                    return date;
                }
            }

            const date = new Date(trimmed);
            if (!isNaN(date.getTime())) {
                return date;
            }
        }
        if (typeof value === "number") {
            let timestamp = value;
            if (value.toString().length === 10) {
                timestamp = value * 1000;
            }
            const date = new Date(timestamp);
            if (!isNaN(date.getTime())) {
                return date;
            }
        }
        return null;
    }

    public getDatePickerMinDate(row: TableRow, column: EpTableColumn): Date | string | null {
        if (!row || !column || column.type !== "date" || !column.key) {
            return column?.minDate ?? null;
        }

        const baseMin = this.parseDateValue(column.minDate ?? null);
        const union = this.getUnionByColumnKey(column.key);
        if (!union || union.ruleName !== "datesSequence") {
            return baseMin ?? column.minDate ?? null;
        }

        const columnIndex = union.keys.indexOf(column.key);
        if (columnIndex <= 0) {
            return baseMin ?? column.minDate ?? null;
        }

        const prevKey = union.keys[columnIndex - 1];
        if (!this.isDateColumnKey(prevKey)) {
            return baseMin ?? column.minDate ?? null;
        }

        const prevDate = this.parseDateValue(this.getNestedValue(row, prevKey));
        if (!prevDate) {
            return baseMin ?? column.minDate ?? null;
        }

        const normalizedPrev = this.toDateOnly(prevDate);
        if (!baseMin) {
            return normalizedPrev;
        }

        const normalizedBase = this.toDateOnly(baseMin);
        return normalizedPrev.getTime() > normalizedBase.getTime()
            ? normalizedPrev
            : normalizedBase;
    }

    private formatDateValue(value: unknown): string {
        if (!value) return "";
        const date = this.parseDateValue(value);
        if (date) {
            return date.toLocaleDateString("en-GB");
        }
        return String(value);
    }

    private formatDateForBackend(date: Date): string {
        if (!date || !(date instanceof Date) || isNaN(date.getTime())) {
            return "";
        }
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        return `${year}-${month}-${day}`;
    }

    public onRowSelect(row: TableRow, event: Event | MouseEvent): void {
        if (this.rowsSelectionType === "select") {
            this.selectedRow = this.selectedRow === row ? null : row;
            this.updateSelectedRowIndices();
        } else if (this.rowsSelectionType === "multiSelect") {
            if (this.selectedRows.has(row)) {
                this.selectedRows.delete(row);
            } else {
                this.selectedRows.add(row);
            }
            this.updateSelectedRowIndices();
        }
        if ((event as Event)?.stopPropagation) {
            event.stopPropagation();
        }
    }

    private updateSelectedRowIndices(): void {
        const tables = (this.message?.response?._tables || []) as Array<{
            id?: string;
            selectedRowIndices?: number[];
        }>;
        const table = tables.find((t) => t.id === this.id);
        if (!table) return;

        if (this.rowsSelectionType === "select") {
            if (this.selectedRow) {
                const index = this.rows.findIndex((r) => r === this.selectedRow);
                table.selectedRowIndices = index !== -1 ? [index] : [];
            } else {
                table.selectedRowIndices = [];
            }
        } else if (this.rowsSelectionType === "multiSelect") {
            table.selectedRowIndices = this.rows
                .map((row, index) => (this.selectedRows.has(row) ? index : -1))
                .filter((index) => index !== -1);
        }
    }

    public isRowSelected(row: TableRow): boolean {
        if (this.rowsSelectionType === "select") {
            return this.selectedRow === row;
        }
        if (this.rowsSelectionType === "multiSelect") {
            return this.selectedRows.has(row);
        }
        return false;
    }

    private restoreSelectedRows(): void {
        if (!this.rows || this.rows.length === 0) {
            return;
        }
        const tables = (this.message?.response?._tables || []) as Array<{
            id?: string;
            selectedRowIndices?: number[];
        }>;
        const table = tables.find((t) => t.id === this.id);
        if (!table) return;

        if (
            this.preselectedRows &&
            Array.isArray(this.preselectedRows) &&
            this.preselectedRows.length > 0
        ) {
            if (this.rowsSelectionType === "select" || this.rowsSelectionType === "multiSelect") {
                this.applyPreselectedRows();
                return;
            }
        }

        if (!table.selectedRowIndices || !Array.isArray(table.selectedRowIndices)) return;

        if (this.rowsSelectionType === "select" && table.selectedRowIndices.length > 0) {
            const index = table.selectedRowIndices[0];
            if (index >= 0 && index < this.rows.length) {
                this.selectedRow = this.rows[index];
                this.updateSelectedRowIndices();
            }
        } else if (this.rowsSelectionType === "multiSelect") {
            this.selectedRows.clear();
            table.selectedRowIndices.forEach((index: number) => {
                if (index >= 0 && index < this.rows.length) {
                    this.selectedRows.add(this.rows[index]);
                }
            });
            this.updateSelectedRowIndices();
        }
    }

    private applyPreselectedRows(): void {
        if (
            !this.preselectedRows ||
            !Array.isArray(this.preselectedRows) ||
            this.preselectedRows.length === 0
        ) {
            return;
        }
        if (this.rowsSelectionType === "select") {
            const index = parseInt(this.preselectedRows[0], 10);
            if (!isNaN(index) && index >= 0 && index < this.rows.length) {
                this.selectedRow = this.rows[index];
                this.updateSelectedRowIndices();
            }
        } else if (this.rowsSelectionType === "multiSelect") {
            this.selectedRows.clear();
            this.preselectedRows.forEach((indexStr: string) => {
                const index = parseInt(indexStr, 10);
                if (!isNaN(index) && index >= 0 && index < this.rows.length) {
                    this.selectedRows.add(this.rows[index]);
                }
            });
            this.updateSelectedRowIndices();
        }
    }

    private initializeUnions(): void {
        this.unionIndexByKey = new Map<string, number>();
        this.unionsNormalized = [];
        this.unionErrorKeysByRow = new WeakMap<TableRow, Map<number, Set<string>>>();

        const raw = Array.isArray(this.unions) ? this.unions : [];
        let idx = 0;
        raw.forEach((u) => {
            const keys = Array.isArray(u?.keys) ? u.keys.filter(Boolean) : [];
            if (keys.length < 2) return;
            const title = (u?.title || "").trim();
            const rawRule = (u?.ruleName || "").trim();
            const ruleName =
                rawRule === "percentage" || rawRule === "datesSequence"
                    ? (rawRule as UnionRuleName)
                    : "";
            this.unionsNormalized.push({ keys, index: idx, title, ruleName });
            keys.forEach((k) => this.unionIndexByKey.set(k, idx));
            idx++;
        });
        this.hasUnions = this.unionsNormalized.length > 0;

        if (!Array.isArray(this.rows) || this.unionsNormalized.length === 0) return;

        for (const row of this.rows) {
            for (const u of this.unionsNormalized) {
                if (u.ruleName === "percentage") {
                    const sum = 100;
                    const values = u.keys.map((k) => this.getNestedValue(row, k));
                    const allEmpty = values.every((v) => v === undefined || v === null || v === "");
                    if (allEmpty) {
                        const n = u.keys.length;
                        const base = Math.floor(sum / n);
                        const remainder = sum - base * n;
                        u.keys.forEach((k, i) => {
                            const val = i === n - 1 ? base + remainder : base;
                            this.setNestedValue(row, k, val);
                        });
                    }
                    this.validateUnionRow(row, u);
                } else if (u.ruleName === "datesSequence") {
                    this.validateUnionRow(row, u);
                }
            }
        }
    }

    public isUnionColumn(column: EpTableColumn): boolean {
        return !!column?.key && this.unionIndexByKey.has(column.key);
    }

    public isUnionStartColumn(column: EpTableColumn): boolean {
        const union = column?.key ? this.getUnionByColumnKey(column.key) : null;
        if (!union) return false;
        return union.keys[0] === column.key;
    }

    public getUnionTitleByColumn(column: EpTableColumn): string {
        const union = column?.key ? this.getUnionByColumnKey(column.key) : null;
        if (!union) return "";
        return union.title || "";
    }

    public getUnionColspanByColumn(column: EpTableColumn): number {
        const union = column?.key ? this.getUnionByColumnKey(column.key) : null;
        if (!union) return 1;
        const keysSet = new Set(union.keys);
        return this.visibleColumns.filter((c) => !!c?.key && keysSet.has(c.key)).length || 1;
    }

    public hasUnionError(row: TableRow, column: EpTableColumn): boolean {
        if (!row || !column?.key) return false;
        const map = this.unionErrorKeysByRow.get(row);
        if (!map) return false;
        for (const set of map.values()) {
            if (set.has(column.key)) {
                return true;
            }
        }
        return false;
    }

    private getUnionByColumnKey(columnKey: string): {
        keys: string[];
        index: number;
        title: string;
        ruleName: UnionRuleName;
    } | null {
        const idx = this.unionIndexByKey.get(columnKey);
        if (idx == null) return null;
        return this.unionsNormalized.find((u) => u.index === idx) || null;
    }

    private validateUnionRow(
        row: TableRow,
        union: {
            keys: string[];
            index: number;
            title: string;
            ruleName: UnionRuleName;
        }
    ): void {
        if (!row) return;
        const errorKeys = new Set<string>();

        if (union.ruleName === "percentage") {
            const sumValue = 100;
            let sum = 0;
            let hasInvalid = false;

            union.keys.forEach((k) => {
                const raw = this.getNestedValue(row, k);
                const n =
                    typeof raw === "number" ? raw : raw === "" || raw == null ? null : Number(raw);
                if (n == null || !Number.isFinite(n) || isNaN(n)) {
                    hasInvalid = true;
                    errorKeys.add(k);
                    return;
                }
                if (n < 0 || n > sumValue) {
                    hasInvalid = true;
                    errorKeys.add(k);
                }
                sum += n;
            });

            if (!hasInvalid && sum !== sumValue) {
                union.keys.forEach((k) => errorKeys.add(k));
            }
        } else if (union.ruleName === "datesSequence") {
            for (let i = 1; i < union.keys.length; i += 1) {
                const prevKey = union.keys[i - 1];
                const currKey = union.keys[i];
                const prevDate = this.parseDateValue(this.getNestedValue(row, prevKey));
                const currDate = this.parseDateValue(this.getNestedValue(row, currKey));
                if (!prevDate || !currDate) continue;
                const prevTime = this.toDateOnly(prevDate).getTime();
                const currTime = this.toDateOnly(currDate).getTime();
                if (currTime < prevTime) {
                    errorKeys.add(prevKey);
                    errorKeys.add(currKey);
                }
            }
        }

        let map = this.unionErrorKeysByRow.get(row);
        if (!map) {
            map = new Map<number, Set<string>>();
            this.unionErrorKeysByRow.set(row, map);
        }

        if (errorKeys.size > 0) {
            map.set(union.index, errorKeys);
        } else {
            map.delete(union.index);
        }

        if (map.size === 0) {
            this.unionErrorKeysByRow.delete(row);
        }
    }

    private isDateColumnKey(key: string): boolean {
        return !!this.columns.find((c) => c?.key === key && c?.type === "date");
    }

    private toDateOnly(date: Date): Date {
        const d = new Date(date.getTime());
        d.setHours(0, 0, 0, 0);
        return d;
    }

    private parseUnionNumber(raw: unknown): number | null {
        if (raw === "" || raw == null) return null;
        const n = typeof raw === "number" ? raw : Number(raw);
        if (!Number.isFinite(n) || isNaN(n)) return null;
        return Math.round(n);
    }

    private normalizeKeyForMath(key: string): string {
        if (!key) return "_";
        let normalized = key.replace(/[^0-9A-Za-z_]/g, "_");
        if (!normalized) {
            normalized = "_";
        }
        if (/^[0-9]/.test(normalized)) {
            normalized = `_${normalized}`;
        }
        return normalized;
    }

    private recalculateMathForAllRows(): void {
        if (!Array.isArray(this.rows) || !this.columns || this.columns.length === 0) {
            return;
        }
        for (const row of this.rows) {
            this.recalculateMathColumnsForRow(row);
        }
    }

    private recalculateMathColumnsForRow(row: TableRow): void {
        if (!this.columns || this.columns.length === 0) return;
        for (const column of this.columns) {
            const mathExpr = (column as EpTableColumn & { params?: { math?: string } }).params
                ?.math;
            if (!mathExpr || typeof mathExpr !== "string") continue;
            const result = this.evaluateMathExpression(row, mathExpr);
            if (result == null) continue;
            this.setNestedValue(row, column.key, result);
        }
    }

    private evaluateMathExpression(row: TableRow, expr: string): number | null {
        if (!expr || typeof expr !== "string") return null;
        try {
            let compiled = this.mathExpressionCache.get(expr);
            if (!compiled) {
                compiled = this.mathParser.parse(expr);
                this.mathExpressionCache.set(expr, compiled);
            }

            const variables = compiled.variables();
            const valueByNormalizedKey = new Map<string, number | null>();
            if (Array.isArray(this.columns)) {
                for (const col of this.columns) {
                    if (!col?.key) continue;
                    const norm = this.normalizeKeyForMath(col.key);
                    if (valueByNormalizedKey.has(norm)) continue;
                    const raw = this.getNestedValue(row, col.key);
                    const n = this.parseUnionNumber(raw);
                    valueByNormalizedKey.set(norm, n);
                }
            }

            const scope: Record<string, unknown> = {};
            for (const name of variables) {
                const normName = this.normalizeKeyForMath(name);
                let n: number | null | undefined = valueByNormalizedKey.get(normName);
                if (n === undefined) {
                    const value = this.getNestedValue(row, name);
                    n = this.parseUnionNumber(value);
                }
                if (n == null) {
                    return null;
                }
                scope[name] = n;
            }

            const evaluated = compiled.evaluate(scope as never);
            if (typeof evaluated !== "number" || !Number.isFinite(evaluated)) {
                return null;
            }
            return evaluated;
        } catch {
            return null;
        }
    }

    private applyUnionColumnOrdering(columns: EpTableColumn[]): EpTableColumn[] {
        const cols = Array.isArray(columns) ? columns.slice() : [];
        const unions = Array.isArray(this.unions) ? this.unions : [];
        if (!unions.length || !cols.length) return cols;

        const keyToGroup = new Map<string, { keys: string[]; title?: string; start: number }>();
        unions.forEach((u) => {
            const keys = Array.isArray(u?.keys) ? u.keys.filter(Boolean) : [];
            if (keys.length < 2) return;
            let start = Infinity;
            keys.forEach((k) => {
                const i = cols.findIndex((c) => c?.key === k);
                if (i !== -1) start = Math.min(start, i);
            });
            if (start === Infinity) return;
            const group = { keys, title: u.title, start };
            keys.forEach((k) => keyToGroup.set(k, group));
        });

        const emittedGroups = new Set<unknown>();
        const out: EpTableColumn[] = [];
        for (let i = 0; i < cols.length; i++) {
            const col = cols[i];
            const group = col?.key ? keyToGroup.get(col.key) : undefined;
            if (!group) {
                out.push(col);
                continue;
            }
            if (emittedGroups.has(group)) {
                continue;
            }
            emittedGroups.add(group);
            group.keys.forEach((k) => {
                const c = cols.find((x) => x?.key === k);
                if (c) out.push(c);
            });
        }

        return out;
    }

    private reorderKeysWithUnions(orderKeys: string[], movedKey: string | null): string[] {
        const keys = Array.isArray(orderKeys) ? orderKeys.slice() : [];
        if (!this.unionsNormalized.length || keys.length === 0) return keys;

        if (movedKey && this.unionIndexByKey.has(movedKey)) {
            const union = this.getUnionByColumnKey(movedKey);
            if (union) {
                const groupKeys = union.keys.filter((k) => keys.includes(k));
                const targetIndex = keys.indexOf(movedKey);
                const removedBeforeTarget = keys
                    .slice(0, targetIndex)
                    .filter((k) => groupKeys.includes(k)).length;
                const filtered = keys.filter((k) => !groupKeys.includes(k));
                const insertIndex = Math.max(
                    0,
                    Math.min(filtered.length, targetIndex - removedBeforeTarget)
                );
                filtered.splice(insertIndex, 0, ...groupKeys);
                return this.reorderKeysWithUnions(filtered, null);
            }
        }

        const processed = new Set<number>();
        const out: string[] = [];
        for (const k of keys) {
            const idx = this.unionIndexByKey.get(k);
            if (idx == null) {
                out.push(k);
                continue;
            }
            if (processed.has(idx)) {
                continue;
            }
            processed.add(idx);
            const union = this.unionsNormalized.find((u) => u.index === idx);
            if (!union) continue;
            union.keys.forEach((uk) => {
                if (keys.includes(uk)) out.push(uk);
            });
        }
        return out;
    }

    public onColumnsUpdated(updatedColumns: DynamicColumn[]): void {
        const prevOrderKeys = (this.dynamicColumns || [])
            .slice()
            .sort((a, b) => a.order - b.order)
            .map((c) => c.key);

        const nextOrderKeysRaw = (updatedColumns || [])
            .slice()
            .sort((a, b) => a.order - b.order)
            .map((c) => c.key);

        let movedKey: string | null = null;
        if (prevOrderKeys.length && nextOrderKeysRaw.length) {
            const prevIndex = new Map<string, number>();
            const nextIndex = new Map<string, number>();
            prevOrderKeys.forEach((k, i) => prevIndex.set(k, i));
            nextOrderKeysRaw.forEach((k, i) => nextIndex.set(k, i));
            let bestKey: string | null = null;
            let bestDelta = 0;
            for (const k of nextOrderKeysRaw) {
                const pi = prevIndex.get(k);
                const ni = nextIndex.get(k);
                if (pi == null || ni == null) continue;
                const delta = ni - pi;
                if (Math.abs(delta) > Math.abs(bestDelta)) {
                    bestDelta = delta;
                    bestKey = k;
                }
            }
            movedKey = bestKey;
        }

        const nextOrderKeys = this.reorderKeysWithUnions(nextOrderKeysRaw, movedKey);
        this.dynamicColumns = updatedColumns;

        const newColumns: EpTableColumn[] = [];
        const dynByKey = new Map<string, DynamicColumn>();
        (updatedColumns || []).forEach((d) => d?.key && dynByKey.set(d.key, d));

        nextOrderKeys.forEach((key) => {
            const originalCol = this.columns.find((col) => col.key === key);
            const dyn = dynByKey.get(key);
            if (originalCol) {
                newColumns.push({
                    ...originalCol,
                    visible: dyn?.visible,
                });
            }
        });

        this.columns = newColumns;

        const dynByKey2 = new Map<string, DynamicColumn>();
        (updatedColumns || []).forEach((c) => c?.key && dynByKey2.set(c.key, c));
        this.dynamicColumns = this.columns
            .filter((c) => c && c.key)
            .map((c, index) => {
                const existing = dynByKey2.get(c.key);
                return {
                    key: c.key,
                    title: c.title || existing?.title || c.key,
                    visible: c.visible !== undefined ? c.visible : (existing?.visible ?? true),
                    type: c.type ?? existing?.type,
                    group: c.group ?? existing?.group,
                    order: index,
                    isHidable: existing?.isHidable ?? true,
                    isReorderable: existing?.isReorderable ?? true,
                    isSortable: existing?.isSortable ?? this.isSortable,
                };
            });

        this.visibleColumns = this.columns.filter((col) => col && col.visible !== false);
        this.buildColumnAccessors();
        this.updateDisplayedValues();
    }

    public toggleColumnsDropdown(): void {
        if (this.showColumnsDropdown) {
            this.showColumnsDropdown = false;
            this.isColumnsDropdownPositioned = false;
            this.columnsDropdownStyles = {};
            return;
        }

        this.isColumnsDropdownPositioned = false;
        this.updateColumnsDropdownPosition();
        this.showColumnsDropdown = true;
        this.cdr.markForCheck();

        setTimeout(() => {
            if (!this.showColumnsDropdown) {
                return;
            }

            this.updateColumnsDropdownPosition();
            this.isColumnsDropdownPositioned = true;
            this.cdr.markForCheck();
        });
    }

    @HostListener("window:resize")
    onWindowResize(): void {
        if (this.showColumnsDropdown) {
            this.updateColumnsDropdownPosition();
        }
    }

    private updateColumnsDropdownPosition(): void {
        const toggleEl = this.columnsToggle?.nativeElement;
        if (!toggleEl) return;

        const rect = toggleEl.getBoundingClientRect();
        const dropdownEl = this.columnsDropdown?.nativeElement;
        const dropdownRect = dropdownEl?.getBoundingClientRect();
        const viewportWidth = window.innerWidth;
        const viewportHeight = window.innerHeight;
        const spacing = 4;
        const viewportPadding = 8;
        const estimatedWidth = 360;
        const estimatedHeight = 400;
        const dropdownWidth = dropdownRect?.width || estimatedWidth;
        const dropdownHeight = dropdownRect?.height || estimatedHeight;

        let left = rect.left;
        let top = rect.bottom + spacing;

        if (left + dropdownWidth + viewportPadding > viewportWidth) {
            left = viewportWidth - dropdownWidth - viewportPadding;
        }
        if (left < viewportPadding) {
            left = viewportPadding;
        }

        if (top + dropdownHeight + viewportPadding > viewportHeight) {
            const topAbove = rect.top - dropdownHeight - spacing;
            top =
                topAbove >= viewportPadding
                    ? topAbove
                    : viewportHeight - dropdownHeight - viewportPadding;
        }
        if (top < viewportPadding) {
            top = viewportPadding;
        }

        this.columnsDropdownStyles = {
            top: `${Math.round(top)}px`,
            left: `${Math.round(left)}px`,
        };
    }
}
