import { HttpClient, HttpHeaders } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { firstValueFrom } from "rxjs";
import { STORAGE_KEYS } from "../constants/storage.constants";
import {
    EpicstaffMessageData,
    EpicstaffMessagesSseMessage,
    EpicstaffResponse,
    EpicstaffSessionResponse,
    EpicstaffStatusSseMessage,
    extractOutputFromFinishMessage,
    isFinishMessageData,
    isStreamMessageData,
} from "../models/epicstaff-api.model";
import { EpMessage, EpResponse } from "../models/message.model";
import { getCurrentTimestamp } from "../utils/message.utils";
import { ActionService } from "./action.service";
import { StorageService } from "./storage.service";

export type EpicstaffBasicAuth = {
    login: string;
    password: string;
};

const STREAM_CANCEL_ERROR = "EPICCHAT_STREAM_CANCELLED";

export type EpicstaffStreamUpdate = {
    messageType: string;
    text: string;
    toolCalls: Array<Record<string, unknown>>;
    isFinal: boolean;
    nodeName?: string;
};

@Injectable({ providedIn: "root" })
export class ApiService {
    private activeSseCancel: (() => void) | null = null;

    constructor(
        private http: HttpClient,
        private actionService: ActionService,
        private storageService: StorageService
    ) {}

    cancelActiveSse(): void {
        if (this.activeSseCancel) {
            this.activeSseCancel();
            this.activeSseCancel = null;
        }
    }

    /**
     * Creates HTTP headers with Basic Authentication
     */
    private createAuthHeaders(auth: EpicstaffBasicAuth): HttpHeaders {
        const credentials = btoa(`${auth.login}:${auth.password}`);
        return new HttpHeaders({
            Authorization: `Basic ${credentials}`,
        });
    }

    async sendMessage(
        message: string,
        agentUrl?: string,
        flowId?: number | null,
        attachedFiles?: File[],
        chatHistory?: EpMessage[],
        userParams?: Record<string, string>,
        basicAuth?: EpicstaffBasicAuth,
        contextExtras?: Record<string, unknown>,
        onStreamUpdate?: (update: EpicstaffStreamUpdate) => void,
        timeout: number = 120000
    ): Promise<EpMessage> {
        if (agentUrl && flowId !== null && flowId !== undefined) {
            return await this.sendEpicstaffRequest({
                agentUrl,
                flowId,
                attachedFiles: attachedFiles || [],
                chatHistory,
                userParams,
                basicAuth,
                contextExtras,
                userInput: message,
                onStreamUpdate,
                timeout,
            });
        }

        return this.createMissingAgentMessage();
    }

    /**
     * Send action message with user_action instead of user_input
     */
    async sendActionMessage(
        actionText: string,
        agentUrl?: string,
        flowId?: number | null,
        attachedFiles?: File[],
        chatHistory?: EpMessage[],
        userParams?: Record<string, string>,
        basicAuth?: EpicstaffBasicAuth,
        contextExtras?: Record<string, unknown>,
        onStreamUpdate?: (update: EpicstaffStreamUpdate) => void,
        timeout: number = 120000
    ): Promise<EpMessage> {
        if (agentUrl && flowId !== null && flowId !== undefined) {
            return await this.sendEpicstaffRequest({
                agentUrl,
                flowId,
                attachedFiles: attachedFiles || [],
                chatHistory,
                userParams,
                basicAuth,
                contextExtras,
                userAction: actionText,
                onStreamUpdate,
                timeout,
            });
        }

        return this.createMissingAgentMessage();
    }

    private createMissingAgentMessage(): EpMessage {
        return {
            id: `msg_${Date.now()}`,
            response: {
                message: "Please create an agent with a valid URL and flow ID.",
            },
            time: getCurrentTimestamp(),
        };
    }

    private async sendEpicstaffRequest(params: {
        agentUrl: string;
        flowId: number;
        attachedFiles: File[];
        chatHistory?: EpMessage[];
        userParams?: Record<string, string>;
        basicAuth?: EpicstaffBasicAuth;
        contextExtras?: Record<string, unknown>;
        userInput?: string;
        userAction?: string;
        onStreamUpdate?: (update: EpicstaffStreamUpdate) => void;
        timeout?: number;
    }): Promise<EpMessage> {
        try {
            const {
                flowId,
                attachedFiles,
                chatHistory,
                userParams,
                basicAuth,
                contextExtras,
                userInput,
                userAction,
                onStreamUpdate,
                timeout = 120000,
            } = params;
            const agentUrl = params.agentUrl.replace(/\/+$/, "");
            const formData = new FormData();
            formData.append("graph_id", String(flowId));

            const chatHistoryFormatted = this.formatChatHistory(chatHistory || []);
            const context: Record<string, unknown> = {
                chat_history: chatHistoryFormatted,
            };
            if (typeof userInput === "string") {
                context["user_input"] = userInput;
            }
            if (typeof userAction === "string") {
                context["user_action"] = userAction;
            }

            // Add user_params if provided
            if (userParams && Object.keys(userParams).length > 0) {
                context["user_params"] = userParams;
            }
            if (contextExtras && Object.keys(contextExtras).length > 0) {
                Object.assign(context, contextExtras);
            }

            const initialState = {
                context,
            };

            formData.append("variables", JSON.stringify(initialState));

            attachedFiles.forEach((file) => {
                formData.append("files", file);
            });

            const headers = basicAuth ? this.createAuthHeaders(basicAuth) : undefined;

            const sessionResponse = await firstValueFrom(
                this.http.post<EpicstaffSessionResponse>(
                    `${agentUrl}/run-session/`,
                    formData,
                    headers ? { headers } : undefined
                )
            );

            const sessionId = sessionResponse.session_id;

            return await this.subscribeToEpicstaffSseSession(
                agentUrl,
                sessionId,
                onStreamUpdate,
                timeout
            );
        } catch (error) {
            console.error("Error sending Epicstaff request:", error);
            throw new Error(this.extractHttpErrorMessage(error));
        }
    }

    private subscribeToEpicstaffSseSession(
        agentUrl: string,
        sessionId: number,
        onStreamUpdate?: (update: EpicstaffStreamUpdate) => void,
        timeout: number = 120000
    ): Promise<EpMessage> {
        return new Promise((resolve, reject) => {
            let finalStatusData: Record<string, unknown> | null = null;
            let parsedFinalOutput: Record<string, unknown> | null = null;
            let isEndReceived = false;
            let timeoutId: ReturnType<typeof setTimeout> | null = null;
            let eventSource: EventSource | null = null;
            let fallbackTried = false;

            const buildResponseMessage = (
                responseData: Record<string, unknown> | null
            ): EpMessage => {
                if (responseData) {
                    return {
                        id: `msg_${Date.now()}`,
                        response: this.convertEpicstaffResponseToEpResponse(
                            responseData as EpicstaffResponse
                        ),
                        time: getCurrentTimestamp(),
                    };
                }

                return {
                    id: `msg_${Date.now()}`,
                    response: {
                        message: "Response received",
                    },
                    time: getCurrentTimestamp(),
                };
            };

            const resolveWithResponseData = (responseData: Record<string, unknown> | null) => {
                resolve(buildResponseMessage(responseData));
            };

            const scheduleTimeout = () => {
                if (isEndReceived) {
                    return;
                }
                if (timeoutId) {
                    clearTimeout(timeoutId);
                }

                timeoutId = setTimeout(() => {
                    if (!isEndReceived) {
                        if (eventSource) {
                            eventSource.close();
                        }

                        const responseData = parsedFinalOutput ?? finalStatusData;

                        if (responseData) {
                            resolveWithResponseData(responseData);
                        } else {
                            reject(new Error("Timeout waiting for session end"));
                        }
                    }
                }, timeout);
            };

            const attachListeners = (source: EventSource, useFiltered: boolean) => {
                // Обработка сообщений типа "status"
                source.addEventListener("status", (event: MessageEvent) => {
                    try {
                        const data: EpicstaffStatusSseMessage = JSON.parse(event.data);
                        console.log({ status: data });
                        scheduleTimeout();

                        if (data.status === "end") {
                            finalStatusData = data.status_data;
                            isEndReceived = true;
                            if (timeoutId) {
                                clearTimeout(timeoutId);
                                timeoutId = null;
                            }
                            source.close();

                            const rawFinalResult =
                                (data.status_data as { variables?: { final_result?: unknown } })
                                    ?.variables?.final_result ?? null;
                            const parsedFinalResult = this.parseOutputIfString(
                                rawFinalResult as Record<string, unknown> | string | null
                            );
                            if (parsedFinalResult) {
                                console.log({ final_result: parsedFinalResult });
                            }

                            const responseData =
                                parsedFinalResult ?? parsedFinalOutput ?? finalStatusData;
                            resolveWithResponseData(responseData);
                        }
                    } catch (error) {
                        console.warn("Failed to parse SSE status message:", error);
                    }
                });

                // Обработка сообщений типа "messages"
                source.addEventListener("messages", (event: MessageEvent) => {
                    try {
                        const data: EpicstaffMessagesSseMessage = JSON.parse(event.data);
                        console.log({ message: data });
                        scheduleTimeout();

                        // Сохраняем данные из message_data, особенно из сообщений с message_type "finish"
                        if (data.message_data) {
                            const messageData: EpicstaffMessageData = data.message_data;

                            if (isStreamMessageData(messageData)) {
                                onStreamUpdate?.({
                                    messageType: messageData.message_type,
                                    text:
                                        typeof messageData.text === "string"
                                            ? messageData.text
                                            : "",
                                    toolCalls: Array.isArray(messageData.tool_calls)
                                        ? (messageData.tool_calls as Array<Record<string, unknown>>)
                                        : [],
                                    isFinal: !!messageData.is_final,
                                    nodeName: data.name,
                                });
                            }

                            // Если это финальное сообщение (finish), сохраняем его данные
                            if (isFinishMessageData(messageData)) {
                                const output = extractOutputFromFinishMessage(messageData);
                                parsedFinalOutput = this.parseOutputIfString(output);
                            }
                            // graph_end сообщения игнорируем, так как они не содержат полезных данных
                        }
                    } catch (error) {
                        console.warn("Failed to parse SSE messages:", error);
                    }
                });

                source.onerror = (error) => {
                    console.error("SSE error:", error);
                    if (isEndReceived) {
                        source.close();
                        return;
                    }

                    if (useFiltered && !fallbackTried) {
                        // Попробовать fallback на неотфильтрованный endpoint
                        fallbackTried = true;
                        source.close();
                        if (timeoutId) {
                            clearTimeout(timeoutId);
                            timeoutId = null;
                        }
                        openEventSource(false);
                        return;
                    }

                    source.close();
                    if (timeoutId) {
                        clearTimeout(timeoutId);
                        timeoutId = null;
                    }
                    reject(new Error("SSE connection error"));
                };
            };

            const openEventSource = (useFiltered: boolean) => {
                // Note: EventSource doesn't support custom headers natively.
                // If the server requires Basic Auth for SSE, you may need to:
                // 1. Use session cookies from the POST request (most common)
                // 2. Pass auth in URL (less secure): ?auth=base64credentials
                // 3. Use fetch API with streaming instead of EventSource
                const filteredSuffix = useFiltered ? "filtered/" : "";
                const subscribeUrl = `${agentUrl}/run-session/subscribe/${sessionId}/${filteredSuffix}`;

                eventSource = new EventSource(subscribeUrl, { withCredentials: true });
                attachListeners(eventSource, useFiltered);
                scheduleTimeout();
            };

            const cancel = () => {
                if (isEndReceived) {
                    return;
                }
                isEndReceived = true;
                if (eventSource) {
                    eventSource.close();
                }
                if (timeoutId) {
                    clearTimeout(timeoutId);
                    timeoutId = null;
                }
                reject(new Error(STREAM_CANCEL_ERROR));
            };

            this.activeSseCancel = cancel;

            openEventSource(true);
        });
    }

    /**
     * Парсит output если он является строкой JSON
     */
    private parseOutputIfString(
        output: Record<string, unknown> | string | null
    ): Record<string, unknown> | null {
        if (!output) {
            return null;
        }

        // Если output - это строка JSON, парсим её
        if (typeof output === "string") {
            const trimmed = output.trim();
            if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
                try {
                    const parsed = JSON.parse(trimmed);
                    return typeof parsed === "object" && parsed !== null
                        ? (parsed as Record<string, unknown>)
                        : null;
                } catch {
                    // Если не удалось распарсить, возвращаем null
                    return null;
                }
            }
            // Если это не JSON строка, возвращаем null
            return null;
        }

        // Если output - это уже объект, возвращаем как есть
        return output;
    }

    /**
     * Преобразует EpicstaffResponse в EpResponse для использования в UI
     */
    private convertEpicstaffResponseToEpResponse(epicstaffResponse: EpicstaffResponse): EpResponse {
        // Преобразуем ef_tables в _tables с правильным форматом
        const efTables = epicstaffResponse["ef_tables"];
        const convertedTables = this.convertTablesToEpTableFormat(
            Array.isArray(efTables) ? efTables : []
        );

        const { ef_tables: _ignoredEfTables, ...epResponse } = epicstaffResponse as EpResponse;

        if (convertedTables.length > 0) {
            epResponse._tables = convertedTables;
        }

        const actions = epResponse.action_message;
        if (Array.isArray(actions) && actions.length > 0) {
            epResponse.action_message = actions.map((a) =>
                this.actionService.isActionHandled(a) ? a : { ...a, disabled: true }
            );
        }

        return epResponse;
    }

    /**
     * Преобразует таблицы из разных форматов в формат EpTable с columns и rows
     */
    private convertTablesToEpTableFormat(tables: unknown[]): unknown[] {
        if (!Array.isArray(tables) || tables.length === 0) {
            return [];
        }

        return tables.map((table) => {
            // Ожидаем формат ef_tables: объект с rows (массив объектов) и опциональными columns
            const tableObj = table as Record<string, unknown>;

            const hasRows =
                tableObj &&
                "rows" in tableObj &&
                Array.isArray(tableObj["rows"]) &&
                (tableObj["rows"] as unknown[]).length > 0;

            const hasColumns =
                tableObj &&
                "columns" in tableObj &&
                Array.isArray((tableObj as { columns: unknown }).columns);

            // Если таблица уже имеет columns и rows в правильном формате, просто нормализуем метаданные
            if (hasRows && hasColumns) {
                return {
                    ...tableObj,
                    id:
                        ("id" in tableObj && typeof tableObj["id"] === "string"
                            ? tableObj["id"]
                            : null) || this.generateTableId(),
                    isEditable: ("isEditable" in tableObj ? tableObj["isEditable"] : true) ?? true,
                    isSortable: ("isSortable" in tableObj ? tableObj["isSortable"] : true) ?? true,
                    defaultSortField:
                        ("defaultSortField" in tableObj &&
                        typeof tableObj["defaultSortField"] === "string"
                            ? tableObj["defaultSortField"]
                            : null) || null,
                };
            }

            // Если rows нет — это устаревший формат tables, больше не поддерживаем
            if (!hasRows) {
                return tableObj;
            }

            const rows = tableObj["rows"] as Record<string, unknown>[];
            const firstRow = rows[0] || {};
            const columnKeys = Object.keys(firstRow);

            // Генерируем columns из ключей
            const nonEditableColumnKeys = ["id", "Id", "ID", "Index", "index"];
            const columns = columnKeys.map((key) => ({
                key,
                title:
                    key.charAt(0).toUpperCase() +
                    key
                        .slice(1)
                        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
                        .trim(),
                visible: true,
                editable: !nonEditableColumnKeys.includes(key),
                type: this.getColumnType(rows.map((r) => r?.[key])),
            }));

            // Добавляем действия таблицы по умолчанию, если их нет
            const defaultTableActions = ("tableActions" in tableObj &&
            Array.isArray(tableObj["tableActions"])
                ? tableObj["tableActions"]
                : null) || [
                {
                    text: ".csv",
                    action: "downloadEpTableCsv",
                    type: "button",
                },
                {
                    text: ".xlsx",
                    action: "downloadEpTableExcel",
                    type: "button",
                },
            ];

            return {
                ...tableObj,
                columns,
                rows,
                id:
                    ("id" in tableObj && typeof tableObj["id"] === "string"
                        ? tableObj["id"]
                        : null) || this.generateTableId(),
                isEditable: ("isEditable" in tableObj ? tableObj["isEditable"] : true) ?? true,
                isSortable: ("isSortable" in tableObj ? tableObj["isSortable"] : true) ?? true,
                defaultSortField:
                    ("defaultSortField" in tableObj &&
                    typeof tableObj["defaultSortField"] === "string"
                        ? tableObj["defaultSortField"]
                        : null) ||
                    columnKeys[0] ||
                    null,
                tableActions: defaultTableActions,
                rowsSelectionType: tableObj["rowsSelectionType"],
                preselectedRows: tableObj["preselectedRows"],
                selectedRowIndices: tableObj["selectedRowIndices"],
                unions: tableObj["unions"],
            };
        });
    }

    /**
     * Определяет тип колонки на основе данных
     */
    private getColumnType(values: unknown[]): "number" | "text" | "default" | "boolean" | "date" {
        if (values.length === 0) return "default";
        const sampleSize = Math.min(10, values.length);
        const sample = values.slice(0, sampleSize);

        const allBooleans = sample.every((v) => v === true || v === false);
        if (allBooleans) return "boolean";

        const allNumbers = sample.every(
            (v) => v !== null && v !== undefined && !isNaN(Number(v)) && v !== ""
        );
        if (allNumbers) return "number";

        const datePattern = /^\d{4}-\d{2}-\d{2}/;
        const allDates = sample.every(
            (v) =>
                v instanceof Date ||
                (typeof v === "string" && datePattern.test(v)) ||
                (typeof v === "number" && v.toString().length >= 10)
        );
        if (allDates) return "date";

        return "text";
    }

    /**
     * Генерирует уникальный ID для таблицы
     */
    private generateTableId(): string {
        return `table_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    private formatChatHistory(messages: EpMessage[]): Array<{ role: string; content: string }> {
        const contextLength = 10;
        const recentMessages = messages.slice(-contextLength); // Берем последние N сообщений

        return recentMessages
            .map((msg) => {
                if (msg.request) {
                    return {
                        role: "user",
                        content: msg.request,
                    };
                }
                if (msg.response?.message) {
                    return {
                        role: "assistant",
                        content: msg.response.message,
                    };
                }
                return null;
            })
            .filter((item): item is { role: string; content: string } => item !== null);
    }

    async getMessages(): Promise<EpMessage[]> {
        return [];
    }

    // ------------------------ Files & IndexedDB ------------------------ //

    public async saveRecentFilesToIndexedDB(files: File[]): Promise<void> {
        try {
            await this.storageService.saveFilesToIndexedDB(STORAGE_KEYS.RECENT_FILES, files);
        } catch (error) {
            console.error("Error saving files to IndexedDB", error);
        }
    }

    public async getRecentFilesFromIndexedDB(): Promise<File[]> {
        try {
            return await this.storageService.getFilesFromIndexedDB(STORAGE_KEYS.RECENT_FILES);
        } catch (error) {
            console.error("Error fetching files from IndexedDB", error);
            return [];
        }
    }

    private extractHttpErrorMessage(error: unknown): string {
        if (error && typeof error === "object") {
            const err = error as Record<string, unknown>;
            if (err["error"] && typeof err["error"] === "object") {
                const body = err["error"] as Record<string, unknown>;
                if (typeof body["message"] === "string") return body["message"];
                if (typeof body["detail"] === "string") return body["detail"];
            }
            if (typeof err["error"] === "string") return err["error"];
            if (typeof err["message"] === "string") return err["message"];
        }
        return "Something went wrong";
    }
}
