import { CommonModule } from "@angular/common";
import {
    Component,
    EventEmitter,
    HostListener,
    Input,
    OnChanges,
    OnInit,
    Output,
    SimpleChanges,
} from "@angular/core";
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from "@angular/forms";
import { Agent, EpicstaffAgent } from "../../models/epicstaff-agent.model";
import { EpicstaffAgentService } from "../../services/epicstaff-agent.service";
import { ButtonComponent } from "../shared/button/button.component";
import { ModalComponent } from "../shared/modal/modal.component";

export type AgentConfigPopupState = "create" | "edit";

@Component({
    selector: "ep-epicstaff-agent-config",
    imports: [CommonModule, ReactiveFormsModule, ButtonComponent, ModalComponent],
    templateUrl: "./epicstaff-agent-config.component.html",
    styleUrls: ["./epicstaff-agent-config.component.scss"],
})
export class EpicstaffAgentConfigComponent implements OnInit, OnChanges {
    @Input() popupState: AgentConfigPopupState | null = null;
    @Input() currentAgent: Agent | null = null;
    @Input() newAgentParams?: { flowId: number; url: string } | null;
    @Output() closed = new EventEmitter<void>();

    form!: FormGroup;

    constructor(
        private fb: FormBuilder,
        private agentService: EpicstaffAgentService
    ) {}

    ngOnInit(): void {
        this.buildForm();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (this.form && changes["newAgentParams"] && this.popupState === "create") {
            this.patchFormFromNewAgentParams();
        }
    }

    private buildForm(): void {
        let name = "";
        let description = "";
        let flowId = "";
        let flowUrl = "";

        if (this.isEdit) {
            name = this.currentAgent?.name ?? "";
            description = this.currentAgent?.description ?? "";
            flowId =
                this.currentAgent?.epicstaffFlowId != null
                    ? String(this.currentAgent.epicstaffFlowId)
                    : "";
            flowUrl = this.currentAgent?.epicstaffFlowUrl ?? "";
        } else if (this.newAgentParams) {
            flowId = this.newAgentParams.flowId != null ? String(this.newAgentParams.flowId) : "";
            flowUrl = this.newAgentParams.url ?? "";
        }

        this.form = this.fb.group({
            name: [name, [Validators.required, Validators.maxLength(100)]],
            description: [description, [Validators.maxLength(200)]],
            flowId: [flowId, [Validators.required]],
            flowUrl: [flowUrl, [Validators.required]],
        });
    }

    private patchFormFromNewAgentParams(): void {
        const p = this.newAgentParams;
        if (!p || !this.form) return;
        this.form.patchValue({
            flowId: p.flowId != null ? String(p.flowId) : "",
            flowUrl: p.url ?? "",
        });
    }

    get isEdit(): boolean {
        return this.popupState === "edit";
    }

    get isValidForm(): boolean {
        return this.form?.valid ?? false;
    }

    cancel(): void {
        this.closed.emit();
    }

    apply(): void {
        if (!this.isValidForm) return;

        const raw = this.form.getRawValue();
        const payload: EpicstaffAgent = {
            flow_id: raw.flowId ? +raw.flowId : null,
            agent_name: (raw.name || "").trim(),
            agent_description: (raw.description || "").trim(),
            url: (raw.flowUrl || "").trim(),
            config: {},
        };
        if (this.isEdit) {
            payload.id = this.currentAgent?.epicstaffAgentId;
        }

        this.closed.emit();

        if (this.isEdit) {
            this.agentService.updateAgent(payload);
        } else {
            this.agentService.createAgent(payload, { selectAfterCreate: true });
        }
        this.agentService.loadAgents();
    }

    async importFromClipboard(): Promise<void> {
        try {
            const clipboardText = await navigator.clipboard.readText();
            this.parseCurlCommand(clipboardText);
        } catch (error) {
            console.error("Failed to read clipboard:", error);
        }
    }

    private parseCurlCommand(curlText: string): void {
        try {
            const urlMatch = curlText.match(/https?:\/\/[^\s']+/);
            if (!urlMatch) {
                return;
            }
            let fullUrl = urlMatch[0];
            if (fullUrl.endsWith("/run-session/")) {
                fullUrl = fullUrl.replace("/run-session/", "");
            }
            const graphIdMatch = curlText.match(/"graph_id":\s*"(\d+)"/);
            if (!graphIdMatch) {
                return;
            }
            const graphId = graphIdMatch[1];
            this.form.patchValue({ flowUrl: fullUrl, flowId: graphId });
        } catch (error) {
            console.error("Failed to parse curl command:", error);
        }
    }

    @HostListener("window:keydown", ["$event"]) onKeyPress(e: KeyboardEvent): void {
        if (e.key === "Enter") {
            if (this.isValidForm) this.apply();
            e.stopPropagation();
        }
        if (e.key === "Escape") {
            this.cancel();
            e.stopPropagation();
        }
    }
}
