import { CommonModule } from "@angular/common";
import {
    AfterViewInit,
    ChangeDetectorRef,
    Component,
    ElementRef,
    EventEmitter,
    Input,
    Output,
    ViewChild,
} from "@angular/core";
import { ApiService } from "../../../services/api.service";
import { MenuComponent } from "../menu/menu.component";
import { IconComponent } from "../icon/icon.component";

@Component({
    selector: "ep-recent-files-menu",
    templateUrl: "./recent-files-menu.component.html",
    styleUrls: ["./recent-files-menu.component.scss"],
    imports: [CommonModule, MenuComponent, IconComponent],
})
export class RecentFilesMenuComponent implements AfterViewInit {
    @Input() alreadyAttachedFiles: File[] = [];
    @Input() multipleFilesAllowed: boolean = true;
    @Output() fileAttached = new EventEmitter<File>();
    @Output() filesAttached = new EventEmitter<File[]>();
    @Output() hideRecentFilesMenu = new EventEmitter<void>();
    @ViewChild("attachFileMenuItem") attachFileMenuItem?: ElementRef<HTMLLabelElement>;

    recentFiles: File[] = [];
    loaded = false;
    hoveredFile: File | null = null;
    public readonly singleModeAccept: string = [
        "application/pdf",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/msword",
        "text/csv",
        "text/plain",
        "text/html",
        "application/xml",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "application/vnd.oasis.opendocument.text",
    ].join(",");

    constructor(
        private apiService: ApiService,
        private cdr: ChangeDetectorRef
    ) {}

    ngAfterViewInit(): void {
        this.getRecentFiles();
    }

    private async getRecentFiles(): Promise<void> {
        const files = await this.apiService.getRecentFilesFromIndexedDB();

        this.recentFiles = files;
        this.loaded = true;
        this.cdr.detectChanges();

        if (!files.length) {
            this.openFilePicker();
        }
    }

    private openFilePicker(): void {
        const fileInput = this.attachFileMenuItem?.nativeElement?.querySelector(
            'input[type="file"]'
        ) as HTMLInputElement | null;
        if (fileInput) {
            // Listen for cancel: when window regains focus but no file was selected
            const onFocus = () => {
                setTimeout(() => {
                    if (!fileInput.files?.length) {
                        this.hideRecentFilesMenu.emit();
                    }
                    window.removeEventListener("focus", onFocus);
                }, 300);
            };
            window.addEventListener("focus", onFocus);
            fileInput.click();
        } else {
            this.hideRecentFilesMenu.emit();
        }
    }

    public attachRecentFile(file: File): void {
        if (this.multipleFilesAllowed && this.isFileAlreadyAttached(file)) {
            this.hideRecentFilesMenu.emit();
            return;
        }
        this.fileAttached.emit(file);
        this.recentFiles = this.recentFiles.filter((f) => f !== file);
        this.recentFiles.push(file);
        this.apiService.saveRecentFilesToIndexedDB(this.recentFiles);
        this.hideRecentFilesMenu.emit();
    }

    public removeFileFromRecentFiles(event: MouseEvent | KeyboardEvent, file: File): void {
        event.stopPropagation();
        event.preventDefault();
        this.recentFiles = this.recentFiles.filter((f) => f !== file);
        this.apiService.saveRecentFilesToIndexedDB(this.recentFiles);
        if (this.recentFiles.length === 0) {
            this.hideRecentFilesMenu.emit();
        }
    }

    public onRemoveFileKeydown(event: KeyboardEvent, file: File): void {
        if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            this.removeFileFromRecentFiles(event, file);
        }
    }

    public onFileHover(file: File | null): void {
        this.hoveredFile = file;
    }

    public onNewFileSelect(event: Event): void {
        const input = event.target as HTMLInputElement;

        if (input.files?.length) {
            if (this.multipleFilesAllowed) {
                let filesArray = Array.from(input.files);
                filesArray = filesArray.filter((f) => !this.isFileAlreadyAttached(f));
                if (filesArray.length) {
                    this.filesAttached.emit(filesArray);
                }
            } else {
                const file = input.files[0];
                this.fileAttached.emit(file);
            }
        }
        this.hideRecentFilesMenu.emit();
    }

    public isFileAlreadyAttached(file: File): boolean {
        return this.alreadyAttachedFiles.some((f) => f.name === file.name && f.size === file.size);
    }
}
