import {
    AfterViewChecked,
    AfterViewInit,
    ChangeDetectionStrategy,
    Component,
    ElementRef,
    OnDestroy,
    ViewChild,
    effect,
    input,
    output,
    signal,
} from "@angular/core";
import { AutoScrollDirective } from "../../directives/auto-scroll.directive";
import { Action, EpMessage } from "../../models/message.model";
import { getImagePath } from "../../utils/asset.utils";
import { MessageItemComponent } from "../message-item/message-item.component";
import { TypingIndicatorComponent } from "../shared/typing-indicator/typing-indicator.component";

export type ScrollMode = "user-message" | "question-answer" | "bottom" | "none";

@Component({
    selector: "ep-chat-body",
    imports: [MessageItemComponent, TypingIndicatorComponent, AutoScrollDirective],
    templateUrl: "./chat-body.component.html",
    styleUrls: ["./chat-body.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChatBodyComponent implements AfterViewInit, AfterViewChecked, OnDestroy {
    readonly messages = input<EpMessage[]>([]);
    readonly isTyping = input<boolean>(false);
    readonly scrollMode = input<ScrollMode>("none");
    readonly actionClick = output<{ action: Action; message: EpMessage }>();

    public readonly getImagePath = getImagePath;

    @ViewChild("bodyElement") bodyElement?: ElementRef<HTMLElement>;
    @ViewChild("spacer") spacerEl?: ElementRef<HTMLElement>;
    @ViewChild(AutoScrollDirective) autoScrollDirective?: AutoScrollDirective;

    shouldAutoScroll = signal(true);
    upperDate = signal("");
    isUpperDateVisible = signal(false);
    private upperDateVisibilityTimeout: ReturnType<typeof setTimeout> | undefined;
    private scrollHandler?: () => void;
    private lastMessageCount: number = 0;
    private lastScrollTop: number = 0;
    private pendingStreamScroll = false;
    private pendingScrollMode: ScrollMode | null = null;

    constructor() {
        // Replaces ngOnChanges for messages/isTyping
        effect(() => {
            const msgs = this.messages();
            const _typing = this.isTyping();
            const mode = this.scrollMode();

            const currentMessageCount = msgs.length;
            const messageAdded = currentMessageCount > this.lastMessageCount;
            this.lastMessageCount = currentMessageCount;

            if (messageAdded && mode !== "none") {
                this.pendingScrollMode = mode;
            } else if (mode === "bottom") {
                this.pendingStreamScroll = true;
            }
        });

        // Replaces ngOnChanges for scrollMode
        effect(() => {
            const mode = this.scrollMode();
            if (mode !== "none") {
                setTimeout(() => {
                    this.performScroll();
                }, 100);
            }
        });
    }

    ngAfterViewInit(): void {
        setTimeout(() => {
            const scrollElement = this.getScrollElement();
            if (scrollElement) {
                this.scrollHandler = this.onScroll.bind(this);
                scrollElement.addEventListener("scroll", this.scrollHandler);
                this.lastScrollTop = scrollElement.scrollTop;
            }
        }, 0);
    }

    ngOnDestroy(): void {
        const scrollElement = this.getScrollElement();
        if (scrollElement && this.scrollHandler) {
            scrollElement.removeEventListener("scroll", this.scrollHandler);
        }
        if (this.upperDateVisibilityTimeout) {
            clearTimeout(this.upperDateVisibilityTimeout);
        }
    }

    private getScrollElement(): HTMLElement | null {
        return this.bodyElement?.nativeElement || null;
    }

    private getDomRoot(): Document | ShadowRoot | null {
        const scrollElement = this.getScrollElement();
        if (!scrollElement) return null;
        const root = scrollElement.getRootNode();
        if (root instanceof ShadowRoot || root instanceof Document) {
            return root;
        }
        return document;
    }

    private getElementByIdInRoot(id: string): HTMLElement | null {
        const root = this.getDomRoot();
        if (!root) return null;
        return root.getElementById(id) as HTMLElement | null;
    }

    private queryElementsInRoot(selector: string): HTMLElement[] {
        const root = this.getDomRoot();
        if (!root) return [];
        return Array.from(root.querySelectorAll(selector) as NodeListOf<HTMLElement>);
    }

    private getLastUserMessage(): EpMessage | undefined {
        const msgs = this.messages();
        for (let i = msgs.length - 1; i >= 0; i--) {
            if (msgs[i]?.request) {
                return msgs[i];
            }
        }
        return undefined;
    }

    private getTargetMessageForMode(mode: ScrollMode): EpMessage | undefined {
        const msgs = this.messages();
        if (!msgs.length) return undefined;
        if (mode === "question-answer" || mode === "user-message") {
            return this.getLastUserMessage() ?? msgs[msgs.length - 1];
        }
        return msgs[msgs.length - 1];
    }

    private onScroll(): void {
        const element = this.getScrollElement();
        if (!element) return;

        const scrollTop = element.scrollTop;
        const scrollHeight = element.scrollHeight;
        const clientHeight = element.clientHeight;

        const isScrollingUp = scrollTop < this.lastScrollTop;
        this.lastScrollTop = scrollTop;

        if (scrollTop + clientHeight >= scrollHeight - 10) {
            this.onScrollDown();
        } else if (isScrollingUp && scrollTop > 10) {
            this.onScrollUp();
        } else {
            this.onScrollDown();
        }
    }

    private onScrollUp(): void {
        clearTimeout(this.upperDateVisibilityTimeout);

        setTimeout(() => {
            const scrollElement = this.getScrollElement();
            if (!scrollElement) return;

            const dialogWindowLocation = scrollElement.getBoundingClientRect();
            const datesInDialog = this.queryElementsInRoot("#firstMessageOfDay");
            const datesUpperThenDialog = datesInDialog
                .filter((dateLabel) => {
                    return dateLabel.getBoundingClientRect().top < dialogWindowLocation.top;
                })
                .map((date) => date.innerText);
            const lastDateUpperThenDialog = datesUpperThenDialog[datesUpperThenDialog.length - 1];

            if (lastDateUpperThenDialog) {
                this.upperDate.set(lastDateUpperThenDialog);
                this.isUpperDateVisible.set(true);

                this.upperDateVisibilityTimeout = setTimeout(() => {
                    this.isUpperDateVisible.set(false);
                }, 2000);
            } else {
                this.isUpperDateVisible.set(false);
                this.upperDate.set("");
            }
        }, 0);
    }

    private onScrollDown(): void {
        clearTimeout(this.upperDateVisibilityTimeout);
        this.isUpperDateVisible.set(false);
    }

    ngAfterViewChecked(): void {
        if (this.pendingScrollMode) {
            const mode = this.pendingScrollMode;
            const targetMessage = this.getTargetMessageForMode(mode);
            const messageId = targetMessage
                ? `message_${targetMessage.id || targetMessage.time}`
                : "";
            const targetEl = messageId ? this.getElementByIdInRoot(messageId) : null;
            if (targetEl) {
                this.pendingScrollMode = null;
                this.performScroll(mode);
            }
        }

        if (this.pendingStreamScroll) {
            this.pendingStreamScroll = false;
            const element = this.getScrollElement();
            if (!element) return;
            const distFromBottom = element.scrollHeight - element.scrollTop - element.clientHeight;
            if (distFromBottom < 100) {
                this.scrollToLastMessageTop("bottom");
            }
        }
    }

    scrollToBottom(): void {
        const element = this.getScrollElement();
        if (element) {
            element.scrollTop = element.scrollHeight;
        }
    }

    scrollToLastUserMessage(): void {
        this.scrollToLastMessageTop("question-answer");
    }

    private scrollToLastMessageTop(retryMode: ScrollMode = "question-answer"): void {
        const msgs = this.messages();
        if (!msgs.length) return;
        const element = this.getScrollElement();
        if (!element) return;
        const targetMessage = this.getTargetMessageForMode(retryMode);
        if (!targetMessage) return;
        const messageId = `message_${targetMessage.id || targetMessage.time}`;
        const lastMessageEl = this.getElementByIdInRoot(messageId);
        if (!lastMessageEl) {
            this.pendingScrollMode = retryMode;
            return;
        }
        requestAnimationFrame(() => {
            const margin = 20;
            const containerRect = element.getBoundingClientRect();
            const msgRect = lastMessageEl.getBoundingClientRect();
            const dialogWindowHeight = containerRect.height;
            const lastMessageHeight = msgRect.height;
            const relativeTop = msgRect.top - containerRect.top + element.scrollTop;
            const spacerHeight = dialogWindowHeight - lastMessageHeight - margin;
            if (this.spacerEl?.nativeElement) {
                this.spacerEl.nativeElement.style.height = `${Math.max(spacerHeight, 0)}px`;
            }
            element.scrollTop = Math.max(0, relativeTop - margin);
        });
    }

    private performScroll(modeOverride?: ScrollMode): void {
        const msgs = this.messages();
        if (!this.bodyElement?.nativeElement || !msgs.length) {
            return;
        }
        const mode = modeOverride ?? this.scrollMode();
        const dialogWindowHeight = this.bodyElement.nativeElement.getBoundingClientRect().height;

        switch (mode) {
            case "user-message":
                this.scrollToUserMessage(dialogWindowHeight);
                break;
            case "question-answer":
                this.scrollToQuestionAnswer(dialogWindowHeight);
                break;
            case "bottom":
                if (this.spacerEl?.nativeElement) {
                    this.spacerEl.nativeElement.style.height = "0px";
                }
                this.scrollToLastMessageTop("bottom");
                break;
            case "none":
                if (this.spacerEl?.nativeElement) {
                    this.spacerEl.nativeElement.style.height = "0px";
                }
                break;
        }
    }

    private scrollToUserMessage(dialogWindowHeight: number): void {
        const msgs = this.messages();
        if (!msgs.length) {
            return;
        }

        const element = this.getScrollElement();
        if (!element) return;
        const lastMessage = this.getLastUserMessage();

        if (!lastMessage || !lastMessage.request) {
            return;
        }

        const messageId = `message_${lastMessage.id || lastMessage.time}`;
        const lastMessageEl = this.getElementByIdInRoot(messageId);

        if (!lastMessageEl || !this.spacerEl) {
            this.scrollToBottom();
            return;
        }

        requestAnimationFrame(() => {
            const lastMessageHeight = lastMessageEl.getBoundingClientRect().height;
            const messageMargin = 20;

            const spacerHeight = dialogWindowHeight - lastMessageHeight - messageMargin;
            if (this.spacerEl?.nativeElement) {
                this.spacerEl.nativeElement.style.height = `${Math.max(spacerHeight, 0)}px`;
            }

            const relativeTop = lastMessageEl.offsetTop - element.offsetTop;
            const targetScrollPosition = relativeTop - messageMargin;

            element.scrollTop = Math.max(0, targetScrollPosition);
        });
    }

    private scrollToQuestionAnswer(_dialogWindowHeight: number): void {
        if (this.spacerEl?.nativeElement) {
            this.spacerEl.nativeElement.style.height = "0px";
        }
        this.scrollToLastMessageTop("question-answer");
    }

    scrollToMessage(messageId: string | number): void {
        const element = this.getScrollElement();
        if (!element) return;
        const messageEl = this.getElementByIdInRoot(`message_${messageId}`);

        if (!messageEl) {
            return;
        }

        requestAnimationFrame(() => {
            const messageMargin = 20;
            const relativeTop = messageEl.offsetTop - element.offsetTop;
            const targetScrollPosition = relativeTop - messageMargin;
            element.scrollTop = Math.max(0, targetScrollPosition);
        });
    }

    onActionClick(event: { action: Action; message: EpMessage }): void {
        this.actionClick.emit(event);
    }
}
