import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    Component,
    ElementRef,
    EventEmitter,
    HostListener,
    Input,
    Output,
} from "@angular/core";
import { FormsModule } from "@angular/forms";
import { DropdownOption } from "src/app/models/table.model";

@Component({
    selector: "ep-dropdown",
    standalone: true,
    imports: [CommonModule, FormsModule],
    templateUrl: "./dropdown.component.html",
    styleUrls: ["./dropdown.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DropdownComponent {
    @Input() options: DropdownOption[] = [];
    @Input() selected: DropdownOption | DropdownOption[] | null = null;
    @Input() multiple = false;
    @Input() placeholder = "";
    @Input() disabled = false;
    @Input() showSearch = true;
    @Input() maxDropdownHeight = "240px";

    @Output() selectedChange = new EventEmitter<DropdownOption | DropdownOption[] | null>();

    isOpen = false;
    filterText = "";
    panelStyles: Record<string, string> = {};

    constructor(private host: ElementRef<HTMLElement>) {}

    get displayLabel(): string {
        if (!this.selected) {
            return "";
        }
        if (Array.isArray(this.selected)) {
            if (this.selected.length === 0) return "";
            if (this.selected.length === 1) {
                return this.selected[0].Name ?? this.selected[0].Id;
            }
            const labels = this.selected.map((o) => o.Name ?? o.Id);
            const first = labels[0];
            const rest = labels.length - 1;
            return rest > 0 ? `${first}, +${rest}` : first;
        }
        return this.selected.Name ?? this.selected.Id;
    }

    get filteredOptions(): DropdownOption[] {
        const text = this.filterText.trim().toLowerCase();
        if (!text) {
            return this.options;
        }
        return this.options.filter((o) => (o.Name ?? o.Id).toLowerCase().includes(text));
    }

    toggleOpen(): void {
        if (this.disabled) return;
        this.isOpen = !this.isOpen;
        if (this.isOpen) {
            this.filterText = "";
            this.updatePanelPosition();
        }
    }

    close(): void {
        if (!this.isOpen) return;
        this.isOpen = false;
        this.filterText = "";
        this.panelStyles = {};
    }

    onOptionClick(option: DropdownOption, event: MouseEvent): void {
        event.stopPropagation();
        if (this.disabled) return;

        if (!this.multiple) {
            this.selectedChange.emit(option);
            this.close();
            return;
        }

        const current = Array.isArray(this.selected) ? [...this.selected] : [];
        const index = current.findIndex((o) => o.Id === option.Id);
        if (index === -1) {
            current.push(option);
        } else {
            current.splice(index, 1);
        }
        this.selectedChange.emit(current);
    }

    isSelected(option: DropdownOption): boolean {
        if (!this.selected) return false;
        if (Array.isArray(this.selected)) {
            return this.selected.some((o) => o.Id === option.Id);
        }
        return this.selected.Id === option.Id;
    }

    onClearClick(event: MouseEvent): void {
        event.stopPropagation();
        if (this.disabled) return;
        this.selectedChange.emit(null);
        this.close();
    }

    onToggleAll(event: MouseEvent): void {
        event.stopPropagation();
        if (this.disabled || !this.multiple) return;

        const filtered = this.filteredOptions;
        const current = Array.isArray(this.selected) ? this.selected : [];
        const allSelected =
            filtered.length > 0 && filtered.every((o) => current.some((c) => c.Id === o.Id));

        if (allSelected) {
            const remaining = current.filter((c) => !filtered.some((f) => f.Id === c.Id));
            this.selectedChange.emit(remaining);
        } else {
            const map = new Map(current.map((c) => [c.Id, c]));
            filtered.forEach((o) => {
                if (!map.has(o.Id)) {
                    map.set(o.Id, o);
                }
            });
            this.selectedChange.emit(Array.from(map.values()));
        }
    }

    get toggleAllLabel(): string {
        if (!this.multiple) return "";
        const filtered = this.filteredOptions;
        if (!Array.isArray(this.selected) || this.selected.length === 0) {
            return "Select all";
        }
        const current = this.selected;
        const allSelected =
            filtered.length > 0 && filtered.every((o) => current.some((c) => c.Id === o.Id));
        return allSelected ? "Deselect all" : "Select all";
    }

    @HostListener("document:click", ["$event"])
    onDocumentClick(event: MouseEvent): void {
        if (!this.isOpen) return;
        const path = event.composedPath?.() ?? [];
        const target = event.target as Node | null;
        const isInside =
            path.includes(this.host.nativeElement) ||
            (!!target && this.host.nativeElement.contains(target));
        if (!isInside) {
            this.close();
        }
    }

    private updatePanelPosition(): void {
        const hostEl = this.host.nativeElement;
        const control = hostEl.querySelector(".ep-dropdown__control") as HTMLElement | null;
        if (!control) return;

        const rect = control.getBoundingClientRect();

        this.panelStyles = {
            top: `${rect.bottom}px`,
            left: `${rect.left}px`,
            "min-width": `${rect.width}px`,
        };
    }
}
