import {
    AfterViewInit,
    Directive,
    ElementRef,
    HostListener,
    Input,
    OnChanges,
    OnDestroy,
    OnInit,
    Renderer2,
    SimpleChanges,
} from "@angular/core";
import { CHAT_CONSTANTS } from "../constants/chat.constants";
import { STORAGE_KEYS } from "../constants/storage.constants";
import { ChatConfig } from "../models/chat-config.model";
import { StorageService } from "../services/storage.service";

interface ChatSize {
    width: number;
    height: number;
    top: number;
    left: number;
    isFullHeight: boolean;
}

@Directive({
    selector: "[epResizableChat]",
})
export class ResizableChatDirective implements OnInit, AfterViewInit, OnChanges, OnDestroy {
    @Input() config?: ChatConfig;
    @Input() resizeDisabled: boolean = false;

    private readonly RESIZE_THRESHOLD = 10;
    private readonly MIN_WIDTH = CHAT_CONSTANTS.MIN_WIDTH;
    private readonly MIN_HEIGHT = CHAT_CONSTANTS.MIN_HEIGHT;

    private element!: HTMLElement;
    private isResizing = false;
    private isDragging = false;
    private resizeDirection: string = "";
    private dragStartX = 0;
    private dragStartY = 0;
    private originalLeft = 0;
    private originalTop = 0;
    private originalWidth = 0;
    private originalHeight = 0;
    private defaultSize: ChatSize | null = null;
    private isFullHeight = false;
    private lastFullHeightNoop = false;
    private resizeTimeout: ReturnType<typeof setTimeout> | null = null;
    private readonly resizeHandler = () => this.handleWindowResize();

    constructor(
        private elementRef: ElementRef,
        private renderer: Renderer2,
        private storageService: StorageService
    ) {
        window.addEventListener("resize", this.resizeHandler);
    }

    ngOnInit(): void {
        this.element = this.elementRef.nativeElement;
    }

    ngOnDestroy(): void {
        window.removeEventListener("resize", this.resizeHandler);
        if (this.resizeTimeout) {
            clearTimeout(this.resizeTimeout);
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes["resizeDisabled"] && !changes["resizeDisabled"].firstChange) {
            if (!this.resizeDisabled) {
                requestAnimationFrame(() => {
                    const loaded = this.loadSizeFromLS();
                    if (!loaded) {
                        this.applyInitialSizeFromConfig();
                        this.setDefaultSize();
                    }
                });
            }
        }
    }

    ngAfterViewInit(): void {
        if (this.resizeDisabled) return;

        requestAnimationFrame(() => {
            if (this.resizeDisabled) return;

            const savedSize = this.loadSizeFromLS();
            if (savedSize) {
                this.setDefaultSize();
                return;
            }

            const rect = this.element.getBoundingClientRect();
            const computedStyle = window.getComputedStyle(this.element);

            const hasSizeFromNgStyle =
                (computedStyle.width !== "auto" &&
                    computedStyle.width !== "0px" &&
                    parseFloat(computedStyle.width) > 0) ||
                (computedStyle.height !== "auto" &&
                    computedStyle.height !== "0px" &&
                    parseFloat(computedStyle.height) > 0);

            const hasPositionFromNgStyle =
                computedStyle.left !== "auto" ||
                computedStyle.top !== "auto" ||
                computedStyle.right !== "auto" ||
                computedStyle.bottom !== "auto" ||
                computedStyle.transform !== "none";

            if (
                hasSizeFromNgStyle ||
                hasPositionFromNgStyle ||
                (rect.width > 0 && rect.height > 0)
            ) {
                this.setDefaultSize();
            } else {
                this.applyInitialSizeFromConfig();
                this.setDefaultSize();
            }
        });
    }

    @HostListener("mousedown", ["$event"])
    onMouseDown(event: MouseEvent): void {
        if (this.resizeDisabled) return;

        const target = event.target as HTMLElement;
        const direction = this.getResizeDirection(event);

        if (direction) {
            this.startResizing(event, direction);
            return;
        }

        if (
            target.closest(".chat-header") &&
            !target.closest("button") &&
            !target.closest(".chat-header__title--clickable") &&
            !target.closest(".chat-header__agent-menu") &&
            !target.closest(".chat-header__actions-menu")
        ) {
            this.startDragging(event);
        }
    }

    @HostListener("document:mousemove", ["$event"])
    onMouseMove(event: MouseEvent): void {
        if (this.resizeDisabled) return;
        if (this.isDragging) {
            this.handleDragging(event);
        } else if (this.isResizing) {
            this.handleResizing(event);
            document.body.style.cursor = this.getCursorForDirection(this.resizeDirection);
        } else {
            this.updateCursor(event);
        }
    }

    @HostListener("document:mouseup", ["$event"])
    onMouseUp(_event: MouseEvent): void {
        if (this.isResizing) {
            this.stopResizing();
        }
        if (this.isDragging) {
            this.stopDragging();
        }
    }

    private startDragging(event: MouseEvent): void {
        this.isDragging = true;
        this.dragStartX = event.clientX;
        this.dragStartY = event.clientY;

        const rect = this.element.getBoundingClientRect();
        this.originalLeft = rect.left;
        this.originalTop = rect.top;

        this.renderer.setStyle(this.element, "cursor", "move");
        this.renderer.setStyle(this.element, "user-select", "none");
        event.preventDefault();
    }

    private handleDragging(event: MouseEvent): void {
        const deltaX = event.clientX - this.dragStartX;
        const deltaY = event.clientY - this.dragStartY;

        let newLeft = this.originalLeft + deltaX;
        let newTop = this.isFullHeight ? this.originalTop : this.originalTop + deltaY;

        const windowWidth = window.innerWidth;
        const windowHeight = window.innerHeight;
        const elementWidth = this.element.offsetWidth;
        const elementHeight = this.element.offsetHeight;

        newLeft = Math.max(0, Math.min(newLeft, windowWidth - elementWidth));
        newTop = Math.max(0, Math.min(newTop, windowHeight - elementHeight));

        this.setPosition(newLeft, newTop);
        event.stopPropagation();
    }

    private stopDragging(): void {
        this.isDragging = false;
        this.renderer.setStyle(this.element, "cursor", "default");
        this.renderer.removeStyle(this.element, "user-select");
        this.adjustElementPosition();
        this.saveSizeToLS();
    }

    private startResizing(event: MouseEvent, direction: string): void {
        this.isResizing = true;
        this.resizeDirection = direction;

        const rect = this.element.getBoundingClientRect();
        this.originalWidth = rect.width;
        this.originalHeight = rect.height;
        this.originalLeft = rect.left;
        this.originalTop = rect.top;

        this.setResizeCursor(direction);
        document.body.style.cursor = this.getCursorForDirection(direction);
        document.body.style.userSelect = "none";

        event.preventDefault();
        event.stopPropagation();
    }

    private handleResizing(event: MouseEvent): void {
        const windowWidth = window.innerWidth;
        const windowHeight = window.innerHeight;

        let newWidth = this.originalWidth;
        let newHeight = this.originalHeight;
        let newLeft = this.originalLeft;
        let newTop = this.originalTop;

        const isResizingLeft = this.resizeDirection.includes("left");
        const isResizingRight = this.resizeDirection.includes("right");
        const isResizingTop = this.resizeDirection.includes("top");
        const isResizingBottom = this.resizeDirection.includes("bottom");

        if (isResizingRight) {
            const deltaX = event.clientX - (this.originalLeft + this.originalWidth);
            newWidth = Math.max(
                this.MIN_WIDTH,
                Math.min(this.originalWidth + deltaX, windowWidth - this.originalLeft)
            );
        }

        if (isResizingLeft) {
            const deltaX = this.originalLeft - event.clientX;
            newWidth = Math.max(
                this.MIN_WIDTH,
                Math.min(this.originalWidth + deltaX, this.originalLeft + this.originalWidth)
            );
            newLeft = Math.max(0, this.originalLeft - deltaX);
        }

        if (isResizingBottom) {
            const deltaY = event.clientY - (this.originalTop + this.originalHeight);
            newHeight = Math.max(
                this.MIN_HEIGHT,
                Math.min(this.originalHeight + deltaY, windowHeight - this.originalTop)
            );
        }

        if (isResizingTop) {
            const deltaY = this.originalTop - event.clientY;
            newHeight = Math.max(
                this.MIN_HEIGHT,
                Math.min(this.originalHeight + deltaY, this.originalTop + this.originalHeight)
            );
            newTop = Math.max(0, this.originalTop - deltaY);

            if (newTop <= 0) {
                if (!this.isFullHeight && !this.defaultSize) {
                    this.setDefaultSize();
                }
                newTop = 0;
                newHeight = windowHeight;
                this.isFullHeight = true;
                this.renderer.setStyle(this.element, "maxHeight", "none");
            } else {
                this.isFullHeight = false;
                this.renderer.removeStyle(this.element, "maxHeight");
            }
        }

        this.setSizeAndPosition(newWidth, newHeight, newLeft, newTop);
        event.stopPropagation();
    }

    private stopResizing(): void {
        this.isResizing = false;
        this.resizeDirection = "";

        document.body.style.cursor = "";
        document.body.style.userSelect = "";
        this.renderer.setStyle(this.element, "cursor", "default");

        if (!this.isFullHeight) {
            this.adjustElementPosition();
        }

        this.saveSizeToLS();
    }

    private getResizeDirection(event: MouseEvent): string {
        const rect = this.element.getBoundingClientRect();
        const mouseX = event.clientX;
        const mouseY = event.clientY;

        const isNearTop = mouseY - rect.top <= this.RESIZE_THRESHOLD;
        const isNearBottom = rect.bottom - mouseY <= this.RESIZE_THRESHOLD;
        const isNearLeft = mouseX - rect.left <= this.RESIZE_THRESHOLD;
        const isNearRight = rect.right - mouseX <= 2; // because of scroll bar conflict

        const vertical: string[] = [];
        const horizontal: string[] = [];

        if (isNearTop) vertical.push("top");
        if (isNearBottom) vertical.push("bottom");
        if (isNearLeft) horizontal.push("left");
        if (isNearRight) horizontal.push("right");

        return [...vertical, ...horizontal].join("");
    }

    private normalizeCornerDirection(direction: string): string {
        if (direction.includes("top") && direction.includes("left")) return "topLeft";
        if (direction.includes("top") && direction.includes("right")) return "topRight";
        if (direction.includes("bottom") && direction.includes("left")) return "bottomLeft";
        if (direction.includes("bottom") && direction.includes("right")) return "bottomRight";
        return direction;
    }

    private getCursorForDirection(direction: string): string {
        if (!direction) return "default";

        const hasTop = direction.includes("top");
        const hasBottom = direction.includes("bottom");
        const hasLeft = direction.includes("left");
        const hasRight = direction.includes("right");
        const isCorner = (hasTop || hasBottom) && (hasLeft || hasRight);

        if (isCorner) {
            const normalizedDirection = this.normalizeCornerDirection(direction);
            const cornerCursors: Record<string, string> = {
                topLeft: "nwse-resize",
                topRight: "nesw-resize",
                bottomLeft: "nesw-resize",
                bottomRight: "nwse-resize",
            };
            return cornerCursors[normalizedDirection] || "default";
        } else if (hasTop || hasBottom) {
            return "ns-resize";
        } else if (hasLeft || hasRight) {
            return "ew-resize";
        }

        return "default";
    }

    private setResizeCursor(direction: string): void {
        const cursor = this.getCursorForDirection(direction);
        this.renderer.setStyle(this.element, "cursor", cursor);
    }

    private updateCursor(event: MouseEvent): void {
        const target = event.target as HTMLElement;
        if (
            target.closest("button") ||
            target.closest(".chat-header__title--clickable") ||
            target.closest(".chat-header__agent-menu") ||
            target.closest(".chat-header__actions-menu")
        ) {
            this.renderer.setStyle(this.element, "cursor", "default");
            return;
        }

        const direction = this.getResizeDirection(event);

        if (!direction) {
            if (target.closest(".chat-header")) {
                this.renderer.setStyle(this.element, "cursor", "move");
            } else {
                this.renderer.setStyle(this.element, "cursor", "default");
            }
            return;
        }

        const hasTop = direction.includes("top");
        const hasBottom = direction.includes("bottom");
        const hasLeft = direction.includes("left");
        const hasRight = direction.includes("right");
        const isCorner = (hasTop || hasBottom) && (hasLeft || hasRight);

        let cursor = "default";

        if (isCorner) {
            const normalizedDirection = this.normalizeCornerDirection(direction);
            const cornerCursors: Record<string, string> = {
                topLeft: "nwse-resize",
                topRight: "nesw-resize",
                bottomLeft: "nesw-resize",
                bottomRight: "nwse-resize",
            };
            cursor = cornerCursors[normalizedDirection] || "default";
        } else if (hasTop || hasBottom) {
            cursor = "ns-resize";
        } else if (hasLeft || hasRight) {
            cursor = "ew-resize";
        } else if (target.closest(".chat-header")) {
            cursor = "move";
        }

        this.renderer.setStyle(this.element, "cursor", cursor);
    }

    public toggleFullHeight(): void {
        if (this.isFullHeight) {
            this.restoreDefaultHeight();
        } else {
            this.setFullHeight();
        }
    }

    private setFullHeight(): void {
        if (!this.isFullHeight && !this.defaultSize) {
            this.setDefaultSize();
        }

        const rect = this.element.getBoundingClientRect();
        const windowHeight = window.innerHeight;
        const isAlreadyFullHeight =
            Math.abs(rect.height - windowHeight) <= 1 && Math.abs(rect.top) <= 1;
        this.lastFullHeightNoop = isAlreadyFullHeight;

        this.setSizeAndPosition(
            this.element.offsetWidth,
            windowHeight,
            this.element.getBoundingClientRect().left,
            0
        );
        this.renderer.setStyle(this.element, "maxHeight", "none");
        this.isFullHeight = true;
        this.saveSizeToLS();
    }

    private restoreDefaultHeight(): void {
        const rect = this.element.getBoundingClientRect();
        const fallback = this.getDefaultHeightTop();
        const targetHeight = this.defaultSize?.height ?? fallback.height;
        const targetTop = this.defaultSize?.top ?? fallback.top;
        const isNoopRestore =
            Math.abs(rect.height - targetHeight) <= 1 && Math.abs(rect.top - targetTop) <= 1;

        const finalHeight =
            this.lastFullHeightNoop || isNoopRestore ? fallback.height : targetHeight;
        const finalTop = this.lastFullHeightNoop || isNoopRestore ? fallback.top : targetTop;
        this.lastFullHeightNoop = false;

        this.setSizeAndPosition(rect.width, finalHeight, rect.left, finalTop);
        this.renderer.removeStyle(this.element, "maxHeight");
        this.isFullHeight = false;
        this.saveSizeToLS();
    }

    private setDefaultSize(): void {
        const rect = this.element.getBoundingClientRect();
        this.defaultSize = {
            width: rect.width,
            height: rect.height,
            top: rect.top,
            left: rect.left,
            isFullHeight: false,
        };
    }

    public resetToDefault(): void {
        if (!this.config) {
            return;
        }
        this.storageService.removeItem(STORAGE_KEYS.CHAT_SIZE);
        this.isFullHeight = false;
        this.renderer.removeStyle(this.element, "maxHeight");
        this.applyInitialSizeFromConfig();
        this.setDefaultSize();
        this.saveSizeToLS();
    }

    private setSizeAndPosition(width: number, height: number, left: number, top: number): void {
        this.renderer.setStyle(this.element, "width", `${width}px`);
        this.renderer.setStyle(this.element, "height", `${height}px`);
        this.renderer.setStyle(this.element, "left", `${left}px`);
        this.renderer.setStyle(this.element, "top", `${top}px`);
        this.renderer.removeStyle(this.element, "right");
        this.renderer.removeStyle(this.element, "bottom");
        this.renderer.removeStyle(this.element, "transform");
    }

    private setPosition(left: number, top: number): void {
        this.renderer.setStyle(this.element, "left", `${left}px`);
        this.renderer.setStyle(this.element, "top", `${top}px`);
        this.renderer.removeStyle(this.element, "right");
        this.renderer.removeStyle(this.element, "bottom");
        this.renderer.removeStyle(this.element, "transform");
    }

    private adjustElementPosition(): void {
        if (this.element.offsetParent == null) {
            return;
        }

        const windowHeight = window.innerHeight;
        const windowWidth = window.innerWidth;
        const rect = this.element.getBoundingClientRect();

        let width = Math.max(this.MIN_WIDTH, rect.width);
        let height = Math.max(this.MIN_HEIGHT, rect.height);
        let top = rect.top;
        let left = rect.left;

        if (left + width > windowWidth) {
            width = Math.max(this.MIN_WIDTH, windowWidth - left);
            if (width < this.MIN_WIDTH) {
                width = this.MIN_WIDTH;
                left = windowWidth - width;
            }
        }

        if (left < 0) {
            left = 0;
        }

        if (top < 0) {
            height = height + top;
            top = 0;
        }

        if (top + height > windowHeight) {
            height = windowHeight - top;
        }

        if (height < this.MIN_HEIGHT) {
            height = this.MIN_HEIGHT;
            top = windowHeight - height;
        }

        this.setSizeAndPosition(width, height, left, top);
    }

    private handleWindowResize(): void {
        if (this.resizeTimeout) {
            clearTimeout(this.resizeTimeout);
        }

        this.resizeTimeout = setTimeout(() => {
            if (this.isFullHeight) {
                const windowHeight = window.innerHeight;
                this.setSizeAndPosition(
                    this.element.offsetWidth,
                    windowHeight,
                    this.element.getBoundingClientRect().left,
                    0
                );
                this.renderer.setStyle(this.element, "maxHeight", "none");
            } else {
                this.adjustElementPosition();
            }
        }, 100);
    }

    private saveSizeToLS(): void {
        const rect = this.element.getBoundingClientRect();
        const size: ChatSize = {
            width: rect.width,
            height: rect.height,
            top: rect.top,
            left: rect.left,
            isFullHeight: this.isFullHeight,
        };

        this.storageService.setItemAsJSON(STORAGE_KEYS.CHAT_SIZE, size);
    }

    private loadSizeFromLS(): boolean {
        const size = this.storageService.getItemAsJSON<ChatSize>(STORAGE_KEYS.CHAT_SIZE);
        if (!size) {
            return false;
        }

        try {
            if (size.width && size.height) {
                this.isFullHeight = size.isFullHeight || false;

                if (this.isFullHeight) {
                    const fallback = this.getDefaultHeightTop();
                    this.defaultSize = {
                        width: size.width,
                        height: fallback.height,
                        top: fallback.top,
                        left: size.left,
                        isFullHeight: false,
                    };
                    const windowHeight = window.innerHeight;
                    this.setSizeAndPosition(size.width, windowHeight, size.left, 0);
                    this.renderer.setStyle(this.element, "maxHeight", "none");
                } else {
                    this.setSizeAndPosition(size.width, size.height, size.left, size.top);
                }
                return true;
            }
        } catch (e) {
            console.error("Failed to load chat size from storage", e);
        }

        return false;
    }

    private applyInitialSizeFromConfig(): void {
        if (!this.config) {
            return;
        }
        const { width, height, left, top, transform } = this.getDefaultSizeFromConfig();

        if (transform) {
            this.renderer.setStyle(this.element, "transform", transform);
            if (transform.includes("translate")) {
                const rect = this.element.getBoundingClientRect();
                this.setSizeAndPosition(width, height, rect.left, rect.top);
                return;
            }
        }

        this.setSizeAndPosition(width, height, left, top);
    }

    private getDefaultHeightTop(): { height: number; top: number } {
        const { height, top } = this.getDefaultSizeFromConfig();
        return { height, top };
    }

    private getDefaultSizeFromConfig(): {
        width: number;
        height: number;
        left: number;
        top: number;
        transform: string | undefined;
    } {
        const chatStyle = this.getChatStyle(this.config?.chatPosition);
        const width = this.parseSize(
            chatStyle["width"] || this.config?.chatWidth || CHAT_CONSTANTS.DEFAULT_WIDTH
        );
        const height = this.parseSize(
            chatStyle["height"] || this.config?.chatHeight || CHAT_CONSTANTS.DEFAULT_HEIGHT
        );

        let left = 0;
        let top = 0;

        if (chatStyle["left"]) {
            left = this.parseSize(chatStyle["left"]);
        } else if (chatStyle["right"]) {
            left = window.innerWidth - width - this.parseSize(chatStyle["right"]);
        } else if (this.config?.chatLeft) {
            left = this.parseSize(this.config.chatLeft);
        } else {
            left = this.parseSize(CHAT_CONSTANTS.DEFAULT_POSITION.left);
        }

        if (chatStyle["top"]) {
            top = this.parseSize(chatStyle["top"]);
        } else if (chatStyle["bottom"]) {
            top = window.innerHeight - height - this.parseSize(chatStyle["bottom"]);
        } else if (this.config?.chatTop) {
            top = this.parseSize(this.config.chatTop);
        } else {
            top = this.parseSize(CHAT_CONSTANTS.DEFAULT_POSITION.top);
        }

        return { width, height, left, top, transform: chatStyle["transform"] };
    }

    private getChatStyle(position?: string): Record<string, string> {
        if (!this.config) {
            return {
                width: CHAT_CONSTANTS.DEFAULT_WIDTH,
                height: CHAT_CONSTANTS.DEFAULT_HEIGHT,
                maxWidth: "90vw",
                maxHeight: "100vh",
            };
        }

        const style: Record<string, string> = {
            width: this.config.chatWidth || CHAT_CONSTANTS.DEFAULT_WIDTH,
            height: this.config.chatHeight || CHAT_CONSTANTS.DEFAULT_HEIGHT,
            maxWidth: "90vw",
            maxHeight: "100vh",
        };

        const pos = position || this.config.chatPosition;

        if (pos && pos in CHAT_CONSTANTS.PRESET_POSITIONS) {
            Object.assign(
                style,
                CHAT_CONSTANTS.PRESET_POSITIONS[pos as keyof typeof CHAT_CONSTANTS.PRESET_POSITIONS]
            );
        } else if (
            this.config.chatTop ||
            this.config.chatLeft ||
            this.config.chatRight ||
            this.config.chatBottom
        ) {
            style["transform"] = "none";
            if (this.config.chatTop) style["top"] = this.config.chatTop;
            if (this.config.chatLeft) style["left"] = this.config.chatLeft;
            if (this.config.chatRight) style["right"] = this.config.chatRight;
            if (this.config.chatBottom) style["bottom"] = this.config.chatBottom;
        } else {
            Object.assign(style, CHAT_CONSTANTS.DEFAULT_POSITION);
        }

        return style;
    }

    private parseSize(size: number | string): number {
        if (typeof size === "number") {
            return size;
        }

        if (typeof size === "string" && size.endsWith("px")) {
            return parseFloat(size);
        }

        if (typeof size === "string" && size.endsWith("vh")) {
            return (parseFloat(size) / 100) * window.innerHeight;
        }

        return parseFloat(size) || 0;
    }
}
