import { CommonModule } from "@angular/common";
import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from "@angular/core";
import { EpIconName, IconComponent } from "../icon/icon.component";

export type EpButtonVariant = "secondary" | "primary" | "ghost";
export type EpButtonSize = "sm" | "md";

@Component({
    selector: "ep-button",
    templateUrl: "./button.component.html",
    styleUrls: ["./button.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
    imports: [CommonModule, IconComponent],
})
export class ButtonComponent {
    @Input() disabled = false;
    @Input() type: "button" | "submit" | "reset" = "button";
    @Input() imgPos: "left" | "right" = "left";
    @Input() imgSrc?: string;
    @Input() iconName?: EpIconName;
    @Input() iconSize = 16;
    @Input() iconPos?: "left" | "right";
    @Input() id?: string;
    @Input() noBorder = false;
    @Input() variant: EpButtonVariant = "secondary";
    @Input() size: EpButtonSize = "sm";
    @Output() buttonClick = new EventEmitter<Event>();
    @Output() buttonMouseEnter = new EventEmitter<MouseEvent>();
    @Output() buttonMouseLeave = new EventEmitter<MouseEvent>();

    public onClick(event: Event): void {
        event.stopPropagation();

        if (!this.disabled) {
            this.buttonClick.emit(event);
        }
    }

    public onMouseEnter(event: MouseEvent): void {
        event.stopPropagation();
        this.buttonMouseEnter.emit(event);
    }

    public onMouseLeave(event: MouseEvent): void {
        event.stopPropagation();
        this.buttonMouseLeave.emit(event);
    }

    public get resolvedIconPos(): "left" | "right" {
        return this.iconPos ?? this.imgPos;
    }
}
