import { Injectable } from "@angular/core";
import { EpChatCommand, EpChatCommandResult } from "../models/ep-chat-bridge.model";
import { ActionService } from "./action.service";

interface EpChatRuntimeContext {
    isMonoAgent: boolean;
    [key: string]: unknown;
}

@Injectable()
export class ChatParentBridgeService {
    private lastProcessedCommandRequestId: string | null = null;

    constructor(private actionService: ActionService) {}

    handleCommand(
        command: EpChatCommand | null,
        runtimeContext: EpChatRuntimeContext,
        onCommandResult: (result: EpChatCommandResult) => void
    ): void {
        if (!command?.requestId || !command.action) {
            return;
        }
        if (this.lastProcessedCommandRequestId === command.requestId) {
            return;
        }
        this.lastProcessedCommandRequestId = command.requestId;

        const onCommandSuccess = (cmd: EpChatCommand, payload?: Record<string, unknown>): void => {
            onCommandResult({
                requestId: cmd.requestId,
                action: cmd.action,
                success: true,
                payload,
            });
        };

        const onCommandError = (cmd: EpChatCommand, message: string): void => {
            onCommandResult({
                requestId: cmd.requestId,
                action: cmd.action,
                success: false,
                message,
            });
        };

        this.actionService.handleParentCommand(
            command,
            runtimeContext,
            onCommandSuccess,
            onCommandError
        );
    }
}
