import {
    AfterViewInit,
    Component,
    ElementRef,
    EventEmitter,
    Input,
    OnDestroy,
    Output,
    forwardRef,
} from "@angular/core";
import { FormControl, NG_VALUE_ACCESSOR } from "@angular/forms";
import { CHAT_CONSTANTS } from "../../../constants/chat.constants";
import { getImagePath } from "../../../utils/asset.utils";

interface SpeechRecognitionAlternative {
    transcript: string;
    confidence: number;
}

interface SpeechRecognitionResult {
    [index: number]: SpeechRecognitionAlternative;
    length: number;
    item(index: number): SpeechRecognitionAlternative;
    isFinal: boolean;
}

interface SpeechRecognitionResultList {
    [index: number]: SpeechRecognitionResult;
    length: number;
    item(index: number): SpeechRecognitionResult;
}

interface SpeechRecognitionEvent {
    results: SpeechRecognitionResultList;
    resultIndex: number;
}

interface SpeechRecognitionErrorEvent {
    error: string;
    message: string;
}

interface SpeechRecognitionConstructor {
    new (): {
        interimResults: boolean;
        lang: string;
        maxAlternatives: number;
        continuous: boolean;
        addEventListener: (event: string, callback: (e: unknown) => void) => void;
        start: () => void;
        stop: () => void;
    };
}

@Component({
    selector: "ep-microphone",
    templateUrl: "./microphone.component.html",
    styleUrls: ["./microphone.component.scss"],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => MicrophoneComponent),
            multi: true,
        },
    ],
    standalone: true,
})
export class MicrophoneComponent implements AfterViewInit, OnDestroy {
    @Input() formControl?: FormControl;
    @Input() disabled = false;
    @Input() showIcon = true;
    @Input() iconSize = "16px";
    @Input() toStopOnClickSelector?: string;

    @Output() voiceStart = new EventEmitter<void>();
    @Output() voiceStop = new EventEmitter<void>();
    @Output() voiceError = new EventEmitter<string>();
    @Output() textRecognized = new EventEmitter<string>();

    public isVoiceMessage = false;
    public isSpeechRecognitionOn = false;
    public readonly getImagePath = getImagePath;

    private recognition?: {
        interimResults: boolean;
        lang: string;
        maxAlternatives: number;
        continuous: boolean;
        addEventListener: (event: string, callback: (e: unknown) => void) => void;
        start: () => void;
        stop: () => void;
    };
    private ignoreRecognitionResult = false;
    private voiceInputStartValue = "";
    private onChange = (_value: string): void => {};
    private onTouched = (): void => {};
    private stopOnInteractionHandler?: () => void;

    constructor(private elementRef: ElementRef) {}

    ngAfterViewInit(): void {
        this.voiceInit();
        this.setupStopOnClickAndFocusListeners();
    }

    ngOnDestroy(): void {
        if (this.recognition && this.isSpeechRecognitionOn) {
            this.recognition.stop();
        }
        this.removeStopOnClickAndFocusListeners();
    }

    public startVoiceRecognition(): void {
        if (this.isSpeechRecognitionOn || this.disabled) {
            console.warn("Speech recognition is already running or disabled.");
            return;
        }

        this.voiceInputStartValue = this.formControl?.value || "";
        this.isVoiceMessage = true;
        this.isSpeechRecognitionOn = true;
        this.voiceStart.emit();
        this.recognition?.start();
    }

    public stopVoiceRecognition(): void {
        if (!this.isSpeechRecognitionOn) {
            console.warn("Speech recognition is not running.");
            return;
        }

        this.ignoreRecognitionResult = true;
        this.isSpeechRecognitionOn = false;
        this.voiceStop.emit();
        this.recognition?.stop();
    }

    private voiceInit(): void {
        const SpeechRecognitionConstructor =
            (window as unknown as { SpeechRecognition?: SpeechRecognitionConstructor })
                .SpeechRecognition ||
            (window as unknown as { webkitSpeechRecognition?: SpeechRecognitionConstructor })
                .webkitSpeechRecognition;

        if (!SpeechRecognitionConstructor) {
            console.error("SpeechRecognition API is not supported in this browser.");
            this.voiceError.emit("SpeechRecognition API is not supported in this browser.");
            return;
        }

        this.recognition = new SpeechRecognitionConstructor();
        this.recognition.interimResults = true;
        this.recognition.lang = "en-US";
        this.recognition.maxAlternatives = 1;
        this.recognition.continuous = true;

        this.recognition.addEventListener("result", (e: unknown) => {
            if (this.ignoreRecognitionResult) {
                return;
            }

            const event = e as SpeechRecognitionEvent;
            const transcript = Array.from(event.results)
                .map((result: SpeechRecognitionResult) => result[0].transcript)
                .join("")
                .replace(/^[\r\n]+/, "");

            const fullText = this.voiceInputStartValue + transcript;
            if (fullText.length > CHAT_CONSTANTS.MAX_INPUT_LENGTH) {
                this.voiceError.emit("Text is too long");
                this.stopVoiceRecognition();
                return;
            }

            if (this.formControl) {
                this.formControl.setValue(fullText + " ");
            }

            this.textRecognized.emit(fullText);
        });

        this.recognition.addEventListener("end", () => {
            this.isSpeechRecognitionOn = false;
            this.ignoreRecognitionResult = false;
        });

        this.recognition.addEventListener("error", (e: unknown) => {
            console.error("SpeechRecognition error:", e);
            this.isSpeechRecognitionOn = false;
            const errorEvent = e as SpeechRecognitionErrorEvent;
            this.voiceError.emit(errorEvent.error || "Speech recognition error occurred");
        });
    }

    writeValue(_value: string): void {}

    registerOnChange(fn: (value: string) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        this.disabled = isDisabled;
    }

    private setupStopOnClickAndFocusListeners(): void {
        if (!this.toStopOnClickSelector) return;

        const root = this.elementRef.nativeElement.getRootNode() as Document | ShadowRoot;
        const element = root.querySelector(this.toStopOnClickSelector);
        if (!element) return;

        this.stopOnInteractionHandler = () => {
            if (this.isSpeechRecognitionOn) {
                this.stopVoiceRecognition();
            }
        };

        element.addEventListener("click", this.stopOnInteractionHandler);
        element.addEventListener("focus", this.stopOnInteractionHandler);
        element.addEventListener("focusin", this.stopOnInteractionHandler);
    }

    private removeStopOnClickAndFocusListeners(): void {
        if (!this.toStopOnClickSelector) return;

        const root = this.elementRef.nativeElement.getRootNode() as Document | ShadowRoot;
        const element = root.querySelector(this.toStopOnClickSelector);
        if (!element) return;

        if (this.stopOnInteractionHandler) {
            element.removeEventListener("click", this.stopOnInteractionHandler);
            element.removeEventListener("focus", this.stopOnInteractionHandler);
            element.removeEventListener("focusin", this.stopOnInteractionHandler);
        }
    }
}
