    ngOnInit(): void {
        this.initializeSubscriptions();
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    private initializeSubscriptions(): void {
        this.subscriptions.add(
            this.messageInputControl.valueChanges.subscribe((value: string) => {
                if (value && /^[\r\n]+/.test(value)) {
                    const trimmedValue = value.replace(/^[\r\n]+/, "");
                    this.messageInputControl.setValue(trimmedValue, { emitEvent: false });
                    return;
                }

                if (value?.length > CHAT_CONSTANTS.MAX_INPUT_LENGTH) {
                    this.messageInputControl.setValue(
                        value.slice(0, CHAT_CONSTANTS.MAX_INPUT_LENGTH - 1),
                        {
                            emitEvent: false,
                        }
                    );
                }
            })
        );

        // no effects needed; template reads signals directly
    }

    public transmitMessageFromInput(): void {
        if (!this.isSendButtonEnabled()) return;

        const text = this.messageInputControl.value?.trim() || "";

        if (text?.length) {
            const isVoice = this.isVoiceMessage;
            const tool = this.effectiveSelectedTool;
            this.stopMicrophoneIfActive();
            this.sendMessage.emit({
                text,
                isVoice,
                tool,
                webConfig:
                    this.allowWebFromResponse && this.webMode()
                        ? { mode: this.webMode()!, sites: this.sites().filter((s) => !!s.trim()) }
                        : null,
            });
            this.messageInputControl.setValue("");
            this.isVoiceMessage = false;
        }
    }

    private stopMicrophoneIfActive(): void {
        if (this.microphoneComponent?.isSpeechRecognitionOn) {
            this.microphoneComponent.stopVoiceRecognition();
        }
    }

    public onKeydown(event: KeyboardEvent): void {
        if (event.key.length === 1 || event.key === "Backspace" || event.key === "Delete") {
            this.isVoiceMessage = false;
        }

        switch (event.key) {
            case "Enter":
                this.handleEnterKey(event);
                break;
            // case "ArrowUp":
            // case "ArrowDown":
            //     this.handleArrowKeys(event);
            //     break;
            default:
                this.handleDefaultKey(event);
                break;
        }
    }

    private handleEnterKey(ev: KeyboardEvent): void {
        // Shift+Enter — просто новая строка, без отправки
        if (ev.shiftKey) {
            return;
        }

        if (!this.isSendButtonEnabled() || this.isTyping) return;
        ev.preventDefault();
        this.transmitMessageFromInput();
    }

