    private handleDefaultKey(ev: KeyboardEvent): void {
        if ((ev.ctrlKey || ev.metaKey) && ev.code === "KeyZ") {
            ev.stopPropagation();
            return;
        }

        const currentInputValue = this.messageInputControl.value || "";
        if (
            currentInputValue.length >= CHAT_CONSTANTS.MAX_INPUT_LENGTH &&
            ev.key.length === 1 &&
            !ev.ctrlKey &&
            !ev.metaKey
        ) {
            ev.preventDefault();
            return;
        }

        ev.stopPropagation();
        setTimeout(() => {
            this.manuallyEnteredText =
                this.messageInputControl.value?.replace(/\r?\n/g, "").trim() || "";
        }, 100);
    }

    public isSendButtonEnabled(): boolean {
        const value = this.messageInputControl.value?.trim();
        return !!value && value.length > 0 && value.length < CHAT_CONSTANTS.MAX_INPUT_LENGTH;
    }

    public onVoiceStart(): void {
        this.isVoiceMessage = true;
    }

    public onTextRecognized(): void {
        this.isVoiceMessage = true;
    }

    public ngOnChanges(changes: SimpleChanges): void {
        if (changes["messages"] && this.selectedTool) {
            const lastBotMessage = this.lastFinishedBotMessage;
            if (lastBotMessage && !lastBotMessage._interim) {
                const tools = lastBotMessage.response?.tools;
                if (!Array.isArray(tools) || !tools.includes(this.selectedTool)) {
                    this.selectedTool = null;
                }
            }
        }
    }

    private get lastFinishedBotMessage() {
        for (let i = this.messages.length - 1; i >= 0; i--) {
            const msg = this.messages[i];
            if (msg.response && !msg._interim) {
                return msg;
            }
        }
        return null;
    }

    public get allowFilesFromResponse(): boolean {
        return this.lastFinishedBotMessage?.response?.allow_files === true;
    }

    public get allowWebFromResponse(): boolean {
        return this.lastFinishedBotMessage?.response?.allow_web === true;
    }

    private closeAllMenus(): void {
        this.isToolMenuOpen = false;
        this.isWebMenuOpen = false;
        this.chatService.setIsRecentFilesMenuShown(false);
    }

    public toggleWebMenu(): void {
        const opening = !this.isWebMenuOpen;
        this.closeAllMenus();
        this.isWebMenuOpen = opening;
    }

    public selectWebMode(mode: WebMode | null): void {
        this.webMode.set(mode);
        if (mode !== "restrict" && mode !== "prioritize") {
            this.isWebMenuOpen = false;
        } else if (this.sites().length === 0) {
            this.addSite(0);
        } else {
            this.editingSiteIndex = this.sites().length - 1;
            this.focusLastSiteInput();
        }
    }

    public addSite(focusIndex?: number | null): void {
        const nextIndex = this.sites().length;
        this.sites.update((s) => [...s, ""]);

        const targetIndex =
            focusIndex === undefined || focusIndex === null ? nextIndex : focusIndex;

        if (targetIndex !== null) {
            this.editingSiteIndex = targetIndex;
            this.focusLastSiteInput();
        }
    }

    private focusLastSiteInput(): void {
        this.focusSiteInput(this.sites().length - 1);
    }

    private focusSiteInput(index: number): void {
        if (index < 0) return;

        let attempts = 0;
        const tryFocus = () => {
            const inputs = document.querySelectorAll<HTMLInputElement>(".web-menu__site-input");
            const targetInput = inputs[index];

            if (targetInput) {
                targetInput.focus({ preventScroll: true });
                return;
            }

            attempts += 1;
            if (attempts < 8) {
                requestAnimationFrame(tryFocus);
            }
        };

        requestAnimationFrame(tryFocus);
    }

    public removeSite(index: number): void {
        this.sites.update((s) => s.filter((_, i) => i !== index));

        if (this.editingSiteIndex !== null) {
            if (this.editingSiteIndex === index) {
                this.editingSiteIndex = null;
            } else if (this.editingSiteIndex > index) {
                this.editingSiteIndex = this.editingSiteIndex - 1;
            }
        }
    }

    public updateSite(index: number, event: Event): void {
        const value = (event.target as HTMLInputElement).value;
        this.sites.update((s) => {
            const copy = [...s];
            copy[index] = value;
            return copy;
        });
    }

    public onSiteInputEnter(index: number, event: Event): void {
        event.preventDefault();
        event.stopPropagation();
        this.addSite();
    }

    public startEditSite(index: number): void {
        this.editingSiteIndex = index;
        this.focusSiteInput(index);
    }

    public get availableTools(): string[] {
        for (let i = this.messages.length - 1; i >= 0; i--) {
            const msg = this.messages[i];
            if (msg.response && !msg._interim) {
                return Array.isArray(msg.response.tools) ? (msg.response.tools as string[]) : [];
            }
        }
        return [];
    }

    public get effectiveSelectedTool(): string | null {
        return this.selectedTool && this.availableTools.includes(this.selectedTool)
            ? this.selectedTool
            : null;
    }

    public toggleToolMenu(): void {
        const opening = !this.isToolMenuOpen;
        this.closeAllMenus();
        this.isToolMenuOpen = opening;
    }

    public selectTool(tool: string | null): void {
        this.selectedTool = tool;
        this.isToolMenuOpen = false;
    }

    public stopGenerating(): void {
        this.stop.emit();
    }

    public focus(): void {
        this.messageInput?.nativeElement.focus();
    }

    // File attachment methods
    public toggleRecentFilesMenu(): void {
        if (!this.fileAttachmentEnabled) return;
        const opening = !this.chatService.isRecentFilesMenuShown();
        this.closeAllMenus();
        if (opening) {
            this.chatService.setIsRecentFilesMenuShown(true);
        }
    }

    public onFileAttached(file: File): void {
        if (!this.fileAttachmentEnabled) return;

        if (this.isMultipleFilesMode()) {
            const newFiles = [...(this.chatService.attachedFiles() || []), file];
            this.chatService.setAttachedFiles(newFiles);
        } else {
            this.chatService.setAttachedFile(file);
        }

        this.saveFilesToRecent([file]);
    }

    public onFilesAttached(files: File[]): void {
        if (!this.fileAttachmentEnabled || !this.isMultipleFilesMode()) return;

        const newFiles = [...(this.chatService.attachedFiles() || []), ...files];
        this.chatService.setAttachedFiles(newFiles);

        this.saveFilesToRecent(files);
    }

    private saveFilesToRecent(files: File[]): void {
        this.apiService.getRecentFilesFromIndexedDB().then((recentFiles) => {
            const updatedFiles = recentFiles.filter(
                (f) => !files.some((newFile) => newFile.name === f.name && newFile.size === f.size)
            );
            updatedFiles.push(...files);
            this.apiService.saveRecentFilesToIndexedDB(updatedFiles);
        });
    }

    public isMultipleFilesMode(): boolean {
        return this.currentAgent?.epicstaffAgentId !== undefined;
    }

    public hasAttachedFiles(): boolean {
        if (this.isMultipleFilesMode()) {
            return (this.chatService.attachedFiles() || []).length > 0;
        }
        return this.chatService.attachedFile() !== null;
    }

    public onDeselectFileFromMultiple(file: File): void {
        if (this.isMultipleFilesMode()) {
            const current = this.chatService.attachedFiles() || [];
            const newFiles = current.filter((f) => f.name !== file.name || f.size !== file.size);
            this.chatService.setAttachedFiles(newFiles);
        }
    }

    public onDeselectFile(): void {
        if (this.fileAttachmentEnabled) {
            this.chatService.setAttachedFile(null);
        }
    }

    public onRepeatFile(): void {
        if (this.fileAttachmentEnabled && this.chatService.isLastRequestUsedFile()) {
            // Logic for reusing the last file
            // Can get the last file from history or state
        }
    }

    public hideRecentFilesMenu(): void {
        if (this.fileAttachmentEnabled) {
            this.chatService.setIsRecentFilesMenuShown(false);
        }
    }

    /**
     * Track function for files
     */
    trackFileById(index: number, file: File): string {
        return `${file.name}_${file.size}_${file.lastModified}_${index}`;
    }
