import { CommonModule } from "@angular/common";
import {
    AfterViewChecked,
    AfterViewInit,
    Component,
    ElementRef,
    EventEmitter,
    HostBinding,
    HostListener,
    Input,
    OnDestroy,
    Output,
    ViewChild,
} from "@angular/core";

@Component({
    selector: "ep-modal",
    imports: [CommonModule],
    templateUrl: "./modal.component.html",
    styleUrls: ["./modal.component.scss"],
})
export class ModalComponent implements AfterViewInit, AfterViewChecked, OnDestroy {
    /** Whether to show "x" button at the top right */
    @Input() closable = true;
    /** Additional class name to add to the dialog */
    @Input() styleClass = "";
    @Input() subContainerStyleClass = "";
    /** Whether to allow closing modal by clicking on the overlay */
    @Input() closableOverlay = true;
    /** If true, scrollbar may appear inside the modal; otherwise modal adapts its height */
    @Input() scrollable = true;
    @Input() zIndex = 11000;
    @Input() positionTop?: number;
    @Input() visible = true;

    @HostListener("document:click", ["$event"])
    onDocumentClick(event: MouseEvent): void {
        // Prevent closing when clicking inside modal
        const target = event.target as HTMLElement;
        if (target.closest(".ep-modal-container")) {
            return;
        }
    }

    @Output() ready = new EventEmitter<void>();
    @Output() closed = new EventEmitter<void>();
    @Output() clickedOutside = new EventEmitter<void>();

    @ViewChild("modalWrapper") modalWrapper?: ElementRef<HTMLElement>;

    isReady = false;
    isClosing = false;
    private wasVisible = false;

    private static lastFocusableElements: ElementRef<HTMLElement>[] = [];

    ngAfterViewInit(): void {
        this.initializeModal();
    }

    ngAfterViewChecked(): void {
        // Если модалка только что стала видимой
        if (this.visible && !this.wasVisible && this.modalWrapper?.nativeElement) {
            this.initializeModal();
        }
        this.wasVisible = this.visible;
    }

    private initializeModal(): void {
        if (this.visible && this.modalWrapper?.nativeElement && !this.isReady) {
            // Проверяем, что элемент еще не добавлен в список
            const alreadyAdded = ModalComponent.lastFocusableElements.includes(this.modalWrapper);
            if (!alreadyAdded) {
                ModalComponent.lastFocusableElements.push(this.modalWrapper);
            }
            this.modalWrapper.nativeElement.focus();
            setTimeout(() => {
                this.isReady = true;
                this.ready.emit();
            }, 0);
        }
    }

    ngOnDestroy(): void {
        if (this.modalWrapper) {
            const index = ModalComponent.lastFocusableElements.indexOf(this.modalWrapper);
            if (index > -1) {
                ModalComponent.lastFocusableElements.splice(index, 1);
            }
        }
    }

    close(): void {
        if (this.isClosing) return;

        this.isClosing = true;
        this.isReady = false; // Сбрасываем флаг готовности
        this.closed.emit();

        if (this.modalWrapper) {
            const index = ModalComponent.lastFocusableElements.indexOf(this.modalWrapper);
            if (index > -1) {
                ModalComponent.lastFocusableElements.splice(index, 1);
            }
        }

        if (ModalComponent.lastFocusableElements.length > 0) {
            const lastElement =
                ModalComponent.lastFocusableElements[
                    ModalComponent.lastFocusableElements.length - 1
                ];
            lastElement?.nativeElement.focus();
        }

        // Reset closing state after animation
        setTimeout(() => {
            this.isClosing = false;
        }, 300);
    }

    onOverlayClick(event: Event): void {
        event.stopPropagation();
        this.clickedOutside.emit();
        if (this.closableOverlay) {
            this.close();
        }
    }

    @HostListener("window:keydown.escape", ["$event"])
    onEscapeKey(event: Event): void {
        if (this.closableOverlay && this.visible && !this.isClosing) {
            this.close();
            event.stopPropagation();
        }
    }

    @HostBinding("class.hidden")
    get isHidden(): boolean {
        return !this.visible || this.isClosing;
    }

    @HostBinding("style.z-index")
    get zindex(): number {
        return this.zIndex;
    }
}
