@Component({
    selector: "ep-icon",
    standalone: true,
    template: `<span [innerHTML]="svg"></span>`,
    styles: [
        `
            :host {
                display: inline-flex;
                align-items: center;
                justify-content: center;
            }
            span {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                width: 100%;
                height: 100%;
            }
            svg {
                display: block;
                width: 100%;
                height: 100%;
            }
        `,
    ],
})
export class IconComponent implements OnChanges {
    @Input() name!: EpIconName;
    @Input() size?: number;

    @HostBinding("style.width.px") get w() {
        return this.size;
    }
    @HostBinding("style.height.px") get h() {
        return this.size;
    }

    svg!: SafeHtml;

    constructor(private sanitizer: DomSanitizer) {}

    ngOnChanges(): void {
        const raw = ICONS[this.name] ?? "";
        this.svg = this.sanitizer.bypassSecurityTrustHtml(raw);
    }
}
