import {
    ApplicationRef,
    ComponentRef,
    createComponent,
    EnvironmentInjector,
    Injectable,
    NgZone,
} from "@angular/core";
import { TooltipComponent } from "../components/shared/tooltip/tooltip.component";
import { TooltipOptions, TooltipState } from "../models/tooltip.interface";

/**
 * ### Using tooltip programmatically
 *
 * constructor(private tooltipService: TooltipService) {}
 * ...
 * this.tooltipService.show(event.target, text, { delay: 500 });
 * this.tooltipService.hide(event.target);
 */
@Injectable({
    providedIn: "root",
})
export class TooltipService {
    private readonly DEFAULT_SHOW_DELAY = 50;
    private readonly DEFAULT_HIDE_DELAY = 150;

    private tooltipComponentRef: ComponentRef<TooltipComponent> | null = null;
    private showTimeoutId: ReturnType<typeof setTimeout> | null = null;
    private hideTimeoutId: ReturnType<typeof setTimeout> | null = null;
    private intersectionObserver: IntersectionObserver | null = null;

    constructor(
        private appRef: ApplicationRef,
        private injector: EnvironmentInjector,
        private zone: NgZone
    ) {}

    public show(element: HTMLElement, text: string, options: TooltipOptions = {}): void {
        if (this.hideTimeoutId) {
            clearTimeout(this.hideTimeoutId);
            this.hideTimeoutId = null;
        }

        if (this.showTimeoutId) {
            clearTimeout(this.showTimeoutId);
        }

        if (this.tooltipComponentRef) {
            this.destroyTooltip();
        }

        const delay = options.delay || this.DEFAULT_SHOW_DELAY;
        const trimmedText = text.replace(/^[ \t]+/gm, "");

        this.showTimeoutId = setTimeout(() => {
            this.zone.run(() => {
                if (!document.body.contains(element)) {
                    return;
                }
                this.createOrUpdateTooltip({ show: true, text: trimmedText, options, element });
            });
        }, delay);
    }

    public hide(element: HTMLElement, immediate: boolean = false): void {
        if (this.showTimeoutId) {
            clearTimeout(this.showTimeoutId);
            this.showTimeoutId = null;
        }

        if (this.hideTimeoutId && !immediate) {
            return;
        }

        const hideTooltip = () => {
            this.zone.run(() => {
                const currentElement = this.tooltipComponentRef?.instance.state.element;
                if (currentElement === element) {
                    this.destroyTooltip();
                } else if (currentElement && !this.isElementVisibleLightweight(currentElement)) {
                    this.destroyTooltip();
                }
            });
        };

        if (immediate) {
            if (this.hideTimeoutId) {
                clearTimeout(this.hideTimeoutId);
                this.hideTimeoutId = null;
            }
            hideTooltip();
        } else {
            this.hideTimeoutId = setTimeout(hideTooltip, this.DEFAULT_HIDE_DELAY);
        }
    }

    public hideAll(): void {
        if (this.showTimeoutId) {
            clearTimeout(this.showTimeoutId);
            this.showTimeoutId = null;
        }

        if (this.hideTimeoutId) {
            clearTimeout(this.hideTimeoutId);
            this.hideTimeoutId = null;
        }

        this.zone.run(() => {
            this.destroyTooltip();
        });
    }

    private createOrUpdateTooltip(state: TooltipState): void {
        if (!this.tooltipComponentRef) {
            this.tooltipComponentRef = createComponent(TooltipComponent, {
                environmentInjector: this.injector,
            });

            this.appRef.attachView(this.tooltipComponentRef.hostView);
            const domElem = this.tooltipComponentRef.location.nativeElement as HTMLElement;

            document.body.appendChild(domElem);
        }

        this.tooltipComponentRef.instance.state = state;
        this.tooltipComponentRef.instance.updateAndShow();
        this.startVisibilityCheck();
    }

    private destroyTooltip(): void {
        this.stopVisibilityCheck();
        if (this.tooltipComponentRef) {
            this.appRef.detachView(this.tooltipComponentRef.hostView);
            this.tooltipComponentRef.destroy();
            this.tooltipComponentRef = null;
        }
    }

    private startVisibilityCheck(): void {
        this.stopVisibilityCheck();

        const element = this.tooltipComponentRef?.instance.state.element;
        if (!element) {
            return;
        }

        // Use IntersectionObserver for efficient visibility tracking
        // This is much more performant than setInterval + getComputedStyle
        if (typeof IntersectionObserver !== "undefined") {
            this.intersectionObserver = new IntersectionObserver(
                (entries) => {
                    this.zone.run(() => {
                        for (const entry of entries) {
                            const target = entry.target as HTMLElement;

                            // Check if element still exists in DOM
                            if (!document.body.contains(target)) {
                                this.destroyTooltip();
                                return;
                            }

                            // If element is not intersecting (not visible in viewport) or has zero dimensions
                            // Also check with lightweight method for CSS-hidden elements
                            if (
                                !entry.isIntersecting ||
                                !this.isElementVisibleLightweight(target)
                            ) {
                                this.destroyTooltip();
                            }
                        }
                    });
                },
                {
                    // Observe when element enters/leaves viewport or becomes hidden
                    threshold: 0,
                    root: null, // viewport
                }
            );

            this.intersectionObserver.observe(element);
        } else {
            // Fallback for browsers without IntersectionObserver support
            // Use lightweight periodic check (less frequent and without expensive operations)
            const checkInterval = setInterval(() => {
                this.zone.run(() => {
                    if (!this.tooltipComponentRef) {
                        clearInterval(checkInterval);
                        return;
                    }

                    const currentElement = this.tooltipComponentRef.instance.state.element;
                    if (!currentElement || !this.isElementVisibleLightweight(currentElement)) {
                        clearInterval(checkInterval);
                        this.destroyTooltip();
                    }
                });
            }, 1000); // Check every second as fallback

            // Store interval ID for cleanup (we'll use intersectionObserver field for this)
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (this.intersectionObserver as any) = { disconnect: () => clearInterval(checkInterval) };
        }
    }

    private stopVisibilityCheck(): void {
        if (this.intersectionObserver) {
            if (
                typeof IntersectionObserver !== "undefined" &&
                "disconnect" in this.intersectionObserver
            ) {
                this.intersectionObserver.disconnect();
            } else {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const fallbackObserver = this.intersectionObserver as any;
                if (typeof fallbackObserver.disconnect === "function") {
                    fallbackObserver.disconnect();
                }
            }
            this.intersectionObserver = null;
        }
    }

    /**
     * Lightweight visibility check without expensive operations like getComputedStyle
     * This is used as a fallback or additional check
     */
    private isElementVisibleLightweight(element: HTMLElement): boolean {
        // Quick check: element exists in DOM
        if (!document.body.contains(element)) {
            return false;
        }

        // Quick check: offsetParent (works for most cases, except fixed/absolute without positioned parent)
        // This is much faster than getComputedStyle
        if (element.offsetParent === null && element !== document.body) {
            // For fixed/absolute elements, check dimensions instead
            // getBoundingClientRect is cached by browser, so it's relatively fast
            const rect = element.getBoundingClientRect();
            if (rect.width === 0 && rect.height === 0) {
                return false;
            }
        }

        return true;
    }
}
