/**
 * Типы для Epicstaff API
 * Основаны на реальных ответах от API
 */

/**
 * Ответ на POST /api/run-session/
 */
export interface EpicstaffSessionResponse {
    session_id: number;
}

/**
 * Базовые поля для всех SSE сообщений с message_data
 */
interface BaseEpicstaffSseMessage {
    session_id: number;
    name: string;
    execution_order: number;
    timestamp: string;
    uuid: string;
}

/**
 * Message data - union type для всех типов
 */
export type EpicstaffMessageData =
    | { input: Record<string, unknown>; message_type: "start" }
    | { python_code_execution_data: EpicstaffPythonExecutionData; message_type: "python" }
    | EpicstaffStreamMessageData
    | EpicstaffFinishMessageData
    | { message_type: "graph_end"; end_node_result: Record<string, unknown> };

/**
 * Python code execution data
 */
interface EpicstaffPythonExecutionData {
    execution_id: string;
    result_data: string; // JSON string
    stderr: string;
    stdout: string;
    returncode: number;
}

/**
 * Message data для типа "finish" (единственный сложный тип, который используется)
 */
export interface EpicstaffFinishMessageData {
    output: Record<string, unknown> | string | null;
    state: {
        variables: Record<string, unknown>;
        context?: Record<string, unknown>;
    };
    state_history: Array<Record<string, unknown>>;
    message_type: "finish";
    additional_data?: Record<string, unknown>;
}

export interface EpicstaffStreamToolCall {
    name?: string;
    arguments?: unknown;
    [key: string]: unknown;
}

export interface EpicstaffStreamMessageData {
    message_type: "code_agent_stream" | "crewai_output" | "python_stream";
    text?: string;
    tool_calls?: EpicstaffStreamToolCall[];
    is_final?: boolean;
    sse_visible?: boolean;
    [key: string]: unknown;
}

/**
 * SSE сообщение с message_data (объединяет "s" и "messages" события)
 */
export interface EpicstaffMessagesSseMessage extends BaseEpicstaffSseMessage {
    message_data: EpicstaffMessageData;
}

/**
 * SSE сообщение типа "status"
 */
export interface EpicstaffStatusSseMessage {
    session_id: number;
    status: "run" | "end";
    status_data: Record<string, unknown>;
}

/**
 * Type guard для проверки finish message
 */
export function isFinishMessageData(
    data: EpicstaffMessageData
): data is EpicstaffFinishMessageData {
    return data.message_type === "finish";
}

export function isStreamMessageData(
    data: EpicstaffMessageData
): data is EpicstaffStreamMessageData {
    return (
        data.message_type === "code_agent_stream" ||
        data.message_type === "crewai_output" ||
        data.message_type === "python_stream"
    );
}

export function extractOutputFromFinishMessage(
    messageData: EpicstaffFinishMessageData
): Record<string, unknown> | string | null {
    return messageData.output;
}

/**
 * Полный ответ от Epicstaff API
 * Структура данных, которую возвращает Python код в output
 * Используется только для парсинга ответов API, затем конвертируется в EpResponse
 */
export interface EpicstaffResponse {
    message?: string;
    time?: string;
    tables?: EpicstaffTable[];
    action_message?: EpicstaffAction[];
    [key: string]: unknown;
}

/**
 * Таблица в формате Epicstaff API
 * Используется только для парсинга ответов API
 */
export interface EpicstaffTable {
    rows: Record<string, unknown>[];
    isEditable?: boolean;
    [key: string]: unknown;
}

/**
 * Действие в формате Epicstaff API
 * Используется только для парсинга ответов API, затем конвертируется в Action
 */
export interface EpicstaffAction {
    text: string;
    type?: "button" | "link" | "prompt";
    action?: string;
    params?: Record<string, unknown>;
    sequence?: string | number;
    tab?: string;
    link?: string;
    disabled?: boolean;
    flow_id?: string | number;
    url?: string;
    [key: string]: unknown;
}
