import { Component, ElementRef, EventEmitter, HostListener, Output } from "@angular/core";

@Component({
    selector: "ep-menu",
    template: `<ng-content></ng-content>`,
    styleUrls: ["./menu.component.scss"],
})
export class MenuComponent {
    @Output() closed = new EventEmitter<void>();

    private filePickerActive = false;
    private outsideClickEnabled = false;

    constructor(private elRef: ElementRef) {
        // Ignore document:click in the same event loop tick that created this menu.
        // Without this, the click that opens the menu also triggers onDocumentClick
        // and immediately closes it.
        setTimeout(() => (this.outsideClickEnabled = true));
    }

    /** Detect when a file input (or label wrapping one) is clicked inside the menu */
    @HostListener("click", ["$event"])
    onMenuClick(event: MouseEvent): void {
        const target = event.target as HTMLElement;
        const isFileInput =
            target.tagName === "INPUT" && (target as HTMLInputElement).type === "file";
        const isLabelWithFileInput =
            target.tagName === "LABEL" && !!target.querySelector('input[type="file"]');
        if (isFileInput || isLabelWithFileInput) {
            this.filePickerActive = true;
        }
    }

    /** Window loses focus when any native dialog (e.g. file picker) opens */
    @HostListener("window:blur")
    onWindowBlur(): void {
        if (this.hasFileInput()) {
            this.filePickerActive = true;
        }
    }

    /** Window regains focus when the native file dialog is dismissed */
    @HostListener("window:focus")
    onWindowFocus(): void {
        if (this.filePickerActive) {
            // Give the change event time to fire before re-enabling outside-click
            setTimeout(() => {
                this.filePickerActive = false;
            }, 300);
        }
    }

    private hasFileInput(): boolean {
        return !!this.elRef.nativeElement.querySelector('input[type="file"]');
    }

    @HostListener("document:click", ["$event"])
    onDocumentClick(event: MouseEvent): void {
        if (!this.outsideClickEnabled || this.filePickerActive) return;
        const path = event.composedPath?.() ?? [];
        const inside =
            path.includes(this.elRef.nativeElement) ||
            this.elRef.nativeElement.contains(event.target as Node);
        if (!inside) {
            this.closed.emit();
        }
    }

    @HostListener("document:keydown.escape")
    onEscape(): void {
        this.closed.emit();
    }
}
