import { Directive, ElementRef, EventEmitter, HostListener, Output } from "@angular/core";

@Directive({
    selector: "[epClickOutside]",
})
export class ClickOutsideDirective {
    @Output() epClickOutside = new EventEmitter<void>();

    constructor(private elementRef: ElementRef) {}

    @HostListener("document:click", ["$event"])
    onClick(event: MouseEvent): void {
        const path = event.composedPath?.() ?? [];
        const host = this.elementRef.nativeElement as Node;
        const target = event.target as Node | null;
        const clickedInside = path.includes(host) || (!!target && host.contains(target));
        if (!clickedInside) {
            this.epClickOutside.emit();
        }
    }
}
