/**
 * Commands from parent host app to chat widget.
 * Used to ask the widget to do something (e.g. create/select agent).
 */
export const EP_CHAT_COMMANDS = {
    AGENT_CREATE: "agent.create",
    AGENT_SELECT: "agent.select",
    AGENT_REMOVE: "agent.remove",
    AGENTS_SYNC: "agents.sync",
} as const;

export type EpChatAction = (typeof EP_CHAT_COMMANDS)[keyof typeof EP_CHAT_COMMANDS];

/**
 * Events from chat widget to parent host app.
 * Used when widget wants the host to react (open flow/node, refresh cache, etc.).
 */
export const EP_CHAT_EVENTS = {
    CHAT_CLOSED: "chat.closed",
    CHAT_OPENED: "chat.opened",
    APP_OPEN_FLOW: "app.openFlow",
    APP_OPEN_NODE: "app.openNode",
    APP_REFRESH_CACHE: "app.refreshCache",
    APP_TOGGLE_DOCK: "app.toggleDock",
    AGENT_DISCONNECTED: "agent.disconnected",
} as const;

export type EpChatEventType = (typeof EP_CHAT_EVENTS)[keyof typeof EP_CHAT_EVENTS];

export interface EpChatCreateAgentPayload {
    id?: number;
    name: string;
    description?: string;
    flowId: number | string;
    flowUrl: string;
    imagePath?: string;
    selectAfterCreate?: boolean;
}

export interface EpChatSelectAgentPayload {
    id: number;
}

export interface EpChatRemoveAgentPayload {
    flowId: number | string;
}

export interface EpChatSyncAgentsPayload {
    agents: EpChatCreateAgentPayload[];
}

export type EpChatCommandPayload =
    | EpChatCreateAgentPayload
    | EpChatSelectAgentPayload
    | EpChatRemoveAgentPayload
    | EpChatSyncAgentsPayload;

export interface EpChatCommand {
    requestId: string;
    action: EpChatAction | string;
    payload: EpChatCommandPayload;
}

export interface EpChatCommandResult {
    requestId: string;
    action: EpChatAction | string;
    success: boolean;
    message?: string;
    payload?: Record<string, unknown>;
}

export interface EpChatEvent {
    type: EpChatEventType | string;
    payload?: Record<string, unknown>;
}
