/**
 * UI element types coming from backend (how to render action in chat).
 */
export enum UserActionType {
    Button = "button",
    Prompt = "prompt",
    Link = "link",
}

/**
 * High-level actions triggered from UI elements (buttons/links/prompts).
 * Depending on the value:
 * - can trigger a local action in the chat,
 * - send a request to the backend,
 * - or dispatch an event to the parent application (via EP_CHAT_EVENTS).
 */
export enum UserAction {
    // Local chat-only actions (no direct parent app involvement)
    EpicstaffSwitchAgent = "switchAgent",
    EpicstaffProcessTables = "processTables",
    EpicstaffResetTable = "resetTable",
    Link = "link",
    Cancel = "cancel",
    DownloadEpTableCsv = "downloadEpTableCsv",
    DownloadEpTableExcel = "downloadEpTableExcel",

    // Backend round-trip / context actions
    SendAction = "sendAction",
    SendButtonTextWithParams = "sendButtonTextWithParams",
    AddTokens = "addTokens",
    Continue = "continue",

    // Bridge to parent app (mapped to EP_CHAT_EVENTS)
    OpenFlow = "openFlow",
    OpenNode = "openNode",
    RefreshCache = "refreshCache",
}
