import { CommonModule } from "@angular/common";
import {
    ChangeDetectionStrategy,
    Component,
    ElementRef,
    EventEmitter,
    Input,
    OnChanges,
    Output,
    SimpleChanges,
    ViewChild,
} from "@angular/core";
import { FormsModule } from "@angular/forms";
import { MatNativeDateModule } from "@angular/material/core";
import { MatDatepicker, MatDatepickerModule } from "@angular/material/datepicker";
import { MatInputModule } from "@angular/material/input";
import { MarkdownComponent } from "ngx-markdown";
import type { DropdownOption, EpTableColumn } from "../../models/table.model";
import { DropdownComponent } from "../shared/dropdown/dropdown.component";

@Component({
    selector: "ep-message-table-cell",
    standalone: true,
    imports: [
        CommonModule,
        FormsModule,
        MarkdownComponent,
        DropdownComponent,
        MatDatepickerModule,
        MatNativeDateModule,
        MatInputModule,
    ],
    templateUrl: "./message-table-cell.component.html",
    styleUrls: ["./message-table-cell.component.scss"],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MessageTableCellComponent implements OnChanges {
    @Input() column!: EpTableColumn;
    @Input() isColumnEditable = true;
    @Input() isEditing = false;
    @Input() displayValue: unknown = "";
    @Input() booleanValue = false;
    @Input() editingDate: Date | null = null;
    @Input() datePickerMinDate: Date | string | null = null;
    @Input() dropdownOptions: DropdownOption[] = [];
    @Input() dropdownSelection: DropdownOption[] | DropdownOption | null = null;

    @Output() cellMouseOver = new EventEmitter<Event>();
    @Output() cellMouseLeave = new EventEmitter<Event>();
    @Output() booleanToggle = new EventEmitter<boolean>();
    @Output() dateChanged = new EventEmitter<Date | null>();
    @Output() dateBlur = new EventEmitter<void>();
    @Output() dropdownFocus = new EventEmitter<void>();
    @Output() selectChanged = new EventEmitter<DropdownOption | null>();
    @Output() multiChanged = new EventEmitter<DropdownOption[]>();
    @Output() editorInput = new EventEmitter<Event>();
    @Output() editorKeydown = new EventEmitter<KeyboardEvent>();
    @Output() editorBlur = new EventEmitter<void>();

    @ViewChild("contentEditableEl") contentEditableEl?: ElementRef<HTMLDivElement>;
    @ViewChild("dateInput") dateInput?: ElementRef<HTMLInputElement>;
    @ViewChild("datePicker") datePicker?: MatDatepicker<Date>;

    showMultiDropdown = false;

    constructor(private host: ElementRef<HTMLElement>) {}

    ngOnChanges(changes: SimpleChanges): void {
        if (changes["isEditing"] && changes["isEditing"].currentValue === true) {
            if (this.column?.type === "date") {
                this.openDatePicker();
            } else {
                this.syncContentEditable();
            }
        }
    }

    onMouseOver(event: Event): void {
        this.cellMouseOver.emit(event);
    }

    onMouseLeave(event: Event): void {
        this.cellMouseLeave.emit(event);
    }

    onBooleanClick(): void {
        if (!this.isColumnEditable) return;
        this.booleanToggle.emit(!this.booleanValue);
    }

    onDateValueChange(value: Date | null): void {
        if (!value) {
            this.dateChanged.emit(null);
            return;
        }
        this.dateChanged.emit(isNaN(value.getTime()) ? null : value);
    }

    onDateBlurInternal(): void {
        this.dateBlur.emit();
    }

    onDatePickerClosed(): void {
        this.dateBlur.emit();
    }

    onDropdownFocusInternal(): void {
        this.dropdownFocus.emit();
    }

    onDropdownSelectedChange(value: DropdownOption | DropdownOption[] | null): void {
        if (this.column.type === "select") {
            if (!value || Array.isArray(value)) {
                this.selectChanged.emit(value && value.length ? value[0] : null);
                return;
            }
            this.selectChanged.emit(value);
            return;
        }

        const arr = Array.isArray(value) ? value : value ? [value] : [];
        this.multiChanged.emit(arr);
    }

    onEditorInputInternal(event: Event): void {
        if (this.column?.type === "number") {
            const el = this.contentEditableEl?.nativeElement;
            if (el) {
                const next = this.sanitizeNumberInput(el.textContent || "");
                if ((el.textContent || "") !== next) {
                    el.textContent = next;
                    const selection = window.getSelection();
                    if (selection) {
                        selection.removeAllRanges();
                        const range = document.createRange();
                        range.selectNodeContents(el);
                        range.collapse(false);
                        selection.addRange(range);
                    }
                }
            }
        }
        this.editorInput.emit(event);
    }

    onEditorKeydownInternal(event: KeyboardEvent): void {
        event.stopPropagation();

        if ((event.ctrlKey || event.metaKey) && event.code === "KeyZ") {
            return;
        }

        if (this.column?.type === "number") {
            const key = event.key;
            // Block only printable non-numeric characters; allow service keys, shortcuts, digits, decimal, minus
            if (
                key.length === 1 &&
                !event.ctrlKey &&
                !event.metaKey &&
                !event.altKey &&
                !/[0-9.,-]/.test(key)
            ) {
                event.preventDefault();
                return;
            }
        }

        this.editorKeydown.emit(event);
    }

    onEditorBlurInternal(): void {
        this.editorBlur.emit();
    }

    private sanitizeNumberInput(value: string): string {
        const trimmed = value.replace(/\s+/g, "");
        if (!trimmed) return "";
        let normalized = trimmed.replace(/,/g, ".");
        normalized = normalized.replace(/[^0-9.-]/g, "");
        if (normalized.startsWith("-")) {
            normalized = "-" + normalized.slice(1).replace(/-/g, "");
        } else {
            normalized = normalized.replace(/-/g, "");
        }
        const parts = normalized.split(".");
        if (parts.length > 2) {
            normalized = `${parts.shift()}.${parts.join("")}`;
        }
        return normalized;
    }

    get numberValue(): number | null {
        const value = this.displayValue;
        if (value === null || value === undefined || value === "") {
            return null;
        }
        const num = typeof value === "number" ? value : Number(value);
        return Number.isFinite(num) ? num : null;
    }

    private syncContentEditable(): void {
        setTimeout(() => {
            if (!this.isEditing) return;
            if (this.column?.type === "date") return;
            const el = this.contentEditableEl?.nativeElement;
            if (!el) return;
            const next = this.displayValue ?? "";
            const text = typeof next === "string" ? next : String(next);
            if ((el.textContent || "") !== text) {
                el.textContent = text;
            }
            try {
                el.focus();
                const range = document.createRange();
                range.selectNodeContents(el);
                range.collapse(false);
                const selection = window.getSelection();
                if (selection) {
                    selection.removeAllRanges();
                    selection.addRange(range);
                }
            } catch {
                return;
            }
        }, 0);
    }

    private openDatePicker(): void {
        setTimeout(() => {
            if (!this.isEditing || this.column?.type !== "date") return;
            const input = this.dateInput?.nativeElement;
            if (!input) return;
            input.focus();
            this.datePicker?.open();
        }, 0);
    }
}
